def branch_wrapped_visible_cases(
    prefix: str,
) -> tuple[tuple[str, str, str, tuple[str, ...]], ...]:
    return tuple(
        (
            f"{prefix}_{name}",
            code,
            f"branch.transaction.{variant}",
            ("CommitError", *source_chain),
        )
        for name, code, variant, source_chain in VISIBLE_REVISION_CASES
    )


