def visible_revision_fixture_class(
    case: tuple[str, str, str, tuple[str, ...]],
) -> str:
    name, _code, variant, _source_chain = case
    if name == "repository_txn_object_inventory_mismatch":
        return "receipt_semantic_manifest"
    if name == "repository_recovery_receipt_incomplete":
        return "receipt_absent"
    if name == "host_txn_io":
        return "receipt_host_io"
    if variant == "commit.codec.scb":
        return "receipt_envelope"
    if variant == "commit.codec.transaction":
        return "receipt_nested_transaction"
    if variant == "commit.codec.candidate":
        return "receipt_nested_candidate"
    if variant == "commit.codec.candidate_result":
        return "receipt_nested_candidate_result"
    if ".state_root." in variant:
        return "receipt_nested_state_root"
    if ".policy_root." in variant:
        return "receipt_nested_policy_root"
    if name == "object_store_object_not_found":
        return "object_absent"
    if name == "object_store_io":
        return "object_host_io"
    if variant == "commit.store":
        return "object_bytes"
    fail(f"visible revision fixture class is undefined: {case!r}")


def visible_revision_probe_class(fixture_class: str) -> str:
    if fixture_class in {
        "receipt_envelope",
        "receipt_nested_transaction",
        "receipt_nested_candidate",
        "receipt_nested_candidate_result",
        "receipt_nested_state_root",
        "receipt_nested_policy_root",
    }:
        return "import_transaction_receipt_error"
    if fixture_class == "receipt_semantic_manifest":
        return "import_receipt_then_verify_revision"
    if fixture_class == "receipt_absent":
        return "verify_absent_revision_receipt"
    if fixture_class == "receipt_host_io":
        return "path_bound_receipt_read_injection"
    if fixture_class in {"object_bytes", "object_absent"}:
        return "object_store_read_error"
    if fixture_class == "object_host_io":
        return "path_bound_object_read_injection"
    fail(f"visible revision probe class is undefined: {fixture_class}")


def visible_revision_fixture_spec(
    row_id: str,
    code: str,
    variant: str,
    source_chain: tuple[str, ...],
    role: str,
    visible_case: tuple[str, str, str, tuple[str, ...]],
) -> CorruptionFixtureSpec:
    selector = visible_case[0]
    fixture_class = visible_revision_fixture_class(visible_case)
    is_object = fixture_class.startswith("object_")
    identity_recipes = {
        "ACCEPTED_REVISION": "accepted_pointer_transaction_id",
        "BRANCH_HEAD_REVISION": "decoded_ref_head_transaction_id",
        "BRANCH_ORIGIN_REVISION": "decoded_origin_transaction_id",
    }
    distinct_roles = {
        "ACCEPTED_REVISION": (),
        "BRANCH_HEAD_REVISION": ("BRANCH_ORIGIN_REVISION",),
        "BRANCH_ORIGIN_REVISION": ("BRANCH_HEAD_REVISION",),
    }
    required_facts = VISIBLE_REVISION_BASE_FACTS
    if role != "ACCEPTED_REVISION":
        required_facts = (*required_facts, *VISIBLE_REVISION_BRANCH_FACTS)
        if is_object:
            required_facts = (
                *required_facts,
                *VISIBLE_REVISION_BRANCH_OBJECT_FACTS,
            )
    return CorruptionFixtureSpec(
        owner_source=(
            "crates/sley-txn/src/repository.rs"
            if row_id == "COR-06"
            else "crates/sley-repo/src/refs.rs"
        ),
        fixture_family="visible_revision",
        recovery_operation=(
            "transaction_recovery" if row_id == "COR-06" else "ref_recovery"
        ),
        expected_code=code,
        expected_variant=variant,
        expected_source_chain=source_chain,
        target_role=role,
        artifact_role="revision_object" if is_object else "revision_receipt",
        identity_recipe=identity_recipes[role],
        path_recipe=(
            "role_changed_object_path" if is_object else "role_receipt_path"
        ),
        corrupter_class=fixture_class,
        probe_class=visible_revision_probe_class(fixture_class),
        selector=selector,
        required_facts=required_facts,
        distinct_from_roles=distinct_roles[role],
    )


