class FixtureRender(NamedTuple):
    statements: tuple[str, ...]
    fact_assertions: dict[str, str]
    helper_ids: tuple[str, ...]


def corruption_fixture_label(key: tuple[str, str, str]) -> str:
    return "s20-530-" + "-".join(
        component.lower().replace("_", "-") for component in key
    )


def tagged_fixture_eq(fact: str, left: str, right: str) -> str:
    tag = json.dumps(fact)
    return f"::core::assert_eq!(({tag}, {left}), ({tag}, {right}));"


def tagged_fixture_ne(fact: str, left: str, right: str) -> str:
    tag = json.dumps(fact)
    return f"::core::assert_ne!(({tag}, {left}), ({tag}, {right}));"


def corruption_fixture_is_absent(spec: CorruptionFixtureSpec) -> bool:
    return spec.corrupter_class in {
        "receipt_absent",
        "object_absent",
        "selected_origin_absent",
    }


def corruption_fixture_expected_kind(spec: CorruptionFixtureSpec) -> str:
    if corruption_fixture_is_absent(spec):
        return "absent"
    if spec.corrupter_class == "non_regular_inventory_entry":
        return "non_regular"
    return "regular"


