class LimitEventSpec(NamedTuple):
    site: tuple[str, str, str]
    source_kind: str
    source: tuple[str, ...]
    identity: tuple[str, ...]
    charges: tuple[tuple[str, str, str, str], ...]
    retains: tuple[tuple[str, str, str], ...]
    sink: tuple[str, ...]
    bypass_tokens: tuple[str, ...]


LIMIT_EVENT_BYPASS_TOKENS = (
    "+=",
    "saturating_add",
    "wrapping_add",
    "read_dir().collect",
    "collect::<Vec",
)


def limit_unit_source(identity: str, source: str) -> tuple[str, ...]:
    return (f"let {identity} = {source};", "let one = 1_u64;")


def limit_metadata_source(
    path_identifier: str,
    path_source: str,
    error_mapping: str,
    *,
    include_one: bool = False,
) -> tuple[str, ...]:
    statements = [
        f"let {path_identifier} = {path_source};",
        (
            "let metadata = ::std::fs::symlink_metadata(&"
            f"{path_identifier}).map_err({error_mapping})?;"
        ),
        "ensure_recovery_regular_file(&metadata)?;",
        "let metadata_bytes = metadata.len();",
    ]
    if include_one:
        statements.append("let one = 1_u64;")
    return tuple(statements)


def limit_recovery_receipt_metadata_source(
    *,
    wrap_verification: bool,
) -> tuple[str, ...]:
    if wrap_verification:
        return (
            "let receipt_path = self.receipt_path_readonly(transaction_id)"
            ".map_err(RecoveryAncestryError::Verification)?;",
            (
                "let metadata = recovery_receipt_metadata(&receipt_path)"
                ".map_err(RecoveryAncestryError::Verification)?;"
            ),
            "let metadata_bytes = metadata.len();",
        )
    return (
        "let receipt_path = self.receipt_path_readonly(transaction_id)?;",
        "let metadata = recovery_receipt_metadata(&receipt_path)?;",
        "let metadata_bytes = metadata.len();",
    )


def limit_recovery_receipt_sink(*, wrap_verification: bool) -> tuple[str, ...]:
    if wrap_verification:
        return (
            "let receipt = self.read_recovery_receipt(&receipt_path)"
            ".map_err(RecoveryAncestryError::Verification)?;",
        )
    return ("let receipt = self.read_recovery_receipt(&receipt_path)?;",)


def limit_recovery_binding_sink(*, wrap_verification: bool) -> tuple[str, ...]:
    if wrap_verification:
        return (
            "inspect_recovery_binding(&binding)"
            ".map_err(RecoveryAncestryError::Verification)?;",
        )
    return ("inspect_recovery_binding(&binding)?;",)


def limit_bounded_object_source(
    object_source: str,
    *,
    wrap_store_error: bool = False,
) -> tuple[str, ...]:
    object_length = (
        "let object_bytes = self.object_store.bounded_object_len(object_id)"
        ".map_err(CommitError::from)"
        ".map_err(RecoveryAncestryError::Verification)?;"
        if wrap_store_error
        else "let object_bytes = self.object_store.bounded_object_len(object_id)?;"
    )
    return (
        f"let object_id = {object_source};",
        object_length,
        "let one = 1_u64;",
    )


def limit_cached_work_source() -> tuple[str, ...]:
    return (
        "let cache_key = transaction_id;",
        (
            "let cached_work = recovery_cache.get(&cache_key)"
            '.expect("verified recovery cache entry");'
        ),
        "let cached_receipt_bytes = cached_work.receipt_bytes;",
        "let cached_binding_visits = cached_work.binding_visits;",
        "let cached_object_verifications = cached_work.object_verifications;",
        "let cached_object_bytes = cached_work.object_bytes;",
    )


def limit_event(
    path: str,
    owner: str,
    function: str,
    source_kind: str,
    source: tuple[str, ...],
    identity: tuple[str, ...],
    charges: tuple[tuple[str, str, str, str], ...],
    sink: tuple[str, ...],
    *,
    retains: tuple[tuple[str, str, str], ...] = (),
) -> LimitEventSpec:
    return LimitEventSpec(
        site=(path, owner, function),
        source_kind=source_kind,
        source=source,
        identity=identity,
        charges=charges,
        retains=retains,
        sink=sink,
        bypass_tokens=LIMIT_EVENT_BYPASS_TOKENS,
    )


