MultifaultKey = tuple[str, str, str | None]


class FaultOverlay(NamedTuple):
    role: str
    identity_recipe: str
    path_recipe: str
    corrupter_class: str
    probe_class: str
    required_facts: tuple[str, ...]


class ErrorAuthority(NamedTuple):
    kind: str
    code: str | None
    variant: str
    source_chain: tuple[str, ...]
    fields: tuple[tuple[str, int], ...] = ()


class CycleEpochContract(NamedTuple):
    epoch_budget: int
    operation_1_claims: int
    operation_1_edge_counts: tuple[int, int]
    operation_2_claims: int
    operation_2_edge_counts: tuple[int, int]
    primary_fault_node: str | None


class MultifaultOverlaySpec(NamedTuple):
    owner_source: str
    recovery_operation: str
    fresh_fixture_recipe: str
    receiver_recipe: str
    guard_recipe: str
    primary: FaultOverlay
    secondary: FaultOverlay
    distinctness_class: str
    winner: ErrorAuthority
    loser: ErrorAuthority
    repair_class: str
    operation_1_profile: str
    operation_2_profile: str
    cycle_epochs: CycleEpochContract | None = None


class RecoveryProvenanceSpec(NamedTuple):
    owner_source: str
    fixture_family: str
    guard_relation: str
    pointer_role: str
    topology_recipe: str
