def recovery_provenance_required_facts(
    fixture_family: str,
    guard_relation: str,
    canary_roles: tuple[str, ...],
    extra_facts: tuple[str, ...] = (),
) -> tuple[str, ...]:
    if fixture_family == "guard_preflight":
        base = (
            RECOVERY_PROVENANCE_SAME_ROOT_GUARD_FACTS
            if guard_relation == "same_root_shared"
            else RECOVERY_PROVENANCE_WRONG_ROOT_GUARD_FACTS
        )
    elif fixture_family == "deep_missing_ancestry":
        base = RECOVERY_PROVENANCE_DEEP_MISSING_FACTS
    elif fixture_family == "logical_cycle":
        base = RECOVERY_PROVENANCE_CYCLE_FACTS
    else:
        fail(f"unknown recovery provenance fixture family {fixture_family!r}")
    canary_facts = tuple(
        f"{role}_{suffix}"
        for role in canary_roles
        for suffix in RECOVERY_PROVENANCE_CANARY_FACT_SUFFIXES
    )
    return (*base, *extra_facts, *canary_facts)


def recovery_provenance_spec(
    owner_source: str,
    fixture_family: str,
    guard_relation: str,
    pointer_role: str,
    topology_recipe: str,
    fault_role: str,
    canary_roles: tuple[str, ...] = (),
    snapshot_roots: tuple[str, ...] = ("OWNER_ROOT",),
    extra_facts: tuple[str, ...] = (),
) -> RecoveryProvenanceSpec:
    return RecoveryProvenanceSpec(
        owner_source=owner_source,
        fixture_family=fixture_family,
        guard_relation=guard_relation,
        pointer_role=pointer_role,
        topology_recipe=topology_recipe,
        fault_role=fault_role,
        canary_roles=canary_roles,
        snapshot_roots=snapshot_roots,
        required_facts=recovery_provenance_required_facts(
            fixture_family,
            guard_relation,
            canary_roles,
            extra_facts,
        ),
    )


