def recovery_provenance_record(
    case_id: tuple[str, str | None],
    spec: RecoveryProvenanceSpec,
) -> tuple[object, ...]:
    return (*case_id, *spec)


def recovery_provenance_plan_sha256(
    case_id: tuple[str, str | None],
    spec: RecoveryProvenanceSpec | None = None,
) -> str:
    selected = RECOVERY_PROVENANCE_SPECS[case_id] if spec is None else spec
    return canonical_json_sha256(recovery_provenance_record(case_id, selected))


def recovery_provenance_specs_sha256(
    specs: dict[tuple[str, str | None], RecoveryProvenanceSpec] = (
        RECOVERY_PROVENANCE_SPECS
    ),
) -> str:
    return canonical_json_sha256(
        tuple(recovery_provenance_record(case_id, spec) for case_id, spec in specs.items())
    )


