def tagged_provenance_eq(fact: str, left: str, right: str) -> str:
    tag = json.dumps(fact)
    return f"::core::assert_eq!(({tag}, {left}), ({tag}, {right}));"


def tagged_provenance_ne(fact: str, left: str, right: str) -> str:
    tag = json.dumps(fact)
    return f"::core::assert_ne!(({tag}, {left}), ({tag}, {right}));"


def tagged_provenance_assert(fact: str, predicate: str) -> str:
    return f"::core::assert!({predicate}, {json.dumps(fact)});"


def recovery_provenance_fact_assertion(
    case_id: tuple[str, str | None],
    spec: RecoveryProvenanceSpec,
    fact: str,
) -> str:
    equality = {
        "canonical_owner_root": (
            "canonical_owner_root.as_path()",
            "::std::fs::canonicalize(owner_root).unwrap().as_path()",
        ),
        "canonical_guard_root": (
            "canonical_guard_root.as_path()",
            "::std::fs::canonicalize(guard_root).unwrap().as_path()",
        ),
        "maintenance_root_equals_canonical_owner": (
            "maintenance.repository_root()",
            "canonical_owner_root.as_path()",
        ),
        "maintenance_root_equals_canonical_guard": (
            "maintenance.repository_root()",
            "canonical_guard_root.as_path()",
        ),
        "direct_target_identity_from_authority": (
            "provenance.direct_target_identity",
            "provenance.authority_target_identity",
        ),
        "direct_target_receipt_path": (
            "provenance.direct_target_receipt_path.as_path()",
            "provenance.expected_direct_target_receipt_path.as_path()",
        ),
        "authority_pointer_unchanged": (
            "authority_pointer_before_snapshot",
            "authority_pointer_after_snapshot",
        ),
        "owner_tree_unchanged": (
            "owner_tree_before_snapshot",
            "owner_tree_after_snapshot",
        ),
        "guard_tree_unchanged": (
            "guard_tree_before_snapshot",
            "guard_tree_after_snapshot",
        ),
        "pointer_decodes_head": (
            "provenance.pointer_identity",
            "provenance.head_identity",
        ),
        "head_parent_is_direct_parent": (
            "provenance.head_parent_identity",
            "provenance.direct_parent_identity",
        ),
        "direct_parent_parent_is_deep_missing": (
            "provenance.direct_parent_parent_identity",
            "provenance.deep_missing_identity",
        ),
        "deep_missing_parent_is_genesis": (
            "provenance.deep_missing_parent_identity",
            "provenance.genesis_identity",
        ),
        "deep_missing_is_depth_two": (
            "provenance.deep_missing_depth",
            "2_u64",
        ),
        "deep_missing_id_derived_from_parent_receipt": (
            "provenance.deep_missing_identity",
            "provenance.derived_deep_missing_identity",
        ),
        "deep_missing_path_from_derived_id": (
            "provenance.deep_missing_receipt_path.as_path()",
            "provenance.derived_deep_missing_receipt_path.as_path()",
        ),
        "genesis_receipt_regular": (
            "provenance.genesis_receipt_kind",
            '"regular"',
        ),
        "direct_parent_receipt_regular": (
            "provenance.direct_parent_receipt_kind",
            '"regular"',
        ),
        "head_receipt_regular": (
            "provenance.head_receipt_kind",
            '"regular"',
        ),
        "pointer_bytes_unchanged": (
            "pointer_before_snapshot.2.as_slice()",
            "pointer_after_snapshot.2.as_slice()",
        ),
        "deep_missing_path_unchanged": (
            "deep_missing_before_snapshot",
            "deep_missing_after_snapshot",
        ),
        "origin_decodes_genesis": (
            "provenance.origin_identity",
            "provenance.genesis_identity",
        ),
        "ref_decodes_head": (
            "provenance.ref_identity",
            "provenance.head_identity",
        ),
        "ref_decodes_left": (
            "provenance.ref_identity",
            "provenance.left_identity",
        ),
        "origin_direct_claim_verified": (
            "provenance.origin_claim.clone()",
            "provenance.verified_origin_claim.clone()",
        ),
        "head_direct_claim_verified": (
            "provenance.head_claim.clone()",
            "provenance.verified_head_claim.clone()",
        ),
        "left_direct_claim_verified": (
            "provenance.left_claim.clone()",
            "provenance.verified_left_claim.clone()",
        ),
        "pointer_decodes_left": (
            "provenance.pointer_identity",
            "provenance.left_identity",
        ),
        "durable_left_parent_is_right": (
            "provenance.durable_left_parents.as_slice()",
            "[provenance.right_identity]",
        ),
        "durable_right_parent_is_genesis": (
            "provenance.durable_right_parents.as_slice()",
            "[provenance.genesis_identity]",
        ),
        "logical_left_parent_is_right": (
            "provenance.logical_left_parents.as_slice()",
            "[provenance.right_identity]",
        ),
        "logical_right_parent_is_left": (
            "provenance.logical_right_parents.as_slice()",
            "[provenance.left_identity]",
        ),
        "observed_left_durable_and_logical_edges": (
            "cycle_observations[0].clone()",
            "(provenance.left_identity, vec![provenance.right_identity], "
            "vec![provenance.right_identity])",
        ),
        "observed_right_durable_and_logical_edges": (
            "cycle_observations[1].clone()",
            "(provenance.right_identity, vec![provenance.genesis_identity], "
            "vec![provenance.left_identity])",
        ),
        "plan_consumed_exactly_once_per_node": (
            "provenance.plan_consumption_counts.as_slice()",
            "[(provenance.left_identity, 1_u64), "
            "(provenance.right_identity, 1_u64)]",
        ),
        "plan_installed_on_owner_repository": (
            "provenance.plan_owner_root.as_path()",
            "canonical_owner_root.as_path()",
        ),
    }
    inequality = {
        "canonical_roots_distinct": (
            "canonical_owner_root.as_path()",
            "canonical_guard_root.as_path()",
        ),
        "origin_head_ids_distinct": (
            "provenance.origin_identity",
            "provenance.head_identity",
        ),
        "origin_left_ids_distinct": (
            "provenance.origin_identity",
            "provenance.left_identity",
        ),
    }
    predicates = {
        "owner_root_real": (
            "::std::fs::symlink_metadata(owner_root).unwrap().is_dir() && "
            "!::std::fs::symlink_metadata(owner_root).unwrap().file_type().is_symlink()"
        ),
        "guard_root_real": (
            "::std::fs::symlink_metadata(guard_root).unwrap().is_dir() && "
            "!::std::fs::symlink_metadata(guard_root).unwrap().file_type().is_symlink()"
        ),
        "maintenance_is_shared": "!maintenance.is_exclusive()",
        "maintenance_is_exclusive": "maintenance.is_exclusive()",
        "maintenance_covers_owner": "maintenance.covers(owner_root)",
        "maintenance_covers_guard": "maintenance.covers(guard_root)",
        "maintenance_does_not_cover_owner": "!maintenance.covers(owner_root)",
        "direct_target_receipt_absent": (
            "direct_target_receipt_before_snapshot.is_none()"
        ),
        "durable_graph_acyclic": (
            "provenance.durable_left_parents.as_slice() == "
            "[provenance.right_identity] && "
            "provenance.durable_right_parents.as_slice() == "
            "[provenance.genesis_identity]"
        ),
        "maintenance_same_root_exclusive": (
            "maintenance.is_exclusive() && maintenance.covers(owner_root)"
        ),
        "production_core_binding": (
            "::core::matches!(&error, "
            f"{error_variant_pattern(spec.owner_source, error_case_spec(*case_id)[1])})"
        ),
    }
    if fact in equality:
        return tagged_provenance_eq(fact, *equality[fact])
    if fact in inequality:
        return tagged_provenance_ne(fact, *inequality[fact])
    if fact in predicates:
        return tagged_provenance_assert(fact, predicates[fact])
    if fact == "transaction_ids_distinct":
        identities = (
            "[provenance.genesis_identity, provenance.deep_missing_identity, "
            "provenance.direct_parent_identity, provenance.head_identity]"
            if spec.fixture_family == "deep_missing_ancestry"
            else "[provenance.genesis_identity, provenance.left_identity, "
            "provenance.right_identity]"
        )
        expected = "4_usize" if spec.fixture_family == "deep_missing_ancestry" else "3_usize"
        return tagged_provenance_eq(
            fact,
            f"::std::collections::BTreeSet::from({identities}).len()",
            expected,
        )
    if fact == "loser_probe_variant":
        loser_pattern = error_variant_pattern(
            spec.owner_source,
            "commit.transaction",
        )
        return tagged_provenance_assert(
            fact,
            f"::core::matches!(&loser_probe_error, {loser_pattern})",
        )
    if fact == "loser_probe_code":
        return tagged_provenance_eq(
            fact,
            "loser_probe_error.code()",
            '"RECOVERY_RECEIPT_INCOMPLETE"',
        )
    if fact == "deep_missing_receipt_absent":
        return tagged_provenance_assert(
            fact,
            "deep_missing_before_snapshot.is_none()",
        )
    canary = re.fullmatch(
        r"(?P<root>owner|guard)_(?P<role>object_stage|receipt_stage|head_stage|"
        r"origin_stage|ref_stage)_(?P<claim>path_from_root|kind_regular|"
        r"bytes_exact|unchanged)",
        fact,
    )
    if canary is not None:
        name = f"{canary['root']}_{canary['role']}"
        claim = canary["claim"]
        if claim == "path_from_root":
            return tagged_provenance_eq(
                fact,
                f"{name}_path.as_path()",
                f"{canary['root']}_root.join(provenance.{name}_relative_path.clone()).as_path()",
            )
        if claim == "kind_regular":
            return tagged_provenance_eq(
                fact,
                f"{name}_before_snapshot.0",
                '"regular"',
            )
        if claim == "bytes_exact":
            return tagged_provenance_eq(
                fact,
                f"{name}_before_snapshot.2.as_slice()",
                f"provenance.{name}_expected_bytes.as_slice()",
            )
        return tagged_provenance_eq(
            fact,
            f"{name}_before_snapshot",
            f"{name}_after_snapshot",
        )
    fail(f"recovery provenance fact renderer is absent: {case_id!r}/{fact}")


def recovery_provenance_fact_assertions(
    case_id: tuple[str, str | None],
    spec: RecoveryProvenanceSpec | None = None,
) -> dict[str, str]:
    selected = RECOVERY_PROVENANCE_SPECS[case_id] if spec is None else spec
    return {
        fact: recovery_provenance_fact_assertion(case_id, selected, fact)
        for fact in selected.required_facts
    }


