def multifault_overlay_record(
    key: MultifaultKey,
    spec: MultifaultOverlaySpec,
) -> tuple[object, ...]:
    return (key, tuple(zip(MultifaultOverlaySpec._fields, spec)))


def multifault_overlay_registry_sha256(
    registry: tuple[tuple[MultifaultKey, MultifaultOverlaySpec], ...] = (
        MULTIFAULT_OVERLAY_REGISTRY
    ),
) -> str:
    return canonical_json_sha256(
        (
            "sley-s20-530-multifault-overlay-registry-v1",
            tuple(multifault_overlay_record(key, spec) for key, spec in registry),
        )
    )


