def durability_cut_metadata_problem(authority: object) -> str | None:
    if not isinstance(authority, dict) or tuple(authority) != OWNER_SOURCES:
        return "owner source order differs"
    variant_rows: list[str] = []
    helper_rows: list[str] = []
    enum_names: list[str] = []
    variant_names: list[str] = []
    helper_names: list[str] = []
    for relative, definition in authority.items():
        if not isinstance(definition, dict) or tuple(definition) != (
            "enum",
            "variants",
            "helpers",
        ):
            return f"{relative} authority fields/order differ"
        enum_name = definition.get("enum")
        variants = definition.get("variants")
        helpers = definition.get("helpers")
        if not isinstance(enum_name, str) or not enum_name.endswith("DurabilityCut"):
            return f"{relative} enum identity differs"
        if not isinstance(variants, tuple) or not variants:
            return f"{relative} variants are not one nonempty tuple"
        if not isinstance(helpers, tuple) or not helpers:
            return f"{relative} helpers are not one nonempty tuple"
        enum_names.append(enum_name)
        local_variant_rows: list[str] = []
        for variant in variants:
            if (
                not isinstance(variant, tuple)
                or len(variant) != 3
                or not isinstance(variant[0], str)
                or not isinstance(variant[2], str)
            ):
                return f"{relative} has a malformed variant authority"
            name, payload, row_id = variant
            expected_payload = DURABILITY_CUT_PAYLOADS.get(row_id)
            if payload != expected_payload:
                return f"{row_id} selector payload differs"
            variant_names.append(name)
            variant_rows.append(row_id)
            local_variant_rows.append(row_id)
        local_helper_rows: list[str] = []
        for helper in helpers:
            if (
                not isinstance(helper, tuple)
                or len(helper) != 3
                or not isinstance(helper[0], str)
                or not isinstance(helper[1], str)
                or not isinstance(helper[2], tuple)
                or not helper[2]
                or any(not isinstance(row_id, str) for row_id in helper[2])
            ):
                return f"{relative} has a malformed helper authority"
            owner, name, rows = helper
            if owner != "<crate>" and not owner.startswith("impl"):
                return f"{relative} helper owner differs for {name}"
            if not name.endswith("_with_gc_durability_cut") and not name.endswith(
                (
                    "_with_store_durability_cut",
                    "_with_transaction_durability_cut",
                    "_with_native_ref_durability_cut",
                )
            ):
                return f"{relative} helper name differs: {name}"
            helper_names.append(name)
            helper_rows.extend(rows)
            local_helper_rows.extend(rows)
        if len(local_helper_rows) != len(set(local_helper_rows)) or set(
            local_helper_rows
        ) != set(local_variant_rows):
            return f"{relative} helper rows do not partition its variants"
    if tuple(variant_rows) != DURABILITY_CUT_ROWS or len(variant_rows) != 70:
        return "ordered 70-row selector coverage differs"
    if len(helper_rows) != len(set(helper_rows)) or set(helper_rows) != set(
        variant_rows
    ):
        return "helper rows do not partition the 70 selectors"
    for label, values in (
        ("enum", enum_names),
        ("variant", variant_names),
        ("helper", helper_names),
    ):
        if len(values) != len(set(values)):
            return f"{label} identities are not unique"
    return None


def durability_retry_protocol_problem(
    protocols: object,
    expected_digest: object = DURABILITY_RETRY_PROTOCOLS_SHA256,
) -> str | None:
    expected_protocols = (
        "H1_R1",
        "H1_R2",
        "H1_O1",
        "H1_R1_O1",
        "H2_O1",
        "H2_R1",
    )
    if not isinstance(protocols, dict) or tuple(protocols) != expected_protocols:
        return "retry protocol vocabulary/order differs"
    rows: list[str] = []
    for protocol, protocol_rows in protocols.items():
        if (
            not isinstance(protocol_rows, tuple)
            or not protocol_rows
            or any(not isinstance(row_id, str) for row_id in protocol_rows)
        ):
            return f"{protocol} rows are not one nonempty tuple"
        rows.extend(protocol_rows)
    if len(rows) != len(set(rows)):
        return "one non-GC durability row has multiple retry protocols"
    if set(rows) != set(NON_GC_DURABILITY_ROWS):
        return "retry protocols do not cover the exact non-GC durability rows"
    if len(rows) != 62:
        return "retry protocol coverage is not exactly 62 rows"
    double_cut_rows = (*protocols["H2_O1"], *protocols["H2_R1"])
    if len(double_cut_rows) != 14:
        return "two-helper retry protocol coverage is not exactly 14 rows"
    digest = hashlib.sha256(
        json.dumps(protocols, ensure_ascii=True, separators=(",", ":")).encode("utf-8")
    ).hexdigest()
    if not isinstance(expected_digest, str) or digest != expected_digest:
        return "retry protocol canonical digest differs"
    return None


def durability_result_metadata_problem(
    result_rows: object = DURABILITY_RESULT_ROWS,
    result_codes: object = DURABILITY_RESULT_CODES,
    ordinary_calls: object = DURABILITY_ORDINARY_CALLS,
    expected_result_digest: object = DURABILITY_RESULT_ROWS_SHA256,
    expected_ordinary_digest: object = DURABILITY_ORDINARY_CALLS_SHA256,
) -> str | None:
    expected_codes = (
        "STORE_IO",
        "TXN_IO",
        "RECOVERY_RECEIPT_INCOMPLETE",
        "RECOVERY_REF_CAS_INCOMPLETE",
        "REF_IO",
    )
    if not isinstance(result_rows, dict) or tuple(result_rows) != expected_codes:
        return "durability result-code vocabulary/order differs"
    flattened: list[str] = []
    for code, rows in result_rows.items():
        if (
            not isinstance(rows, tuple)
            or not rows
            or any(not isinstance(row_id, str) for row_id in rows)
        ):
            return f"{code} durability rows are not one nonempty tuple"
        flattened.extend(rows)
    if len(flattened) != len(set(flattened)):
        return "one durability row has multiple injected result codes"
    if set(flattened) != set(NON_GC_DURABILITY_ROWS) or len(flattened) != 62:
        return "injected result codes do not cover exactly 62 durability rows"
    expected_result_codes = {
        row_id: code
        for row_id in NON_GC_DURABILITY_ROWS
        for code, rows in result_rows.items()
        if row_id in rows
    }
    if (
        not isinstance(result_codes, dict)
        or tuple(result_codes) != NON_GC_DURABILITY_ROWS
        or result_codes != expected_result_codes
    ):
        return "ordered per-row durability result codes differ"
    ordinary_rows = tuple(
        row_id
        for row_id in NON_GC_DURABILITY_ROWS
        if durability_retry_protocol(row_id).endswith("O1")
    )
    if (
        not isinstance(ordinary_calls, dict)
        or tuple(ordinary_calls) != ordinary_rows
        or any(
            not isinstance(name, str) or re.fullmatch(RUST_IDENTIFIER, name) is None
            for name in ordinary_calls.values()
        )
    ):
        return "ordinary durability retry call coverage/order differs"
    result_digest = hashlib.sha256(
        json.dumps(result_rows, ensure_ascii=True, separators=(",", ":")).encode(
            "utf-8"
        )
    ).hexdigest()
    ordinary_digest = hashlib.sha256(
        json.dumps(ordinary_calls, ensure_ascii=True, separators=(",", ":")).encode(
            "utf-8"
        )
    ).hexdigest()
    if (
        not isinstance(expected_result_digest, str)
        or result_digest != expected_result_digest
    ):
        return "durability result-row canonical digest differs"
    if (
        not isinstance(expected_ordinary_digest, str)
        or ordinary_digest != expected_ordinary_digest
    ):
        return "ordinary durability retry canonical digest differs"
    return None


def durability_retry_protocol(row_id: str) -> str:
    matches = tuple(
        protocol
        for protocol, protocol_rows in DURABILITY_RETRY_PROTOCOLS.items()
        if row_id in protocol_rows
    )
    if len(matches) != 1:
        fail(f"{row_id} lacks one exact non-GC durability retry protocol")
    return matches[0]


def durability_cut_call_count(row_id: str) -> int:
    if row_id.startswith(("GCW-", "GC-")):
        return 1
    return 2 if durability_retry_protocol(row_id).startswith("H2_") else 1


def durability_operation_keys(row_id: str) -> tuple[str, ...]:
    protocol = durability_retry_protocol(row_id)
    keys = ["first_fault"]
    if protocol.startswith("H2_"):
        keys.append("second_fault")
    if "R1" in protocol:
        keys.append("first_recovery")
    if "R2" in protocol:
        keys.append("second_recovery")
    if protocol.endswith("O1"):
        keys.append("ordinary_retry")
    return tuple(keys)


def durability_recovery_call(row_id: str) -> str:
    if row_id.startswith(("OBJ-", "OLAY-")):
        return "recover_staged"
    if row_id.startswith(("TOBJ-", "TXN-", "HEAD-", "GEN-", "RCV-")):
        return "recover"
    if row_id.startswith(("RLAY-", "REF-")):
        return "recover_refs"
    fail(f"{row_id} lacks one exact normal recovery call")


def durability_result_projection(row_id: str, error_name: str) -> str:
    if row_id.startswith(("OBJ-", "OLAY-")):
        return f"{error_name}.symbol()"
    return f"{error_name}.code()"


