def fail(message: str) -> None:
    print(f"S20-530 crash-recovery check failed: {message}", file=sys.stderr)
    raise SystemExit(1)


def strict_json_object(payload: bytes, label: str) -> dict[str, object]:
    def object_from_pairs(pairs: list[tuple[str, object]]) -> dict[str, object]:
        value: dict[str, object] = {}
        for key, item in pairs:
            if key in value:
                raise ValueError(f"{label} contains duplicate JSON key {key!r}")
            value[key] = item
        return value

    def reject_constant(value: str) -> object:
        raise ValueError(f"{label} contains non-finite JSON number {value}")

    def finite_float(value: str) -> float:
        parsed = float(value)
        if not math.isfinite(parsed):
            raise ValueError(f"{label} contains non-finite JSON number {value}")
        return parsed

    try:
        text = payload.decode("utf-8", errors="strict")
        value = json.loads(
            text,
            object_pairs_hook=object_from_pairs,
            parse_constant=reject_constant,
            parse_float=finite_float,
        )
    except (UnicodeDecodeError, json.JSONDecodeError, ValueError) as error:
        raise ValueError(f"cannot parse {label}: {error}") from error
    if not isinstance(value, dict):
        raise ValueError(f"{label} must contain one JSON object")
    return value


def read_bounded_repository_file(
    path: Path,
    *,
    root: Path = ROOT,
    size_limit: int = JSON_FILE_LIMIT_BYTES,
) -> bytes:
    try:
        relative = path.relative_to(root)
    except ValueError:
        raise ValueError(f"repository file escapes its root: {path}") from None
    if not relative.parts or any(part in {"", ".", ".."} for part in relative.parts):
        raise ValueError(f"repository file has an unsafe path: {path}")
    if size_limit < 0:
        raise ValueError("repository file size limit must be non-negative")

    directory_flags = os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW | os.O_CLOEXEC
    descriptor = os.open(root, directory_flags)
    try:
        root_metadata = os.fstat(descriptor)
        if problem := authority_directory_problem(root_metadata, str(root)):
            raise ValueError(problem)
        traversed = root
        for part in relative.parts[:-1]:
            child = os.open(part, directory_flags, dir_fd=descriptor)
            traversed /= part
            try:
                metadata = os.fstat(child)
                if problem := authority_directory_problem(metadata, str(traversed)):
                    raise ValueError(problem)
            except BaseException:
                os.close(child)
                raise
            os.close(descriptor)
            descriptor = child

        file_descriptor = os.open(
            relative.parts[-1],
            os.O_RDONLY | os.O_NOFOLLOW | os.O_NONBLOCK | os.O_CLOEXEC,
            dir_fd=descriptor,
        )
        try:
            before = os.fstat(file_descriptor)
            mode = stat.S_IMODE(before.st_mode)
            if not stat.S_ISREG(before.st_mode):
                raise ValueError(f"repository file is not regular: {relative}")
            if before.st_uid != os.geteuid():
                raise ValueError(f"repository file has the wrong uid: {relative}")
            if before.st_gid != os.getegid():
                raise ValueError(f"repository file has the wrong gid: {relative}")
            if mode & stat.S_IWOTH:
                raise ValueError(f"repository file is world-writable: {relative}")
            if mode & 0o111:
                raise ValueError(f"repository JSON file is executable: {relative}")
            if not mode & stat.S_IRUSR:
                raise ValueError(f"repository file is not owner-readable: {relative}")
            if before.st_size > size_limit:
                raise ValueError(
                    f"repository file exceeds {size_limit} bytes: {relative}"
                )
            content = bytearray()
            while True:
                chunk = os.read(file_descriptor, size_limit + 1 - len(content))
                if not chunk:
                    break
                content.extend(chunk)
                if len(content) > size_limit:
                    raise ValueError(
                        f"repository file exceeds {size_limit} bytes: {relative}"
                    )
            after = os.fstat(file_descriptor)
            stable_fields = (
                "st_dev",
                "st_ino",
                "st_mode",
                "st_uid",
                "st_gid",
                "st_size",
                "st_mtime_ns",
                "st_ctime_ns",
            )
            if any(
                getattr(before, field) != getattr(after, field)
                for field in stable_fields
            ):
                raise ValueError(f"repository file changed while read: {relative}")
            if len(content) != before.st_size:
                raise ValueError(
                    f"repository file length differs from metadata: {relative}"
                )
            return bytes(content)
        finally:
            os.close(file_descriptor)
    finally:
        os.close(descriptor)


def load_json(path: Path) -> dict[str, object]:
    label = str(path.relative_to(ROOT))
    try:
        return strict_json_object(read_bounded_repository_file(path), label)
    except (OSError, ValueError) as error:
        fail(f"cannot load {label}: {error}")


def exact_json_scalar_equal(actual: object, expected: object) -> bool:
    if type(expected) not in {bool, int, str, type(None)}:
        return False
    return type(actual) is type(expected) and actual == expected


def file_sha256(path: Path) -> str:
    try:
        return hashlib.sha256(path.read_bytes()).hexdigest()
    except OSError as error:
        fail(f"cannot hash {path.relative_to(ROOT)}: {error}")


def repository_file_sha256(path: Path) -> str:
    try:
        return hashlib.sha256(read_bounded_repository_file(path)).hexdigest()
    except (OSError, ValueError) as error:
        fail(f"cannot hash {path.relative_to(ROOT)}: {error}")


def canonical_json_sha256(value: object) -> str:
    encoded = json.dumps(
        value,
        ensure_ascii=False,
        separators=(",", ":"),
        allow_nan=False,
    ).encode("utf-8")
    return hashlib.sha256(encoded).hexdigest()


def review_payload_sha256(evidence: dict[str, object]) -> str:
    return canonical_json_sha256(
        {key: value for key, value in evidence.items() if key != "reviews"}
    )


def authority_mode(metadata: os.stat_result) -> str:
    return f"{stat.S_IMODE(metadata.st_mode):04o}"


def authority_directory_problem(metadata: os.stat_result, label: str) -> str | None:
    if not stat.S_ISDIR(metadata.st_mode):
        return f"{label} is not a real directory"
    if metadata.st_uid != os.geteuid():
        return f"{label} is not owned by the validation uid"
    if metadata.st_gid != os.getegid():
        return f"{label} is not owned by the validation gid"
    if metadata.st_mode & stat.S_IWOTH:
        return f"{label} is world-writable"
    return None


def open_authority_directory(
    name: str | Path,
    label: str,
    *,
    directory_fd: int | None = None,
) -> tuple[int, os.stat_result]:
    flags = os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW | os.O_CLOEXEC
    try:
        descriptor = os.open(name, flags, dir_fd=directory_fd)
        metadata = os.fstat(descriptor)
    except OSError:
        raise
    if problem := authority_directory_problem(metadata, label):
        os.close(descriptor)
        raise ValueError(problem)
    return descriptor, metadata


def read_authority_file(
    directory_fd: int,
    name: str,
    label: str,
    expected: bytes,
) -> dict[str, object]:
    flags = os.O_RDONLY | os.O_NOFOLLOW | os.O_NONBLOCK | os.O_CLOEXEC
    descriptor = os.open(name, flags, dir_fd=directory_fd)
    try:
        before = os.fstat(descriptor)
        if not stat.S_ISREG(before.st_mode):
            raise ValueError(f"{label} is not a regular file")
        if before.st_uid != os.geteuid():
            raise ValueError(f"{label} is not owned by the validation uid")
        if before.st_gid != os.getegid():
            raise ValueError(f"{label} is not owned by the validation gid")
        if before.st_mode & stat.S_IWOTH:
            raise ValueError(f"{label} is world-writable")
        if before.st_size > GIT_AUTHORITY_FILE_LIMIT_BYTES:
            raise ValueError(f"{label} exceeds the authority size limit")
        content = bytearray()
        while True:
            chunk = os.read(
                descriptor,
                GIT_AUTHORITY_FILE_LIMIT_BYTES + 1 - len(content),
            )
            if not chunk:
                break
            content.extend(chunk)
            if len(content) > GIT_AUTHORITY_FILE_LIMIT_BYTES:
                raise ValueError(f"{label} exceeds the authority size limit")
        after = os.fstat(descriptor)
        stable_fields = (
            "st_dev",
            "st_ino",
            "st_mode",
            "st_uid",
            "st_gid",
            "st_size",
            "st_mtime_ns",
            "st_ctime_ns",
        )
        if any(
            getattr(before, field) != getattr(after, field) for field in stable_fields
        ):
            raise ValueError(f"{label} changed while it was read")
        if len(content) != before.st_size:
            raise ValueError(f"{label} length differs from its metadata")
        if bytes(content) != expected:
            raise ValueError(f"{label} bytes differ from the frozen safe value")
        return {
            "uid": before.st_uid,
            "gid": before.st_gid,
            "mode": authority_mode(before),
            "sha256": hashlib.sha256(content).hexdigest(),
        }
    finally:
        os.close(descriptor)


def require_absent_authority_entry(directory_fd: int, name: str, label: str) -> None:
    try:
        os.stat(name, dir_fd=directory_fd, follow_symlinks=False)
    except FileNotFoundError:
        return
    except OSError as error:
        raise ValueError(f"cannot inspect {label}: {error}") from error
    raise ValueError(f"forbidden Git local authority exists: {label}")


def inspect_git_local_authority(
    root: Path = ROOT,
) -> tuple[dict[str, object] | None, str | None]:
    descriptors: list[int] = []
    try:
        root_fd, root_metadata = open_authority_directory(root, "repository root")
        descriptors.append(root_fd)
        git_fd, git_metadata = open_authority_directory(
            ".git", "Git directory", directory_fd=root_fd
        )
        descriptors.append(git_fd)
        info_fd, info_metadata = open_authority_directory(
            "info", "Git info directory", directory_fd=git_fd
        )
        descriptors.append(info_fd)
        objects_fd, objects_metadata = open_authority_directory(
            "objects", "Git objects directory", directory_fd=git_fd
        )
        descriptors.append(objects_fd)
        objects_info_fd, objects_info_metadata = open_authority_directory(
            "info", "Git objects/info directory", directory_fd=objects_fd
        )
        descriptors.append(objects_info_fd)
        refs_fd, refs_metadata = open_authority_directory(
            "refs", "Git refs directory", directory_fd=git_fd
        )
        descriptors.append(refs_fd)

        config = read_authority_file(
            git_fd, "config", "Git local config", GIT_LOCAL_CONFIG_BYTES
        )
        exclude = read_authority_file(
            info_fd, "exclude", "Git info/exclude", GIT_INFO_EXCLUDE_BYTES
        )
        for directory_fd, name, label in (
            (git_fd, "config.worktree", "config.worktree"),
            (info_fd, "attributes", "info/attributes"),
            (info_fd, "grafts", "info/grafts"),
            (git_fd, "modules", "modules"),
            (objects_info_fd, "alternates", "objects/info/alternates"),
            (
                objects_info_fd,
                "http-alternates",
                "objects/info/http-alternates",
            ),
            (refs_fd, "replace", "refs/replace"),
            (git_fd, "shallow", "shallow"),
        ):
            require_absent_authority_entry(directory_fd, name, label)

        return (
            {
                "contract": GIT_LOCAL_AUTHORITY_CONTRACT,
                "owner_uid": os.geteuid(),
                "owner_gid": os.getegid(),
                "root_mode": authority_mode(root_metadata),
                "git_dir_mode": authority_mode(git_metadata),
                "config": config,
                "info_dir_mode": authority_mode(info_metadata),
                "info_exclude": exclude,
                "objects_dir_mode": authority_mode(objects_metadata),
                "objects_info_dir_mode": authority_mode(objects_info_metadata),
                "refs_dir_mode": authority_mode(refs_metadata),
                "absent": list(GIT_LOCAL_AUTHORITY_ABSENT),
            },
            None,
        )
    except (OSError, ValueError) as error:
        return None, str(error)
    finally:
        for descriptor in reversed(descriptors):
            os.close(descriptor)


def git_local_authority_record_problem(record: object) -> str | None:
    fields = (
        "contract",
        "owner_uid",
        "owner_gid",
        "root_mode",
        "git_dir_mode",
        "config",
        "info_dir_mode",
        "info_exclude",
        "objects_dir_mode",
        "objects_info_dir_mode",
        "refs_dir_mode",
        "absent",
    )
    if not isinstance(record, dict) or tuple(record) != fields:
        return "Git local-authority fields/order differ"
    if record.get("contract") != GIT_LOCAL_AUTHORITY_CONTRACT:
        return "Git local-authority contract differs"
    owner_uid = record.get("owner_uid")
    if type(owner_uid) is not int or owner_uid < 0:
        return "Git local-authority owner uid is malformed"
    owner_gid = record.get("owner_gid")
    if type(owner_gid) is not int or owner_gid < 0:
        return "Git local-authority owner gid is malformed"
    for field in (
        "root_mode",
        "git_dir_mode",
        "info_dir_mode",
        "objects_dir_mode",
        "objects_info_dir_mode",
        "refs_dir_mode",
    ):
        mode = record.get(field)
        if (
            not isinstance(mode, str)
            or re.fullmatch(r"0[0-7]{3}", mode) is None
            or int(mode, 8) & stat.S_IWOTH
        ):
            return f"Git local-authority {field} is unsafe"
    for field, expected in (
        ("config", GIT_LOCAL_CONFIG_BYTES),
        ("info_exclude", GIT_INFO_EXCLUDE_BYTES),
    ):
        descriptor = record.get(field)
        if not isinstance(descriptor, dict) or tuple(descriptor) != (
            "uid",
            "gid",
            "mode",
            "sha256",
        ):
            return f"Git local-authority {field} descriptor differs"
        if not exact_json_scalar_equal(descriptor.get("uid"), owner_uid):
            return f"Git local-authority {field} uid differs"
        if not exact_json_scalar_equal(descriptor.get("gid"), owner_gid):
            return f"Git local-authority {field} gid differs"
        mode = descriptor.get("mode")
        if (
            not isinstance(mode, str)
            or re.fullmatch(r"0[0-7]{3}", mode) is None
            or int(mode, 8) & stat.S_IWOTH
        ):
            return f"Git local-authority {field} mode is unsafe"
        if descriptor.get("sha256") != hashlib.sha256(expected).hexdigest():
            return f"Git local-authority {field} digest differs"
    if record.get("absent") != list(GIT_LOCAL_AUTHORITY_ABSENT):
        return "Git local-authority absent-path contract differs"
    return None


def git_local_authority() -> dict[str, object]:
    record, problem = inspect_git_local_authority()
    if problem is not None or record is None:
        fail(f"unsafe Git local authority: {problem}")
    if record_problem := git_local_authority_record_problem(record):
        fail(record_problem)
    return record


def git_bytes(*arguments: str) -> bytes:
    authority_before = git_local_authority()
    result = subprocess.run(
        (str(GIT), *arguments),
        cwd=ROOT,
        check=False,
        stdout=subprocess.PIPE,
        stderr=subprocess.PIPE,
        env=GIT_ENVIRONMENT,
    )
    authority_after = git_local_authority()
    if authority_after != authority_before:
        fail(f"Git local authority changed during git {' '.join(arguments)}")
    if result.returncode != 0:
        detail = result.stderr.decode("utf-8", errors="replace").strip()
        fail(f"git {' '.join(arguments)} failed: {detail}")
    return result.stdout


def git_text(*arguments: str) -> str:
    return git_bytes(*arguments).decode("utf-8", errors="strict").strip()


def checker_contract_sha256() -> str:
    source = Path(__file__).resolve().read_text(encoding="utf-8")
    canonical, replacements = re.subn(
        r'^CHECKER_CONTRACT_SHA256 = "[^"]+"$',
        'CHECKER_CONTRACT_SHA256 = "<SELF>"',
        source,
        count=1,
        flags=re.MULTILINE,
    )
    if replacements != 1:
        fail("checker self-digest field is not unique")
    return hashlib.sha256(canonical.encode("utf-8")).hexdigest()


def current_contract_hashes() -> dict[str, str]:
    return {
        "matrix_rows_sha256": MATRIX_ROWS_SHA256,
        "spec_sha256": repository_file_sha256(SPEC),
        "adr_sha256": repository_file_sha256(ADR),
        "checker_sha256": repository_file_sha256(Path(__file__).resolve()),
        "checker_contract_sha256": checker_contract_sha256(),
        "runner_sha256": repository_file_sha256(RUNNER),
    }


def require_frozen_contract_integrity() -> dict[str, str]:
    if any(
        value == "DRAFT"
        for value in (
            FROZEN_SPEC_SHA256,
            FROZEN_ADR_SHA256,
            FROZEN_RUNNER_SHA256,
            CHECKER_CONTRACT_SHA256,
        )
    ):
        fail("S20-530 contract hashes are not sealed")
    expected = {
        "spec_sha256": FROZEN_SPEC_SHA256,
        "adr_sha256": FROZEN_ADR_SHA256,
        "runner_sha256": FROZEN_RUNNER_SHA256,
        "checker_contract_sha256": CHECKER_CONTRACT_SHA256,
    }
    current = current_contract_hashes()
    for field, value in expected.items():
        if current[field] != value:
            fail(f"frozen {field} differs")
    return current


def validation_log_relative(prefix: str, index: int, command: str) -> str:
    slug = re.sub(r"[^a-z0-9]+", "-", command.lower()).strip("-")[:72]
    return f"{VALIDATION_LOG_PREFIX}{prefix}-{index:02d}-{slug}.log"


def expected_validation_log_paths() -> frozenset[str]:
    return frozenset(
        {
            *(
                validation_log_relative("test-list", index, command)
                for index, command in enumerate(TEST_LIST_COMMANDS, start=1)
            ),
            *(
                validation_log_relative("tier2", index, command)
                for index, command in enumerate(TIER_2_COMMANDS, start=1)
            ),
        }
    )


def is_validation_output_path(relative: str) -> bool:
    return relative in OUTPUT_EXACT_PATHS or relative in expected_validation_log_paths()


def regular_input_descriptor(mode: int, content: bytes) -> dict[str, str]:
    return {
        "kind": "regular",
        "mode": f"{stat.S_IMODE(mode):04o}",
        "sha256": hashlib.sha256(content).hexdigest(),
    }


def workspace_input_kind_problem(mode: int) -> str | None:
    if stat.S_ISREG(mode):
        return None
    if stat.S_ISLNK(mode):
        return "symlink"
    return "non-regular"


def workspace_input_hashes() -> dict[str, dict[str, str]]:
    raw = git_bytes("ls-files", "-z", "--cached", "--others", "--exclude-standard")
    relatives = sorted({os.fsdecode(value) for value in raw.split(b"\0") if value})
    output: dict[str, dict[str, str]] = {}
    for relative in relatives:
        pure = Path(relative)
        if pure.is_absolute() or ".." in pure.parts:
            fail(f"workspace input path escapes the repository: {relative!r}")
        path = ROOT / pure
        try:
            metadata = path.lstat()
        except OSError as error:
            fail(f"cannot inspect workspace input {relative}: {error}")
        kind_problem = workspace_input_kind_problem(metadata.st_mode)
        if kind_problem is not None:
            if kind_problem == "symlink":
                fail(f"workspace input symlinks are forbidden: {relative}")
            fail(f"workspace input is not a regular file: {relative}")
        if is_validation_output_path(relative):
            continue
        if kind_problem is None:
            try:
                descriptor = regular_input_descriptor(
                    metadata.st_mode, path.read_bytes()
                )
            except OSError as error:
                fail(f"cannot hash workspace input {relative}: {error}")
        output[relative] = descriptor
    return output


def commit_input_hashes(revision: str) -> dict[str, dict[str, str]]:
    raw = git_bytes("ls-tree", "-r", "-z", "--full-tree", revision)
    output: dict[str, dict[str, str]] = {}
    for record in raw.split(b"\0"):
        if not record:
            continue
        try:
            metadata, encoded_path = record.split(b"\t", 1)
            mode, kind, object_id = metadata.decode("ascii").split(" ")
            relative = os.fsdecode(encoded_path)
        except (UnicodeDecodeError, ValueError) as error:
            fail(f"cannot parse Git tree input record: {error}")
        if kind != "blob" or mode not in {"100644", "100755"}:
            fail(f"Git tree input is not a regular file: {relative} ({mode} {kind})")
        if is_validation_output_path(relative):
            continue
        content = git_bytes("cat-file", "blob", object_id)
        output[relative] = regular_input_descriptor(
            stat.S_IFREG | (0o755 if mode == "100755" else 0o644), content
        )
    return output


def index_flag_problems() -> tuple[str, ...]:
    problems: list[str] = []
    for record in git_bytes("ls-files", "-v", "-z").split(b"\0"):
        if not record:
            continue
        try:
            tag, encoded_path = record[:1].decode("ascii"), record[2:]
        except UnicodeDecodeError:
            problems.append("<non-ascii-index-tag>")
            continue
        if len(record) < 3 or record[1:2] != b" " or tag != "H":
            problems.append(f"{tag}:{os.fsdecode(encoded_path)}")
    return tuple(sorted(problems))


def workspace_input_dirtiness(
    *, allow_post_validation_outputs: bool = False
) -> tuple[str, ...]:
    paths: set[str] = set()
    for arguments in (
        ("diff", "--name-only", "-z"),
        ("diff", "--cached", "--name-only", "-z"),
        ("ls-files", "--others", "--exclude-standard", "-z"),
    ):
        for value in git_bytes(*arguments).split(b"\0"):
            if value:
                relative = os.fsdecode(value)
                if not (
                    allow_post_validation_outputs
                    and is_validation_output_path(relative)
                ):
                    paths.add(relative)
    return tuple(sorted(paths))


def current_git_revision() -> tuple[str, str]:
    revision = git_text("rev-parse", "HEAD")
    tree = git_text("rev-parse", "HEAD^{tree}")
    return revision, tree


def revision_is_ancestor(revision: str) -> bool:
    authority_before = git_local_authority()
    result = subprocess.run(
        (str(GIT), "merge-base", "--is-ancestor", revision, "HEAD"),
        cwd=ROOT,
        check=False,
        stdout=subprocess.DEVNULL,
        stderr=subprocess.DEVNULL,
        env=GIT_ENVIRONMENT,
    )
    authority_after = git_local_authority()
    if authority_after != authority_before:
        fail("Git local authority changed during merge-base")
    return result.returncode == 0


def git_substitution_marker_problem(
    replace_refs: tuple[str, ...], marker_paths: tuple[str, ...], shallow: bool
) -> str | None:
    if replace_refs:
        return f"Git replace refs are forbidden: {replace_refs!r}"
    if marker_paths:
        return f"Git substitution metadata is forbidden: {marker_paths!r}"
    if shallow:
        return "a shallow Git repository cannot bind revision ancestry"
    return None


def require_git_source_authority() -> None:
    replace_refs = tuple(
        line
        for line in git_text(
            "for-each-ref", "--format=%(refname)", "refs/replace/"
        ).splitlines()
        if line
    )
    common_dir = Path(
        git_text("rev-parse", "--path-format=absolute", "--git-common-dir")
    )
    markers: list[str] = []
    for relative in (
        "info/grafts",
        "objects/info/alternates",
        "objects/info/http-alternates",
    ):
        path = common_dir / relative
        try:
            path.lstat()
        except FileNotFoundError:
            continue
        except OSError as error:
            fail(f"cannot inspect Git substitution marker {path}: {error}")
        markers.append(relative)
    shallow_text = git_text("rev-parse", "--is-shallow-repository")
    if shallow_text not in {"true", "false"}:
        fail("Git shallow-repository result is malformed")
    if problem := git_substitution_marker_problem(
        replace_refs, tuple(markers), shallow_text == "true"
    ):
        fail(problem)


def require_runner_self_controls() -> None:
    result = subprocess.run(
        (str(PYTHON), "-I", "-B", str(RUNNER), "--self-test"),
        cwd=ROOT,
        check=False,
        stdout=subprocess.PIPE,
        stderr=subprocess.PIPE,
        env={"LC_ALL": "C", "PATH": "/usr/bin:/bin"},
    )
    if (
        result.returncode != 0
        or result.stdout != b"S20-530 validation runner self-test: PASS\n"
        or result.stderr
    ):
        detail = (result.stdout + result.stderr).decode("utf-8", errors="replace")
        fail(f"validation runner hostile controls failed: {detail.strip()}")


def non_output_changes_since(revision: str) -> tuple[str, ...]:
    raw = git_bytes("diff", "--name-only", "-z", f"{revision}..HEAD")
    return tuple(
        sorted(
            os.fsdecode(value)
            for value in raw.split(b"\0")
            if value and not is_validation_output_path(os.fsdecode(value))
        )
    )


def committed_blob(revision: str, relative: str) -> bytes:
    return git_bytes("show", f"{revision}:{relative}")


def require_text(text: str, needle: str, owner: str) -> None:
    if needle not in text:
        fail(f"{owner} is missing {needle!r}")


def require_exact_matrix(spec: str) -> None:
    try:
        matrix = spec.split(
            "| ID | Owner | Injected boundary | Required immediate state | Required recovery/retry result |",
            1,
        )[1].split("Existing S20-500", 1)[0]
    except IndexError:
        fail("cannot isolate the fixed fault matrix")
    rows = []
    for line in matrix.splitlines():
        if line.startswith("| `"):
            rows.append([cell.strip() for cell in line.strip().strip("|").split("|")])
    found = tuple(row[0].strip("`") for row in rows)
    if found != MATRIX_IDS:
        fail(f"matrix IDs/order differ: expected {MATRIX_IDS!r}, found {found!r}")
    if len(set(found)) != len(MATRIX_IDS):
        fail("matrix IDs are not unique")
    if any(len(row) != 5 for row in rows):
        fail("a matrix row does not have exactly five cells")
    digest = hashlib.sha256(
        json.dumps(rows, ensure_ascii=False, separators=(",", ":")).encode("utf-8")
    ).hexdigest()
    if digest != MATRIX_ROWS_SHA256:
        fail(
            f"full matrix-row digest differs: expected {MATRIX_ROWS_SHA256}, found {digest}"
        )


def tier_2_command_contract_problem(spec: str) -> str | None:
    if len(TIER_2_COMMANDS) != 24 or len(set(TIER_2_COMMANDS)) != 24:
        return "checker does not freeze exactly 24 unique direct Tier 2 commands"
    if any(command.startswith("make ") for command in TIER_2_COMMANDS):
        return "Tier 2 command authority contains mutable Make indirection"
    marker = "Tier 2 for S20-530 is:\n\n```text\n"
    try:
        block = spec.split(marker, 1)[1].split("\n```", 1)[0]
    except IndexError:
        return "cannot isolate the exact Tier 2 command block"
    if tuple(block.splitlines()) != TIER_2_COMMANDS:
        return "specification Tier 2 command set/order differs"
    return None


