def normal_build_test_only_ranges(source: str, projected: str) -> list[tuple[int, int]]:
    ranges: list[tuple[int, int]] = []
    exact_test_only = {
        "cfg(test)",
        "cfg(any(test))",
        "cfg(all(test))",
    }
    for match in re.finditer(r"#\s*\[", projected):
        attribute = rust_attribute_end(projected, match.start())
        raw_attribute = rust_attribute_end(source, match.start())
        if attribute is None or raw_attribute is None:
            continue
        item_end = rust_attributed_item_end(projected, attribute[0])
        if item_end is None:
            fail("cannot isolate a test-only Rust item")
        if raw_attribute[1] in exact_test_only:
            ranges.append((match.start(), item_end))
            continue
        if raw_attribute[1] != S20_530_TEST_HOOK_FEATURE_GATE:
            continue
        gated_item = normalize_rust_tokens(source[match.start() : item_end])
        allowed_items = {
            normalize_rust_tokens(item)
            for item in S20_530_ALLOWED_FEATURE_GATED_ITEMS
        }
        if gated_item in allowed_items:
            ranges.append((match.start(), item_end))
    return ranges


def normal_build_rust(source: str) -> str:
    """Project code and remove only audited test-only items in a normal build."""
    projected = rust_code_projection(source)
    if re.search(r"#\s*!\s*\[\s*cfg(?:_attr)?\s*\(", projected):
        fail("production owner source contains an inner cfg/cfg_attr gate")
    ranges = normal_build_test_only_ranges(source, projected)
    output = list(projected)
    for start, end in ranges:
        for index in range(start, end):
            if output[index] != "\n":
                output[index] = " "
    return require_balanced_rust_projection("".join(output))


def normal_build_source(source: str) -> str:
    """Remove audited test-only items while preserving normal-build source bytes."""
    projected = rust_code_projection(source)
    if re.search(r"#\s*!\s*\[\s*cfg(?:_attr)?\s*\(", projected):
        fail("production owner source contains an inner cfg/cfg_attr gate")
    ranges = normal_build_test_only_ranges(source, projected)
    output = list(source)
    for start, end in ranges:
        for index in range(start, end):
            if output[index] != "\n":
                output[index] = " "
    result = "".join(output)
    require_balanced_rust_projection(rust_code_projection(result))
    return result


