def trait_impl_surface(
    source: str,
    projected: str,
    owner_ranges: tuple[tuple[int, int, str], ...],
) -> tuple[str, ...]:
    tokens: list[str] = []
    for match in rust_item_matches(projected, r"(?:(?:unsafe|default)\s+)?impl\b"):
        impl_start = projected.find("impl", match.start(), match.end())
        if impl_start < 0:
            fail("cannot isolate a Rust trait impl")
        extent = rust_attributed_item_end(projected, match.start())
        if extent is None:
            fail("cannot isolate a Rust trait impl")
        opening = projected.find("{", match.start(), extent)
        if opening < 0:
            fail("Rust trait impl has no body")
        closing = matching_delimiter(
            projected, [True] * len(projected), opening, "{", "}"
        )
        if closing is None:
            fail("Rust trait impl has no closing brace")
        header_projection = projected[match.start() : opening]
        if re.search(r"\bfor\b", header_projection) is None:
            continue
        header = normalize_rust_tokens(source[match.start() : opening])
        owner = rust_owner_chain(owner_ranges, match.start())
        tokens.append(f"trait-impl:{owner}:{header}")
        body_source = source[opening + 1 : closing]
        body_projection = projected[opening + 1 : closing]
        member_tokens: list[str] = []
        for function in rust_item_matches(
            body_projection,
            rf"(?:(?:default|const|async|unsafe)\s+)*"
            rf"(?:extern(?:\s+\"[^\"]+\")?\s+)?fn\s+{RUST_IDENTIFIER}\b",
        ):
            if (
                brace_depth_at(
                    body_projection, [True] * len(body_projection), function.start()
                )
                != 0
            ):
                continue
            end = public_function_signature_end(body_projection, function.start())
            if end is None:
                fail("cannot isolate a trait-impl member signature")
            member_tokens.append(
                "fn:" + normalize_rust_tokens(body_source[function.start() : end])
            )
        for associated in rust_item_matches(
            body_projection,
            rf"(?:default\s+)?(?P<kind>type|const)\s+"
            rf"(?P<name>{RUST_IDENTIFIER})\b",
        ):
            if (
                brace_depth_at(
                    body_projection, [True] * len(body_projection), associated.start()
                )
                != 0
            ):
                continue
            end = rust_attributed_item_end(body_projection, associated.start())
            if end is None:
                fail("cannot isolate a trait-impl associated item")
            member_tokens.append(
                f"{associated['kind']}:"
                + normalize_rust_tokens(body_source[associated.start() : end])
            )
        tokens.extend(
            f"trait-impl-member:{owner}:{header}:{member}"
            for member in sorted(member_tokens)
        )
    return tuple(tokens)


def rust_attribute_chain_target(projected: str, end: int) -> int:
    cursor = end
    while True:
        while cursor < len(projected) and projected[cursor].isspace():
            cursor += 1
        if cursor >= len(projected) or projected[cursor] != "#":
            return cursor
        following = rust_attribute_end(projected, cursor)
        if following is None:
            return cursor
        cursor = following[0]


def rust_enclosing_brace_openings(
    projected: str, position: int
) -> tuple[int, ...] | None:
    stack: list[int] = []
    for index, character in enumerate(projected[:position]):
        if character == "{":
            stack.append(index)
        elif character == "}":
            if not stack:
                return None
            stack.pop()
    return tuple(stack)


def rust_valid_authority_owner_openings(projected: str) -> dict[int, str]:
    candidates: dict[int, str] = {}
    for match in rust_item_matches(
        projected,
        rf"(?:pub(?:\([^)]*\))?\s+)?mod\s+{RUST_IDENTIFIER}\s*\{{",
    ):
        opening = projected.find("{", match.start(), match.end())
        if opening >= 0:
            candidates[opening] = "module"
    for match in rust_item_matches(projected, r"(?:(?:unsafe|default)\s+)?impl\b"):
        extent = rust_attributed_item_end(projected, match.start())
        if extent is None:
            continue
        opening = projected.find("{", match.start(), extent)
        if opening >= 0:
            candidates[opening] = "impl"
    for match in rust_item_matches(
        projected,
        r"(?:unsafe\s+)?extern(?:\s+\"[^\"]+\")?\s*\{",
    ):
        opening = projected.find("{", match.start(), match.end())
        if opening >= 0:
            candidates[opening] = "foreign"

    valid: dict[int, str] = {}
    for opening in sorted(candidates):
        parents = rust_enclosing_brace_openings(projected, opening)
        if parents is not None and all(
            valid.get(parent) == "module" for parent in parents
        ):
            valid[opening] = candidates[opening]
    return valid


def nested_public_declaration_problem(projected: str) -> str | None:
    valid_owners = rust_valid_authority_owner_openings(projected)
    declaration = re.compile(
        r"\bpub(?:\([^)]*\))?\s+"
        r"(?:"
        r"(?:(?:const|async|safe|unsafe)\s+)*"
        r"(?:extern(?:\s+\"[^\"]+\")?\s+)?fn\s+"
        rf"{RUST_IDENTIFIER}\b"
        r"|(?:(?:safe|unsafe)\s+)?static\s+(?:mut\s+)?"
        rf"{RUST_IDENTIFIER}\b"
        r"|(?:unsafe\s+)?(?:struct|enum|trait|union|type|const|mod)\s+"
        rf"{RUST_IDENTIFIER}\b"
        r"|use\b"
        r"|extern\s+crate\b"
        r")"
    )
    for match in declaration.finditer(projected):
        parents = rust_enclosing_brace_openings(projected, match.start())
        if parents is None:
            return "unbalanced Rust authority nesting"
        if all(valid_owners.get(parent) == "module" for parent in parents):
            continue
        if (
            parents
            and all(valid_owners.get(parent) == "module" for parent in parents[:-1])
            and valid_owners.get(parents[-1]) in {"impl", "foreign"}
        ):
            continue
        return "nested public declaration authority"
    return None


def generated_api_authority_problem(source: str) -> str | None:
    projected = rust_code_projection(source)
    if any(ord(character) > 127 for character in projected):
        return "non-ASCII Rust code authority is forbidden"
    if problem := nested_public_declaration_problem(projected):
        return problem
    attribute_ranges: list[tuple[int, int]] = []
    allowed_attributes = {
        "cold",
        "inline",
        "inline(always)",
        "inline(never)",
        "must_use",
        "track_caller",
    }
    for match in re.finditer(r"#\s*!?\s*\[", projected):
        attribute = rust_attribute_end(projected, match.start())
        if attribute is None:
            return "unterminated Rust attribute"
        end, normalized = attribute
        attribute_ranges.append((match.start(), end))
        target = rust_attribute_chain_target(projected, end)
        if re.match(r"(?:(?:unsafe|default)\s+)?impl\b", projected[target:]):
            return "attribute-controlled Rust impl authority"
        if normalized.startswith("derive(") and normalized.endswith(")"):
            derives = tuple(
                item for item in normalized[len("derive(") : -1].split(",") if item
            )
            if not derives or any(item not in BUILTIN_DERIVES for item in derives):
                return f"non-builtin derive authority: {normalized}"
            continue
        if normalized in allowed_attributes:
            continue
        if re.fullmatch(r"(?:allow|deny|forbid|warn)\([A-Za-z0-9_:,]+\)", normalized):
            continue
        if re.fullmatch(r"repr\([A-Za-z0-9_,()]+\)", normalized):
            continue
        if normalized.startswith("doc="):
            continue
        return f"procedural or unbound Rust attribute authority: {normalized}"

    function_ranges = rust_function_body_ranges(projected)
    for implementation in rust_item_matches(
        projected, r"(?:(?:unsafe|default)\s+)?impl\b"
    ):
        if any(start <= implementation.start() < end for start, end in function_ranges):
            return "nested trait or inherent impl authority"
    for trait in re.finditer(r"\btrait\s+", projected):
        if any(start <= trait.start() < end for start, end in function_ranges):
            return "nested trait-definition authority"
    allowed_expression_macros = {
        "assert",
        "assert_eq",
        "assert_ne",
        "debug_assert",
        "debug_assert_eq",
        "debug_assert_ne",
        "format",
        "matches",
        "println",
        "unreachable",
        "vec",
        "write",
        "writeln",
    }
    for use in re.finditer(r"\buse\s+(?P<body>.*?);", projected, re.DOTALL):
        imported = set(re.findall(RUST_IDENTIFIER, use["body"]))
        if imported.intersection(allowed_expression_macros):
            return "expression-macro name is imported or shadowable"
    for match in re.finditer(
        rf"(?P<path>(?:::)?{RUST_IDENTIFIER}(?:::{RUST_IDENTIFIER})*)\s*!",
        projected,
    ):
        path = match["path"]
        if path == "macro_rules":
            return "macro_rules! authority is forbidden at every depth"
        if any(start <= match.start() < end for start, end in function_ranges):
            if path not in allowed_expression_macros:
                return f"unbound expression-macro authority: {path}!"
            continue
        if any(start <= match.start() < end for start, end in attribute_ranges):
            continue
        return f"item-position macro authority: {match['path']}!"
    return None


def exact_module_declarations(source: str) -> tuple[str, ...] | None:
    projected = rust_code_projection(source)
    found: list[str] = []
    for match in rust_item_matches(
        projected,
        rf"(?P<visibility>pub(?:\([^)]*\))?\s+)?"
        rf"mod\s+(?P<name>{RUST_IDENTIFIER})\s*(?P<tail>;|\{{)",
    ):
        mod_start = projected.find("mod", match.start(), match.end())
        if (
            mod_start < 0
            or brace_depth_at(projected, [True] * len(projected), mod_start) != 0
        ):
            continue
        if match["visibility"] is not None or match["tail"] != ";":
            return None
        if has_preceding_code_attribute(
            projected, [True] * len(projected), match.start()
        ):
            return None
        found.append(semantic_rust_identifier(match["name"]))
    return tuple(found)


def public_semantic_attribute_surface(
    source: str,
    projected: str,
    owner_ranges: tuple[tuple[int, int, str], ...],
) -> tuple[str, ...]:
    tokens: list[str] = []
    for match in re.finditer(r"#\s*\[", projected):
        attribute = rust_attribute_end(projected, match.start())
        if attribute is None:
            fail("cannot isolate a public semantic Rust attribute")
        end, _normalized_projection = attribute
        cursor = rust_attribute_chain_target(projected, end)
        tail = projected[cursor:]
        label: str | None = None
        owner = rust_owner_chain(owner_ranges, cursor)
        function = re.match(
            r"pub(?:\([^)]*\))?\s+"
            r"(?:(?:const|async|safe|unsafe)\s+)*(?:extern(?:\s+\"[^\"]+\")?\s+)?"
            rf"fn\s+(?P<name>{RUST_IDENTIFIER})",
            tail,
        )
        item = re.match(
            r"pub(?:\([^)]*\))?\s+"
            r"(?:(?P<safety>safe|unsafe)\s+)?"
            rf"(?P<kind>struct|enum|trait|union|type|const|static|mod)\s+"
            r"(?:mut\s+)?"
            rf"(?P<name>{RUST_IDENTIFIER})",
            tail,
        )
        extern_crate = re.match(
            r"pub(?:\([^)]*\))?\s+extern\s+crate\s+"
            rf"(?P<name>{RUST_IDENTIFIER})",
            tail,
        )
        if function is not None:
            label = f"function:{owner}:{semantic_rust_identifier(function['name'])}"
        elif item is not None:
            label = (
                f"item:{owner}:{item['kind']}:{semantic_rust_identifier(item['name'])}"
            )
        elif extern_crate is not None:
            label = (
                f"extern-crate:{owner}:{semantic_rust_identifier(extern_crate['name'])}"
            )
        elif re.match(r"(?:(?:unsafe|default)\s+)?impl\b", tail):
            opening = projected.find("{", cursor)
            if opening >= 0:
                label = f"impl:{owner}:" + normalize_rust_tokens(source[cursor:opening])
        if label is None:
            continue
        normalized = normalize_rust_tokens(source[match.start() : end])
        digest = hashlib.sha256(normalized.encode("utf-8")).hexdigest()
        tokens.append(f"attribute:{label}:{digest}")
    return tuple(tokens)


def complete_public_surface(
    source: str, *, body_exclusions: frozenset[str] = frozenset()
) -> tuple[str, ...]:
    projected = rust_code_projection(source)
    owner_ranges = rust_owner_ranges(source, projected)
    tokens: list[str] = []
    for match in re.finditer(
        r"\bpub(?:\([^)]*\))?\s+"
        r"(?:(?:const|async|safe|unsafe)\s+)*(?:extern(?:\s+\"[^\"]+\")?\s+)?"
        rf"fn\s+{RUST_IDENTIFIER}\b",
        projected,
    ):
        end = public_function_signature_end(projected, match.start())
        if end is None:
            fail("cannot isolate a public Rust function signature")
        signature = normalize_rust_tokens(source[match.start() : end])
        owner = rust_owner_chain(owner_ranges, match.start())
        tokens.append(f"function:{owner}:{signature}")
    item_ranges: list[tuple[int, int, str]] = []
    for match in re.finditer(
        r"\bpub(?:\([^)]*\))?\s+"
        rf"(?:(?:unsafe\s+)?(?P<kind>struct|enum|trait|union|type|mod)\s+|"
        rf"(?P<const>const)\s+(?!fn\b)|"
        rf"(?:(?:safe|unsafe)\s+)?(?P<static>static)\s+(?:mut\s+)?)"
        rf"(?P<name>{RUST_IDENTIFIER})",
        projected,
    ):
        kind = match["kind"] or match["const"] or match["static"]
        name = semantic_rust_identifier(match["name"])
        owner = rust_owner_chain(owner_ranges, match.start())
        tokens.append(f"item:{owner}:{kind}:{name}")
        extent = rust_attributed_item_end(projected, match.start())
        if extent is None:
            fail(f"cannot isolate public {kind} {name}")
        opening = projected.find("{", match.end(), extent)
        if opening >= 0:
            closing = matching_delimiter(
                projected, [True] * len(projected), opening, "{", "}"
            )
            if closing is None or closing >= extent:
                fail(f"cannot close public {kind} {name}")
            if kind in {"struct", "enum", "trait", "union"}:
                item_ranges.append((opening, closing, name))
        if name not in body_exclusions:
            declaration = normalize_rust_tokens(source[match.start() : extent])
            declaration_digest = hashlib.sha256(declaration.encode("utf-8")).hexdigest()
            tokens.append(
                f"item-declaration:{owner}:{kind}:{name}:{declaration_digest}"
            )
        if (
            opening >= 0
            and kind in {"struct", "enum", "trait", "union"}
            and name not in body_exclusions
        ):
            header = normalize_rust_tokens(source[match.start() : opening])
            body = normalize_rust_tokens(source[opening + 1 : closing])
            tokens.append(f"item-header:{owner}:{kind}:{name}:{header}")
            tokens.append(
                f"item-body:{owner}:{kind}:{name}:"
                f"{hashlib.sha256(body.encode('utf-8')).hexdigest()}"
            )
    for match in re.finditer(
        r"(?m)^[ \t]*pub(?:\([^)]*\))?\s+"
        rf"(?P<name>{RUST_IDENTIFIER})\s*:\s*(?P<type>[^,\n]+),",
        projected,
    ):
        parents = [
            (closing - opening, parent)
            for opening, closing, parent in item_ranges
            if opening < match.start() < closing
        ]
        parent = min(parents)[1] if parents else "<unowned>"
        owner = rust_owner_chain(owner_ranges, match.start())
        field_type = normalize_rust_tokens(match["type"])
        tokens.append(
            f"field:{owner}:{parent}:"
            f"{semantic_rust_identifier(match['name'])}:{field_type}"
        )
    for match in re.finditer(
        r"\bpub(?:\([^)]*\))?\s+use\s+(?P<body>.*?);",
        projected,
        re.DOTALL,
    ):
        normalized = normalize_rust_tokens(match["body"])
        owner = rust_owner_chain(owner_ranges, match.start())
        if normalized.startswith("repository::{"):
            tokens.append(f"use:{owner}:<txn-repository-reexports-checked-separately>")
        else:
            tokens.append(f"use:{owner}:{normalized}")
    for match in re.finditer(
        r"\bpub(?:\([^)]*\))?\s+extern\s+crate\s+"
        rf"(?P<name>{RUST_IDENTIFIER})"
        rf"(?:\s+as\s+(?P<alias>{RUST_IDENTIFIER}))?\s*;",
        projected,
    ):
        owner = rust_owner_chain(owner_ranges, match.start())
        declaration = normalize_rust_tokens(source[match.start() : match.end()])
        tokens.append(f"extern-crate:{owner}:{declaration}")
    for match in rust_item_matches(
        projected,
        r"(?:(?:unsafe)\s+)?extern(?:\s+\"[^\"]+\")?\s*\{",
    ):
        opening = projected.find("{", match.start(), match.end())
        closing = matching_delimiter(
            projected, [True] * len(projected), opening, "{", "}"
        )
        if opening < 0 or closing is None:
            fail("cannot isolate a Rust foreign block")
        owner = rust_owner_chain(owner_ranges, match.start())
        declaration = normalize_rust_tokens(source[match.start() : closing + 1])
        digest = hashlib.sha256(declaration.encode("utf-8")).hexdigest()
        tokens.append(f"foreign-block:{owner}:{digest}")
    tokens.extend(trait_impl_surface(source, projected, owner_ranges))
    tokens.extend(public_semantic_attribute_surface(source, projected, owner_ranges))
    return tuple(sorted(tokens))


def public_api_source_paths() -> tuple[str, ...]:
    roots = (
        ROOT / "crates/sley-store/src",
        ROOT / "crates/sley-txn/src",
        ROOT / "crates/sley-repo/src",
    )
    return tuple(
        str(path.relative_to(ROOT))
        for root in roots
        for path in sorted(root.rglob("*.rs"))
        if path.is_file()
    )


def frozen_test_authority_record_problem(record: object) -> str | None:
    if not isinstance(record, dict):
        return "frozen test-authority record is not an object"
    if len(record) != FROZEN_TEST_AUTHORITY_FILE_COUNT:
        return "frozen test-authority file count differs"
    for relative, digest in record.items():
        if (
            not isinstance(relative, str)
            or not isinstance(digest, str)
            or re.fullmatch(r"[0-9a-f]{64}", digest) is None
        ):
            return "frozen test-authority path or digest is malformed"
    if canonical_json_sha256(record) != FROZEN_TEST_AUTHORITY_SET_SHA256:
        return "frozen test-authority path/byte set differs"
    return None


def owner_package_non_source_record_problem(record: object) -> str | None:
    if not isinstance(record, dict):
        return "owner package non-source record is not an object"
    if tuple(record) != OWNER_PACKAGE_NON_SOURCE_PATHS:
        return "owner package non-source path inventory differs"
    for relative, digest in record.items():
        if (
            not isinstance(relative, str)
            or not isinstance(digest, str)
            or re.fullmatch(r"[0-9a-f]{64}", digest) is None
        ):
            return "owner package non-source path or digest is malformed"
    return None


def owner_package_non_source_record() -> dict[str, str]:
    paths: set[Path] = set()
    for relative_root in OWNER_PACKAGE_ROOTS:
        root = ROOT / relative_root
        try:
            root_metadata = root.lstat()
        except OSError as error:
            fail(f"cannot inspect owner package root {relative_root}: {error}")
        if not stat.S_ISDIR(root_metadata.st_mode):
            fail(f"owner package root is not a real directory: {relative_root}")
        for path in root.rglob("*"):
            local = path.relative_to(root)
            if local.parts and local.parts[0] == "src" and path.suffix == ".rs":
                continue
            try:
                metadata = path.lstat()
            except OSError as error:
                fail(
                    f"cannot inspect owner package input {relative_root}/{local}: {error}"
                )
            if stat.S_ISDIR(metadata.st_mode):
                continue
            if not stat.S_ISREG(metadata.st_mode):
                fail(
                    "owner package non-source input is not a regular file: "
                    f"{relative_root}/{local}"
                )
            paths.add(path)
    record: dict[str, str] = {}
    for path in sorted(paths, key=lambda candidate: str(candidate.relative_to(ROOT))):
        relative = str(path.relative_to(ROOT))
        try:
            payload = path.read_bytes()
        except OSError as error:
            fail(f"cannot read owner package non-source input {relative}: {error}")
        record[relative] = hashlib.sha256(payload).hexdigest()
    return record


def frozen_test_authority_record() -> dict[str, str]:
    paths = {ROOT / relative for relative in FROZEN_TEST_AUTHORITY_FIXED_PATHS}
    for relative in FROZEN_TEST_AUTHORITY_ROOTS:
        root = ROOT / relative
        try:
            root_metadata = root.lstat()
        except OSError as error:
            fail(f"cannot inspect frozen test-authority root {relative}: {error}")
        if not stat.S_ISDIR(root_metadata.st_mode):
            fail(f"frozen test-authority root is not a real directory: {relative}")
        paths.update(root.rglob("*"))
    record: dict[str, str] = {}
    for path in sorted(paths, key=lambda candidate: str(candidate.relative_to(ROOT))):
        relative = str(path.relative_to(ROOT))
        try:
            metadata = path.lstat()
        except OSError as error:
            fail(f"cannot inspect frozen test-authority input {relative}: {error}")
        if stat.S_ISDIR(metadata.st_mode):
            continue
        if not stat.S_ISREG(metadata.st_mode):
            fail(f"frozen test-authority input is not a regular file: {relative}")
        try:
            payload = path.read_bytes()
        except OSError as error:
            fail(f"cannot read frozen test-authority input {relative}: {error}")
        record[relative] = hashlib.sha256(payload).hexdigest()
    return record


def require_frozen_test_authority() -> None:
    if problem := owner_package_non_source_record_problem(
        owner_package_non_source_record()
    ):
        fail(problem)
    if problem := frozen_test_authority_record_problem(frozen_test_authority_record()):
        fail(problem)


def public_api_baseline_problem() -> str | None:
    if public_api_source_paths() != PUBLIC_API_SOURCE_PATHS:
        return "production Rust source-path inventory differs"
    for relative, expected in PUBLIC_API_MODULE_GRAPH.items():
        source = normal_build_source((ROOT / relative).read_text(encoding="utf-8"))
        if exact_module_declarations(source) != expected:
            return f"exact unconditional module graph differs in {relative}"
    for relative in PUBLIC_API_CRATE_MANIFESTS:
        manifest = (ROOT / relative).read_bytes()
        if problem := native_lib_harness_problem(manifest):
            return f"native library root differs in {relative}: {problem}"
        if problem := owner_manifest_build_authority_problem(manifest):
            return f"owner build authority differs in {relative}: {problem}"
    for relative in PUBLIC_API_SOURCE_PATHS:
        complete_source = (ROOT / relative).read_text(encoding="utf-8")
        if problem := owner_source_external_authority_problem(complete_source):
            return (
                f"production API source has external authority in {relative}: {problem}"
            )
        source = normal_build_source(complete_source)
        if problem := generated_api_authority_problem(source):
            return f"production API source has generated authority in {relative}: {problem}"
        surface = list(
            complete_public_surface(
                source,
                body_exclusions=PUBLIC_API_BODY_EXCLUSIONS.get(relative, frozenset()),
            )
        )
        for allowed in PUBLIC_API_ALLOWED_ADDITIONS.get(relative, ()):
            try:
                surface.remove(allowed)
            except ValueError:
                return f"required public API delta is absent from {relative}: {allowed}"
        digest = canonical_json_sha256(surface)
        if digest != PUBLIC_API_BASELINE_SHA256[relative]:
            return f"complete public API baseline differs in {relative}"
    return None


def limit_profile_problem(source: str, spec: dict[str, object]) -> str | None:
    production = normal_build_rust(source)
    constructor = spec["constructor"]
    profile_type = spec["profile_type"]
    constants = spec["constants"]
    if not isinstance(constructor, str) or not isinstance(profile_type, str):
        return "invalid checker limit-profile metadata"
    if not isinstance(constants, tuple):
        return "invalid checker limit-constant metadata"

    for field, constant, expected in constants:
        matches = direct_code_matches(
            production,
            rf"\bconst\s+{re.escape(constant)}\s*:\s*u64\s*=\s*"
            r"(?P<value>[0-9][0-9_]*)\s*;",
        )
        if len(matches) != 1:
            return f"lacks one private u64 default constant {constant}"
        if int(matches[0]["value"].replace("_", "")) != expected:
            return f"default value differs for {constant}"
        if len(re.findall(rf"\b{re.escape(constant)}\b", production)) != 2:
            return f"{constant} is not bound only to its frozen profile field"

    constructor_matches = direct_code_matches(
        production,
        rf"\bconst\s+fn\s+{re.escape(constructor)}\s*\(\s*\)\s*"
        rf"->\s*{re.escape(profile_type)}\s*\{{",
    )
    if len(constructor_matches) != 1:
        return f"lacks one exact private constructor {constructor}"
    constructor_body = rust_named_function_body(production, constructor, "<crate>")
    if constructor_body is None:
        return f"cannot isolate private constructor {constructor}"
    if normalize_rust_tokens(constructor_body) != spec["initializer"]:
        return f"frozen profile initializer differs for {constructor}"
    if len(re.findall(rf"\b{re.escape(constructor)}\b", production)) != 2:
        return f"{constructor} is not selected by exactly one production wrapper"

    wrapper = spec["wrapper"]
    wrapper_owner = spec["wrapper_owner"]
    wrapper_body_expected = spec["wrapper_body"]
    if not all(
        isinstance(value, str)
        for value in (wrapper, wrapper_owner, wrapper_body_expected)
    ):
        return "invalid checker wrapper metadata"
    wrapper_body = rust_named_function_body(production, wrapper, wrapper_owner)
    if wrapper_body is None:
        return f"cannot isolate limit-selecting wrapper {wrapper_owner}::{wrapper}"
    normalized_wrapper = normalize_rust_tokens(wrapper_body)
    if normalized_wrapper != wrapper_body_expected:
        return f"{wrapper_owner}::{wrapper} does not make its exact bound core call"

    helper = spec["helper"]
    helper_error = spec["helper_error"]
    overflow_error = spec["overflow_error"]
    helper_body_expected = spec["helper_body"]
    if not all(
        isinstance(value, str)
        for value in (
            helper,
            helper_error,
            overflow_error,
            helper_body_expected,
        )
    ):
        return "invalid checker enforcement metadata"
    if helper_error not in helper_body_expected:
        return "checker helper-error metadata is not bound to its exact body"
    if not overflow_error:
        return "checker overflow-error metadata is empty"

    helper_matches = direct_code_matches(
        production,
        rf"\bfn\s+{re.escape(helper)}\s*\(\s*value\s*:\s*u64\s*,\s*"
        r"limit\s*:\s*u64\s*,?\s*\)",
    )
    if len(helper_matches) != 1:
        return f"lacks one exact private comparison helper {helper}"
    helper_body = rust_named_function_body(production, helper, "<crate>")
    if helper_body is None:
        return f"cannot isolate private comparison helper {helper}"
    normalized_helper = normalize_rust_tokens(helper_body)
    if normalized_helper != helper_body_expected:
        return f"{helper} does not implement the exact closed comparison body"
    return None


def limit_profile_map() -> dict[str, dict[str, object]]:
    profiles: dict[str, dict[str, object]] = {}
    for spec in LIMIT_PROFILE_SPECS:
        constructor = spec.get("constructor")
        if not isinstance(constructor, str) or constructor in profiles:
            fail("checker limit-profile constructor authority differs")
        profiles[constructor] = spec
    return profiles


def limit_profile_metadata_problem(
    specs: object = LIMIT_PROFILE_SPECS,
) -> str | None:
    expected_keys = (
        "path",
        "constructor",
        "profile_type",
        "initializer",
        "constants",
        "wrapper_owner",
        "wrapper",
        "wrapper_body",
        "helper",
        "helper_error",
        "overflow_error",
        "helper_body",
    )
    expected_constructors = (
        "object_recovery_limits",
        "transaction_recovery_limits",
        "accepted_recovery_limits",
        "branch_recovery_limits",
        "ref_recovery_limits",
    )
    if not isinstance(specs, tuple) or len(specs) != 5:
        return "limit profile authority is not exactly five profiles"
    if any(not isinstance(spec, dict) for spec in specs):
        return "limit profile authority contains a non-object profile"
    if tuple(spec.get("constructor") for spec in specs) != expected_constructors:
        return "limit profile constructors/order differ"
    qualified_fields: list[str] = []
    constants: list[str] = []
    for spec in specs:
        if tuple(spec) != expected_keys:
            return f"{spec.get('constructor')} limit profile schema/order differs"
        if not all(
            isinstance(spec[key], str) and bool(spec[key])
            for key in expected_keys
            if key != "constants"
        ):
            return f"{spec['constructor']} limit profile string metadata differs"
        entries = spec["constants"]
        if not isinstance(entries, tuple) or not entries:
            return f"{spec['constructor']} limit constant inventory differs"
        for entry in entries:
            if (
                not isinstance(entry, tuple)
                or len(entry) != 3
                or not isinstance(entry[0], str)
                or not isinstance(entry[1], str)
                or not isinstance(entry[2], int)
                or isinstance(entry[2], bool)
                or entry[2] <= 0
            ):
                return f"{spec['constructor']} limit constant entry differs"
            qualified_fields.append(f"{spec['constructor']}::{entry[0]}")
            constants.append(entry[1])
    if len(qualified_fields) != 37 or len(set(qualified_fields)) != 37:
        return "limit profile fields are not exactly 37 unique fields"
    if len(constants) != 37 or len(set(constants)) != 37:
        return "limit profile constants are not exactly 37 unique constants"
    return None


def limit_qualified_fields() -> tuple[str, ...]:
    return tuple(
        f"{spec['constructor']}::{field}"
        for spec in LIMIT_PROFILE_SPECS
        for field, _constant, _value in spec["constants"]
    )


def limit_event_record(
    specs: dict[str, LimitEventSpec] = LIMIT_EVENT_SPECS,
) -> tuple[tuple[object, ...], ...]:
    return tuple((event_id, *spec) for event_id, spec in specs.items())


def limit_event_specs_sha256(
    specs: dict[str, LimitEventSpec] = LIMIT_EVENT_SPECS,
) -> str:
    return canonical_json_sha256(limit_event_record(specs))


LIMIT_EVENT_SPECS_SHA256 = (
    "6dd6bf07baf3be257ba37df08e88b3e364a8be18024e4122edbf9e0f1ba3c3f3"
)


def limit_event_profile(
    qualified_field: str,
) -> tuple[dict[str, object], str] | None:
    try:
        constructor, field = qualified_field.split("::", 1)
    except ValueError:
        return None
    profile = limit_profile_map().get(constructor)
    if profile is None:
        return None
    constants = profile.get("constants")
    if not isinstance(constants, tuple) or field not in {
        item[0] for item in constants
    }:
        return None
    return profile, field


def limit_event_expected_statements(spec: LimitEventSpec) -> tuple[str, ...]:
    statements = list(spec.source)
    profile_by_charge: list[tuple[dict[str, object], str]] = []
    for qualified_field, counter, next_identifier, delta in spec.charges:
        resolved = limit_event_profile(qualified_field)
        if resolved is None:
            fail(f"limit event has an unknown profile field: {qualified_field}")
        profile, field = resolved
        overflow_error = profile.get("overflow_error")
        if not isinstance(overflow_error, str):
            fail("limit event profile lacks an overflow error")
        statements.append(
            f"let {next_identifier} = {counter}.checked_add({delta})"
            f".ok_or_else(|| {overflow_error})?;"
        )
        profile_by_charge.append((profile, field))
    if spec.charges:
        first_profile = profile_by_charge[0][0]
        overflow_error = first_profile.get("overflow_error")
        if not isinstance(overflow_error, str):
            fail("limit event retain profile lacks an overflow error")
    else:
        fail("limit event has no governed charge")
    for accumulator, next_identifier, delta in spec.retains:
        statements.append(
            f"let {next_identifier} = {accumulator}.checked_add({delta})"
            f".ok_or_else(|| {overflow_error})?;"
        )
    for (qualified_field, _counter, next_identifier, _delta), (
        profile,
        field,
    ) in zip(spec.charges, profile_by_charge):
        helper = profile.get("helper")
        if not isinstance(helper, str):
            fail(f"limit event helper differs for {qualified_field}")
        statements.append(f"{helper}({next_identifier}, limits.{field})?;")
    for _qualified_field, counter, next_identifier, _delta in spec.charges:
        statements.append(f"{counter} = {next_identifier};")
    for accumulator, next_identifier, _delta in spec.retains:
        statements.append(f"{accumulator} = {next_identifier};")
    statements.extend(spec.sink)
    return tuple(statements)


def limit_event_source_problem(spec: LimitEventSpec) -> str | None:
    normalized = tuple(normalize_rust_tokens(statement) for statement in spec.source)
    if spec.source_kind == "unit":
        if len(normalized) != 2 or normalized[-1] != "letone=1_u64;":
            return "unit source is not one exact item plus one-unit delta"
        if any(delta != "one" for _field, _counter, _next, delta in spec.charges):
            return "unit source has a non-unit governed delta"
        if spec.identity == ("binding",):
            wrap_verification = (
                spec.site[2] == "verify_recovery_ancestries_with_limits"
            )
            expected_sink = limit_recovery_binding_sink(
                wrap_verification=wrap_verification,
            )
            if tuple(
                normalize_rust_tokens(statement) for statement in spec.sink
            ) != tuple(
                normalize_rust_tokens(statement) for statement in expected_sink
            ):
                return "binding sink does not use its exact site-specific bridge"
    elif spec.source_kind == "batch_len":
        if normalized != (
            "letmutrequest_usage=0_u64;",
            "letrequest_count=u64::try_from(requests.len()).map_err(|_|RecoveryAncestryError::LimitExceeded)?;",
        ):
            return "batch source is not the checked request-slice length"
        if any(
            delta != "request_count"
            for _field, _counter, _next, delta in spec.charges
        ):
            return "batch source has a non-length governed delta"
    elif spec.source_kind == "metadata_file":
        is_receipt_site = spec.site[0] == TXN_LIMIT_SOURCE and spec.site[2] in {
            "verify_accepted_recovery_ancestry_with_limits",
            "verify_recovery_ancestries_with_limits",
        }
        if is_receipt_site:
            wrap_verification = (
                spec.site[2] == "verify_recovery_ancestries_with_limits"
            )
            expected_source = limit_recovery_receipt_metadata_source(
                wrap_verification=wrap_verification,
            )
            if normalized != tuple(
                normalize_rust_tokens(statement) for statement in expected_source
            ):
                return "receipt metadata source does not use its exact read-only bridge"
            expected_sink = limit_recovery_receipt_sink(
                wrap_verification=wrap_verification,
            )
            if tuple(
                normalize_rust_tokens(statement) for statement in spec.sink
            ) != tuple(
                normalize_rust_tokens(statement) for statement in expected_sink
            ):
                return "receipt sink does not use its exact site-specific bridge"
        else:
            if len(normalized) not in {4, 5}:
                return "metadata source statement count differs"
            if "symlink_metadata" not in normalized[1]:
                return "metadata source does not stat the exact path"
            if normalized[2] != "ensure_recovery_regular_file(&metadata)?;":
                return "metadata source does not reject symlink/non-regular entries"
            if normalized[3] != "letmetadata_bytes=metadata.len();":
                return "metadata source does not charge metadata length"
            if len(normalized) == 5 and normalized[4] != "letone=1_u64;":
                return "metadata count delta is not one"
        allowed_deltas = {"metadata_bytes"}
        if len(normalized) == 5:
            allowed_deltas.add("one")
        if any(
            delta not in allowed_deltas
            for _field, _counter, _next, delta in spec.charges
        ):
            return "metadata source has an untrusted governed delta"
    elif spec.source_kind == "bounded_object":
        expected_source = limit_bounded_object_source(
            "next_object_id",
            wrap_store_error=(
                spec.site[2] == "verify_recovery_ancestries_with_limits"
            ),
        )
        if normalized != tuple(
            normalize_rust_tokens(statement) for statement in expected_source
        ):
            return "bounded-object source does not use its exact site-specific bridge"
        expected_sink = (
            (
                "let object = self.object_store.read(object_id, verifier)"
                ".map_err(CommitError::from)"
                ".map_err(RecoveryAncestryError::Verification)?;"
            )
            if spec.site[2] == "verify_recovery_ancestries_with_limits"
            else "let object = self.object_store.read(object_id, verifier)?;"
        )
        if tuple(normalize_rust_tokens(statement) for statement in spec.sink) != (
            normalize_rust_tokens(expected_sink),
        ):
            return "bounded-object sink does not use its exact site-specific bridge"
        if any(
            delta not in {"one", "object_bytes"}
            for _field, _counter, _next, delta in spec.charges
        ):
            return "bounded-object source has an untrusted governed delta"
    elif spec.source_kind == "branch_ancestry":
        if normalized != (
            "lettransaction_id=pending_transaction_id;",
            "letfirst_union=!union_seen.contains(&transaction_id);",
            "letone=1_u64;",
            "letunion_delta=u64::from(first_union);",
        ):
            return "branch-ancestry source is not exact head/union admission"
        if tuple(charge[3] for charge in spec.charges) != ("one", "union_delta"):
            return "branch-ancestry source has non-head/union deltas"
    elif spec.source_kind == "cached_work":
        if normalized != tuple(
            normalize_rust_tokens(statement) for statement in limit_cached_work_source()
        ):
            return "cached-work source is not the immutable retained cache entry"
        if tuple(charge[3] for charge in spec.charges) != (
            "cached_receipt_bytes",
            "cached_binding_visits",
            "cached_object_verifications",
            "cached_object_bytes",
        ):
            return "cached-work source has forged or reordered deltas"
    else:
        return f"unknown limit-event source kind {spec.source_kind!r}"
    joined_source = "\n".join(spec.source)
    joined_sink = "\n".join(spec.sink)
    for identity in spec.identity:
        if not code_contains_token(joined_source, identity) or not code_contains_token(
            joined_sink, identity
        ):
            return f"identity {identity!r} is not shared by source and sink"
    return None


def limit_event_metadata_problem(
    specs: object = LIMIT_EVENT_SPECS,
    expected_digest: object = LIMIT_EVENT_SPECS_SHA256,
) -> str | None:
    expected_ids = (
        "object.scan_fanout",
        "object.scan_leaf",
        "object.retain_final",
        "object.retain_stage",
        "txn.receipt_scan_fanout",
        "txn.receipt_scan_leaf",
        "txn.retain_receipt",
        "txn.retain_receipt_stage",
        "txn.head_scan_entry",
        "txn.retain_head_stage",
        "ref.origin_scan_fanout",
        "ref.origin_scan_leaf",
        "ref.retain_origin",
        "ref.retain_origin_stage",
        "ref.record_scan_fanout",
        "ref.record_scan_leaf",
        "ref.retain_record_stage",
        "ref.visible_record_read",
        "ref.visible_origin_read",
        "ref.orphan_origin_read",
        "branch.request_batch",
        "accepted.ancestry_node",
        "accepted.receipt_read",
        "accepted.binding_visit",
        "accepted.object_read",
        "branch.ancestry_node",
        "branch.actual_receipt_read",
        "branch.actual_binding_visit",
        "branch.actual_object_read",
        "branch.cached_fact_use",
    )
    if not isinstance(specs, dict) or tuple(specs) != expected_ids:
        return "limit event IDs/order differ"
    if len(specs) != 30 or any(
        not isinstance(spec, LimitEventSpec) for spec in specs.values()
    ):
        return "limit event authority is not exactly 30 typed events"
    allowed_sources = {
        "unit",
        "batch_len",
        "metadata_file",
        "bounded_object",
        "branch_ancestry",
        "cached_work",
    }
    field_memberships: list[str] = []
    next_identifiers: set[tuple[tuple[str, str, str], str]] = set()
    for event_id, spec in specs.items():
        if spec.source_kind not in allowed_sources:
            return f"{event_id} source kind differs"
        if (
            len(spec.site) != 3
            or spec.site[0] not in {STORE_LIMIT_SOURCE, TXN_LIMIT_SOURCE, REF_LIMIT_SOURCE}
            or not spec.source
            or not spec.identity
            or not spec.charges
            or not spec.sink
            or spec.bypass_tokens != LIMIT_EVENT_BYPASS_TOKENS
        ):
            return f"{event_id} event shape differs"
        if problem := limit_event_source_problem(spec):
            return f"{event_id} source differs: {problem}"
        for qualified_field, counter, next_identifier, delta in spec.charges:
            if limit_event_profile(qualified_field) is None:
                return f"{event_id} has unknown field {qualified_field}"
            if any(
                re.fullmatch(r"[A-Za-z_][A-Za-z0-9_.]*", value) is None
                for value in (counter, next_identifier, delta)
            ):
                return f"{event_id} charge identifiers differ"
            identity = (spec.site, next_identifier)
            if identity in next_identifiers:
                return f"{event_id} reuses a next-value identifier at one site"
            next_identifiers.add(identity)
            field_memberships.append(qualified_field)
        for accumulator, next_identifier, delta in spec.retains:
            if any(
                re.fullmatch(r"[A-Za-z_][A-Za-z0-9_.]*", value) is None
                for value in (accumulator, next_identifier, delta)
            ):
                return f"{event_id} retain identifiers differ"
            identity = (spec.site, next_identifier)
            if identity in next_identifiers:
                return f"{event_id} reuses a retain next-value identifier"
            next_identifiers.add(identity)
        if len(set(spec.charges)) != len(spec.charges) or len(set(spec.retains)) != len(
            spec.retains
        ):
            return f"{event_id} repeats a charge or retention"
        if any(
            token in code_only_normalized("\n".join(limit_event_expected_statements(spec)))
            for token in spec.bypass_tokens
        ):
            return f"{event_id} exact window contains a bypass token"

    qualified_fields = limit_qualified_fields()
    expected_memberships = {field: 1 for field in qualified_fields}
    for repeated in (
        "ref_recovery_limits::origin_record_bytes",
        "branch_recovery_limits::per_pointer.receipt_bytes",
        "branch_recovery_limits::per_pointer.binding_visits",
        "branch_recovery_limits::per_pointer.object_verifications",
        "branch_recovery_limits::per_pointer.object_bytes",
    ):
        expected_memberships[repeated] = 2
    found_memberships = {
        field: field_memberships.count(field) for field in set(field_memberships)
    }
    if len(qualified_fields) != 37 or len(field_memberships) != 42:
        return "limit field/event cardinalities are not exactly 37/42"
    if found_memberships != expected_memberships:
        return "limit field-event membership counter differs"

    multi_charge_counts = {
        event_id: len(specs[event_id].charges)
        for event_id in (
            "ref.visible_record_read",
            "ref.orphan_origin_read",
            "accepted.object_read",
            "branch.ancestry_node",
            "branch.actual_receipt_read",
            "branch.actual_binding_visit",
            "branch.actual_object_read",
            "branch.cached_fact_use",
        )
    }
    if multi_charge_counts != {
        "ref.visible_record_read": 2,
        "ref.orphan_origin_read": 2,
        "accepted.object_read": 2,
        "branch.ancestry_node": 2,
        "branch.actual_receipt_read": 2,
        "branch.actual_binding_visit": 2,
        "branch.actual_object_read": 4,
        "branch.cached_fact_use": 4,
    }:
        return "shared atomic multi-budget window membership differs"
    for event_id in (
        "branch.actual_receipt_read",
        "branch.actual_binding_visit",
        "branch.actual_object_read",
    ):
        fields = tuple(charge[0] for charge in specs[event_id].charges)
        if not any("::per_pointer." in field for field in fields) or not any(
            "::union." in field for field in fields
        ):
            return f"{event_id} does not charge head and union atomically"
        if not specs[event_id].retains:
            return f"{event_id} does not retain its exact cache work"
    cached_fields = tuple(
        charge[0] for charge in specs["branch.cached_fact_use"].charges
    )
    if any("::union." in field for field in cached_fields) or specs[
        "branch.cached_fact_use"
    ].retains:
        return "cached fact use charges union or republishes cache work"
    if (
        not isinstance(expected_digest, str)
        or limit_event_specs_sha256(specs) != expected_digest
    ):
        return "limit event authority digest differs"
    return None


def limit_event_window_problem(
    source: str,
    spec: LimitEventSpec,
) -> str | None:
    production = normal_build_source(source)
    _path, owner, function = spec.site
    body = rust_named_function_raw_body(production, function, owner)
    if body is None:
        return f"cannot isolate limit event site {owner}::{function}"
    expected = limit_event_expected_statements(spec)
    event_range = exact_statement_sequence_range(body, expected)
    if event_range is None:
        return "exact source/add/guard/commit/sink window is absent or repeated"
    window = body[event_range[0] : event_range[1]]
    normalized_window = code_only_normalized(window)
    for token in spec.bypass_tokens:
        if token in normalized_window:
            return f"event window contains bypass token {token!r}"
    for qualified_field, counter, next_identifier, delta in spec.charges:
        resolved = limit_event_profile(qualified_field)
        if resolved is None:
            return f"unknown event field {qualified_field}"
        profile, field = resolved
        helper = profile["helper"]
        checked = normalize_rust_tokens(
            f"{counter}.checked_add({delta})"
        )
        guard = normalize_rust_tokens(f"{helper}({next_identifier},limits.{field})?")
        commit = normalize_rust_tokens(f"{counter}={next_identifier};")
        if normalized_window.count(checked) != 1:
            return f"{qualified_field} lacks one checked-add of its trusted delta"
        if normalized_window.count(guard) != 1:
            return f"{qualified_field} lacks one guard of its next value"
        if normalized_window.count(commit) != 1:
            return f"{qualified_field} lacks one post-guard counter commit"
    return None


def limit_sink_call_target(statement: str) -> str | None:
    projected = rust_code_projection(statement)
    match = re.search(
        rf"(?P<callee>(?:::)?{RUST_IDENTIFIER}"
        rf"(?:(?:::|\.){RUST_IDENTIFIER})*)\s*\(",
        projected,
    )
    if match is None:
        return None
    return semantic_rust_identifier(match["callee"])


def limit_events_problem(sources: object) -> str | None:
    if problem := limit_event_metadata_problem():
        return f"limit event metadata differs: {problem}"
    if not isinstance(sources, dict) or any(
        not isinstance(relative, str) or not isinstance(source, str)
        for relative, source in sources.items()
    ):
        return "limit event production sources differ"
    ranges_by_site: dict[tuple[str, str, str], list[tuple[int, int]]] = {}
    bodies_by_site: dict[tuple[str, str, str], str] = {}
    for event_id, spec in LIMIT_EVENT_SPECS.items():
        relative = spec.site[0]
        if relative not in sources:
            return f"{event_id} limit event source is absent"
        if problem := limit_event_window_problem(sources[relative], spec):
            return f"{event_id} limit event differs: {problem}"
        production = normal_build_source(sources[relative])
        body = rust_named_function_raw_body(
            production,
            spec.site[2],
            spec.site[1],
        )
        if body is None:
            return f"{event_id} limit event site disappeared after validation"
        event_range = exact_statement_sequence_range(
            body, limit_event_expected_statements(spec)
        )
        if event_range is None:
            return f"{event_id} limit event window disappeared after validation"
        for existing in ranges_by_site.setdefault(spec.site, []):
            if event_range[0] < existing[1] and existing[0] < event_range[1]:
                return f"{event_id} overlaps another governed limit event"
        ranges_by_site[spec.site].append(event_range)
        bodies_by_site[spec.site] = body

    memberships: dict[tuple[tuple[str, str, str], str], int] = {}
    sinks: dict[tuple[tuple[str, str, str], str], int] = {}
    helper_calls: dict[tuple[tuple[str, str, str], str], int] = {}
    counter_writes: dict[tuple[tuple[str, str, str], str], int] = {}
    for spec in LIMIT_EVENT_SPECS.values():
        for qualified_field, counter, _next, _delta in spec.charges:
            profile, field = limit_event_profile(qualified_field) or ({}, "")
            key = (spec.site, field)
            memberships[key] = memberships.get(key, 0) + 1
            helper = profile.get("helper")
            if not isinstance(helper, str):
                return f"{qualified_field} lacks an exact comparison helper"
            helper_key = (spec.site, helper)
            helper_calls[helper_key] = helper_calls.get(helper_key, 0) + 1
            counter_key = (spec.site, counter)
            counter_writes[counter_key] = counter_writes.get(counter_key, 0) + 1
        for accumulator, _next, _delta in spec.retains:
            counter_key = (spec.site, accumulator)
            counter_writes[counter_key] = counter_writes.get(counter_key, 0) + 1
        for statement in spec.sink:
            target = limit_sink_call_target(statement)
            if target is None:
                return "checker limit-event sink lacks a direct call target"
            key = (spec.site, target)
            sinks[key] = sinks.get(key, 0) + 1
    for (site, field), expected_count in memberships.items():
        normalized = normalize_rust_tokens(bodies_by_site[site])
        if normalized.count(f"limits.{field}") != expected_count:
            return (
                f"{site[0]}::{site[2]} limit field {field} occurs outside its exact "
                "event membership"
            )
    for (site, helper), expected_count in helper_calls.items():
        normalized = normalize_rust_tokens(bodies_by_site[site])
        if normalized.count(f"{helper}(") != expected_count:
            return (
                f"{site[0]}::{site[2]} helper {helper} occurs outside its exact "
                "governed event membership"
            )
    for (site, counter), expected_commits in counter_writes.items():
        normalized = normalize_rust_tokens(bodies_by_site[site])
        expected_initializers = sum(
            normalize_rust_tokens(statement).count(f"{counter}=")
            for spec in LIMIT_EVENT_SPECS.values()
            if spec.site == site
            for statement in spec.source
        )
        if normalized.count(f"{counter}=") != (
            expected_commits + expected_initializers
        ):
            return (
                f"{site[0]}::{site[2]} counter {counter} has an ungoverned write"
            )
    for (site, target), expected_count in sinks.items():
        normalized = normalize_rust_tokens(bodies_by_site[site])
        if normalized.count(f"{target}(") != expected_count:
            return (
                f"{site[0]}::{site[2]} sink {target} occurs outside its exact "
                "governed event membership"
            )
    for site, body in bodies_by_site.items():
        normalized = code_only_normalized(body)
        for token in LIMIT_EVENT_BYPASS_TOKENS:
            if token in normalized:
                return (
                    f"{site[0]}::{site[2]} contains global limit bypass token "
                    f"{token!r}"
                )
    return None


def require_limit_events(sources: dict[str, str]) -> None:
    if problem := limit_events_problem(sources):
        fail(problem)


def require_production_limit_defaults(sources: dict[str, str]) -> None:
    if problem := limit_profile_metadata_problem():
        fail(f"limit profile metadata differs: {problem}")
    expected = {
        (relative, constant, value)
        for subcases in LIMIT_DEFAULTS.values()
        for relative, constant, value in subcases.values()
    }
    expected.add(BRANCH_RECOVERY_REQUEST_LIMIT)
    specified = {
        (spec["path"], constant, value)
        for spec in LIMIT_PROFILE_SPECS
        for _field, constant, value in spec["constants"]
    }
    if specified != expected:
        fail("checker limit-profile metadata does not cover the exact frozen defaults")

    for spec in LIMIT_PROFILE_SPECS:
        relative = spec["path"]
        if not isinstance(relative, str) or relative not in sources:
            fail("checker limit-profile source metadata differs")
        if problem := limit_profile_problem(sources[relative], spec):
            fail(f"production limit profile {spec['constructor']} differs: {problem}")

    require_limit_events(sources)

    refs = normal_build_rust(sources["crates/sley-repo/src/refs.rs"])
    branch_constants = tuple(
        constant
        for spec in LIMIT_PROFILE_SPECS
        if spec["constructor"] == "branch_recovery_limits"
        for _field, constant, _value in spec["constants"]
    )
    mirrored = tuple(
        constant
        for constant in branch_constants
        if re.search(rf"\b{re.escape(constant)}\b", refs)
    )
    if mirrored:
        fail(f"repository source mirrors transaction-owned branch limits: {mirrored!r}")


def exact_error_case_keys(
    family_specs: dict[str, dict[str, tuple[str, str, tuple[str, ...]]]],
    row_specs: dict[str, tuple[str, str, tuple[str, ...]]],
) -> frozenset[tuple[str, str | None]]:
    return frozenset(
        {
            *(
                (row_id, subcase_id)
                for row_id, cases in family_specs.items()
                for subcase_id in cases
            ),
            *((row_id, None) for row_id in row_specs),
        }
    )


def error_metadata_problem(
    family_specs: dict[str, dict[str, tuple[str, str, tuple[str, ...]]]],
    row_specs: dict[str, tuple[str, str, tuple[str, ...]]],
    operation_calls: dict[str, frozenset[tuple[str, str | None]]],
) -> str | None:
    expected_family_rows = (
        "GUARD-01",
        "GUARD-02",
        "ANC-04",
        "ANC-06",
        "COR-08",
    )
    expected_row_ids = (
        "GUARD-03",
        "GUARD-04",
        "GUARD-05",
        "GUARD-06",
        "ANC-03",
        "ANC-05",
        "ANC-07",
        "ANC-08",
    )
    if tuple(family_specs) != expected_family_rows:
        return "exact error-family rows/order differ"
    if tuple(row_specs) != expected_row_ids:
        return "exact non-family error rows/order differ"
    for row_id, cases in family_specs.items():
        if tuple(cases) != EVIDENCE_FAMILIES[row_id]:
            return f"{row_id} exact error subcase coverage/order differs"
    expected_operations = (
        "transaction_recovery",
        "ancestry_verifier",
        "ref_recovery",
        "gc_witness_recovery",
    )
    if tuple(operation_calls) != expected_operations:
        return "error operation vocabulary/order differs"
    operation_sets = tuple(operation_calls.values())
    if any(not isinstance(cases, frozenset) for cases in operation_sets):
        return "error operation coverage is not immutable"
    combined: set[tuple[str, str | None]] = set()
    for cases in operation_sets:
        if combined.intersection(cases):
            return "one exact error case maps to multiple recovery operations"
        combined.update(cases)
    expected_cases = exact_error_case_keys(family_specs, row_specs).union(
        MULTIFAULT_NON_ERROR_VARIANTS
    )
    if frozenset(combined) != expected_cases:
        return "error operation coverage differs from exact error cases"
    return None


def recovery_provenance_metadata_problem(
    specs: object = RECOVERY_PROVENANCE_SPECS,
    expected_digest: object = RECOVERY_PROVENANCE_SPECS_SHA256,
) -> str | None:
    if not isinstance(specs, dict) or tuple(specs) != RECOVERY_PROVENANCE_CASE_IDS:
        return "recovery provenance case IDs/order differ"
    if len(specs) != 10 or any(
        not isinstance(spec, RecoveryProvenanceSpec) for spec in specs.values()
    ):
        return "recovery provenance authority is not exactly ten typed cases"
    expected_canaries = {
        ("GUARD-01", "transaction_recovery_same_root_shared"): TXN_OWNER_CANARIES,
        ("GUARD-01", "ancestry_verifier_same_root_shared"): (),
        ("GUARD-02", "transaction_recovery_wrong_root_exclusive"): (
            TXN_TWO_ROOT_CANARIES
        ),
        ("GUARD-02", "ancestry_verifier_wrong_root_exclusive"): (),
        ("GUARD-03", None): REF_OWNER_CANARIES,
        ("GUARD-04", None): REF_TWO_ROOT_CANARIES,
        ("ANC-03", None): (),
        ("ANC-05", None): (),
        ("ANC-07", None): (),
        ("ANC-08", None): (),
    }
    expected_extra_facts = {
        ("ANC-05", None): RECOVERY_PROVENANCE_DEEP_REF_FACTS,
        ("ANC-08", None): RECOVERY_PROVENANCE_CYCLE_REF_FACTS,
    }
    plan_digests: list[str] = []
    for case_id, spec in specs.items():
        if any(
            not value
            for value in (
                spec.owner_source,
                spec.fixture_family,
                spec.guard_relation,
                spec.pointer_role,
                spec.topology_recipe,
                spec.fault_role,
            )
        ):
            return f"{case_id!r} recovery provenance has an empty identifier"
        if spec.canary_roles != expected_canaries[case_id]:
            return f"{case_id!r} recovery canary roles/order differ"
        expected_roots = (
            ("OWNER_ROOT", "GUARD_ROOT")
            if spec.guard_relation == "wrong_root_exclusive"
            else ("OWNER_ROOT",)
        )
        if spec.snapshot_roots != expected_roots:
            return f"{case_id!r} recovery snapshot roots/order differ"
        expected_facts = recovery_provenance_required_facts(
            spec.fixture_family,
            spec.guard_relation,
            spec.canary_roles,
            expected_extra_facts.get(case_id, ()),
        )
        if spec.required_facts != expected_facts or len(set(expected_facts)) != len(
            expected_facts
        ):
            return f"{case_id!r} recovery required facts/order differ"
        rendered_assertions = recovery_provenance_fact_assertions(case_id, spec)
        if (
            tuple(rendered_assertions) != spec.required_facts
            or len(set(rendered_assertions.values())) != len(rendered_assertions)
        ):
            return f"{case_id!r} recovery fact assertion rendering differs"
        for fact, assertion in rendered_assertions.items():
            if ASSERTION_MACRO.match(assertion) is None:
                return f"{case_id!r} recovery fact {fact!r} is not an assertion"
            operands = exact_assert_eq_operands(assertion)
            if operands is not None and code_only_normalized(
                operands[0]
            ) == code_only_normalized(operands[1]):
                return f"{case_id!r} recovery fact {fact!r} is reflexive"
            predicate = exact_assert_predicate(assertion)
            if predicate is not None and re.fullmatch(RUST_IDENTIFIER, predicate):
                return f"{case_id!r} recovery fact {fact!r} trusts a local boolean"
        operation = error_operation_name(*case_id)
        expected_owner = (
            REF_PROVENANCE_SOURCE
            if operation == "ref_recovery"
            else TXN_PROVENANCE_SOURCE
        )
        if spec.owner_source != expected_owner:
            return f"{case_id!r} recovery provenance owner differs"
        plan_digests.append(recovery_provenance_plan_sha256(case_id, spec))
    if len(set(plan_digests)) != 10:
        return "recovery provenance plan digests are not unique"
    family_counts = {
        family: sum(spec.fixture_family == family for spec in specs.values())
        for family in ("guard_preflight", "deep_missing_ancestry", "logical_cycle")
    }
    if family_counts != {
        "guard_preflight": 6,
        "deep_missing_ancestry": 2,
        "logical_cycle": 2,
    }:
        return "recovery provenance family cardinalities differ"
    if (
        not isinstance(expected_digest, str)
        or recovery_provenance_specs_sha256(specs) != expected_digest
    ):
        return "recovery provenance authority digest differs"
    return None


def grouped_error_metadata_problem(
    grouped_cases: object = GROUPED_ERROR_CASES,
    grouped_specs: object = GROUPED_ERROR_SPECS,
    operation_calls: object = GROUPED_ERROR_OPERATION_CALLS,
    expected_digest: object = GROUPED_ERROR_CASES_SHA256,
) -> str | None:
    if not isinstance(grouped_cases, dict) or tuple(grouped_cases) != (
        "COR-06",
        "COR-07",
    ):
        return "grouped error rows/order differ"
    expected_group_counts = {
        "COR-06": (2, 1, 54, 4, 8, 1, 3, 1),
        "COR-07": (2, 1, 5, 1, 2, 1, 72, 77),
    }
    expected_totals = {"COR-06": 74, "COR-07": 161}
    flattened_keys: list[tuple[str, str, str]] = []
    for row_id, groups in grouped_cases.items():
        if not isinstance(groups, dict) or tuple(groups) != EVIDENCE_FAMILIES[row_id]:
            return f"{row_id} grouped error namespaces/order differ"
        counts = tuple(len(leaves) for leaves in groups.values())
        if counts != expected_group_counts[row_id]:
            return f"{row_id} grouped error leaf counts differ"
        if sum(counts) != expected_totals[row_id]:
            return f"{row_id} grouped error total differs"
        local_leaf_ids: list[str] = []
        for group_id, leaves in groups.items():
            if not isinstance(leaves, tuple) or not leaves:
                return f"{row_id}/{group_id} leaves are not one nonempty tuple"
            for leaf in leaves:
                if (
                    not isinstance(leaf, tuple)
                    or len(leaf) != 4
                    or not isinstance(leaf[0], str)
                    or not isinstance(leaf[1], str)
                    or not isinstance(leaf[2], str)
                    or not isinstance(leaf[3], tuple)
                    or any(not isinstance(item, str) for item in leaf[3])
                ):
                    return f"{row_id}/{group_id} has malformed leaf authority"
                leaf_id = leaf[0]
                local_leaf_ids.append(leaf_id)
                flattened_keys.append((row_id, group_id, leaf_id))
        if len(local_leaf_ids) != len(set(local_leaf_ids)):
            return f"{row_id} grouped error leaf identities are not unique"
    if (
        len(VISIBLE_REVISION_CASES) != 72
        or len({case[0] for case in VISIBLE_REVISION_CASES}) != 72
    ):
        return "visible-revision preservation authority is not 72 unique cases"
    visible_names = {case[0] for case in VISIBLE_REVISION_CASES}
    for forbidden in ("semantic_txn_io", "recovery_txn_resource_limit"):
        if forbidden in visible_names:
            return f"visible-revision authority retains recovery-owned case {forbidden}"
    for required in (
        "state_root_scb_digest_mismatch",
        "policy_root_scb_digest_mismatch",
        "host_txn_io",
        "codec_txn_resource_limit",
    ):
        if required not in visible_names:
            return f"visible-revision authority lacks exact case {required}"
    if grouped_cases["COR-06"] != grouped_cor06_cases():
        return "COR-06 exact grouped preservation partition differs"
    expected_ref_groups = {
        group_id: REF_OWNER_ERROR_CASES[group_id]
        for group_id in (
            "origin_format",
            "origin_digest",
            "ref_format",
            "ref_digest",
            "origin_ref_binding",
            "target_binding",
        )
    }
    for group_id, expected in expected_ref_groups.items():
        if grouped_cases["COR-07"][group_id] != expected:
            return f"COR-07 exact ref-owner group differs: {group_id}"
    target_cases = grouped_cases["COR-07"]["target_transaction"]
    origin_cases = grouped_cases["COR-07"]["origin_ancestry_binding"][:72]
    expected_target = branch_wrapped_visible_cases("target")
    expected_origin = branch_wrapped_visible_cases("origin")
    origin_tail = grouped_cases["COR-07"]["origin_ancestry_binding"][72:]
    if (
        target_cases != expected_target
        or origin_cases != expected_origin
        or origin_tail != REF_OWNER_ERROR_CASES["origin_ancestry_binding"]
    ):
        return "target/origin transaction preservation copies differ"
    ref_cases = tuple(
        leaf
        for group_id, leaves in REF_OWNER_ERROR_CASES.items()
        for leaf in leaves
        if group_id != "target_transaction"
    )
    if len(ref_cases) != 17 or set(REF_RECOVERY_CODES) != {
        code for _leaf, code, _variant, _chain in ref_cases
    }:
        return "exact 17-case ref-owner preservation authority differs"
    expected_specs = {
        (row_id, group_id, leaf_id): (code, variant, source_chain)
        for row_id, groups in grouped_cases.items()
        for group_id, leaves in groups.items()
        for leaf_id, code, variant, source_chain in leaves
    }
    if (
        not isinstance(grouped_specs, dict)
        or tuple(grouped_specs) != tuple(flattened_keys)
        or grouped_specs != expected_specs
    ):
        return "flattened grouped error specification order differs"
    expected_operation_keys = set(flattened_keys)
    found_operation_keys: set[tuple[str, str, str]] = set()
    if not isinstance(operation_calls, dict) or tuple(operation_calls) != (
        "transaction_recovery",
        "ref_recovery",
    ):
        return "grouped error operation vocabulary/order differs"
    for cases in operation_calls.values():
        if not isinstance(cases, frozenset):
            return "grouped error operation coverage is not immutable"
        if found_operation_keys.intersection(cases):
            return "one grouped error leaf maps to multiple operations"
        found_operation_keys.update(cases)
    if found_operation_keys != expected_operation_keys:
        return "grouped error operation coverage differs"
    if (
        not isinstance(expected_digest, str)
        or grouped_error_cases_sha256(grouped_cases) != expected_digest
    ):
        return "grouped error canonical tuple digest differs"
    return None


def corruption_fixture_metadata_problem(
    specs: object = CORRUPTION_FIXTURE_SPECS,
    expected_digest: object = CORRUPTION_FIXTURE_SPECS_SHA256,
) -> str | None:
    expected_keys = tuple(
        (row_id, group_id, leaf_id)
        for row_id, groups in GROUPED_ERROR_CASES.items()
        for group_id, leaves in groups.items()
        for leaf_id, _code, _variant, _source_chain in leaves
    )
    if not isinstance(specs, dict) or tuple(specs) != expected_keys:
        return "corruption fixture keys/order differ"
    if len(specs) != 235:
        return "corruption fixture authority is not exactly 235 leaves"
    if any(not isinstance(spec, CorruptionFixtureSpec) for spec in specs.values()):
        return "corruption fixture authority contains a malformed spec"
    expected_specs = corruption_fixture_specs()
    if specs != expected_specs:
        return "corruption fixture recipes differ from the closed generator"
    assert all(isinstance(spec, CorruptionFixtureSpec) for spec in specs.values())
    for key, spec in specs.items():
        if any(
            not value
            for value in (
                spec.owner_source,
                spec.fixture_family,
                spec.recovery_operation,
                spec.expected_code,
                spec.expected_variant,
                spec.target_role,
                spec.artifact_role,
                spec.identity_recipe,
                spec.path_recipe,
                spec.corrupter_class,
                spec.probe_class,
                spec.selector,
            )
        ):
            return f"corruption fixture spec contains an empty field: {key!r}"
        if not spec.required_facts or len(spec.required_facts) != len(
            set(spec.required_facts)
        ):
            return f"corruption fixture facts are empty or duplicated: {key!r}"
    family_counts = {
        family: sum(spec.fixture_family == family for spec in specs.values())
        for family in ("visible_revision", "accepted_head_pointer", "ref_owner")
    }
    if family_counts != {
        "visible_revision": 216,
        "accepted_head_pointer": 2,
        "ref_owner": 17,
    }:
        return "corruption fixture family cardinalities differ"
    visible_specs = tuple(
        spec for spec in specs.values() if spec.fixture_family == "visible_revision"
    )
    class_counts = {
        fixture_class: sum(
            spec.corrupter_class == fixture_class for spec in visible_specs
        )
        for fixture_class in VISIBLE_REVISION_FIXTURE_CLASS_COUNTS
    }
    if class_counts != {
        fixture_class: count * 3
        for fixture_class, count in VISIBLE_REVISION_FIXTURE_CLASS_COUNTS.items()
    }:
        return "visible-revision fixture class cardinalities differ"
    visible_by_selector_role = {
        (spec.selector, spec.target_role): spec for spec in visible_specs
    }
    if len(visible_by_selector_role) != 216:
        return "visible-revision selector/role identities are not unique"
    for visible_case in VISIBLE_REVISION_CASES:
        selector = visible_case[0]
        role_specs = {}
        for role in (
            "ACCEPTED_REVISION",
            "BRANCH_HEAD_REVISION",
            "BRANCH_ORIGIN_REVISION",
        ):
            try:
                role_specs[role] = visible_by_selector_role[(selector, role)]
            except KeyError:
                return f"visible-revision role copy is absent: {selector}/{role}"
        target = role_specs["BRANCH_HEAD_REVISION"]
        origin = role_specs["BRANCH_ORIGIN_REVISION"]
        differing_fields = {
            field
            for field in CorruptionFixtureSpec._fields
            if getattr(target, field) != getattr(origin, field)
        }
        if differing_fields != {
            "target_role",
            "identity_recipe",
            "distinct_from_roles",
        }:
            return f"target/origin fixture copies differ outside role binding: {selector}"
        if (
            target.identity_recipe != "decoded_ref_head_transaction_id"
            or origin.identity_recipe != "decoded_origin_transaction_id"
            or target.distinct_from_roles != ("BRANCH_ORIGIN_REVISION",)
            or origin.distinct_from_roles != ("BRANCH_HEAD_REVISION",)
        ):
            return f"target/origin role bindings differ: {selector}"
        for spec in (target, origin):
            if not set(VISIBLE_REVISION_BRANCH_FACTS).issubset(
                spec.required_facts
            ):
                return f"branch role-distinction facts are absent: {selector}"
            if spec.corrupter_class.startswith("object_") and not set(
                VISIBLE_REVISION_BRANCH_OBJECT_FACTS
            ).issubset(spec.required_facts):
                return f"branch object-distinction facts are absent: {selector}"
    if set(REF_OWNER_REQUIRED_FACTS_BY_LEAF) != set(REF_OWNER_FIXTURE_RECIPES):
        return "ref-owner fact authority does not cover the exact 17 recipes"
    ref_specs = {
        spec.selector: spec
        for spec in specs.values()
        if spec.fixture_family == "ref_owner"
    }
    if len(ref_specs) != 17 or set(ref_specs) != set(REF_OWNER_FIXTURE_RECIPES):
        return "ref-owner fixture selector coverage differs"
    for selector, spec in ref_specs.items():
        if spec.required_facts != REF_OWNER_REQUIRED_FACTS_BY_LEAF[selector]:
            return f"ref-owner class-specific facts differ: {selector}"
    filesystem_facts = {
        "artifact_path_from_target",
        "artifact_kind",
        "artifact_bytes_or_absence",
    }
    for selector in ("branch_ancestry_cycle", "branch_resource_limit"):
        if filesystem_facts.intersection(ref_specs[selector].required_facts):
            return f"logical graph plan retains singular filesystem facts: {selector}"
    if not {
        "logical_graph_nodes",
        "logical_graph_edges_l_r_l",
        "production_traversal_core",
    }.issubset(ref_specs["branch_ancestry_cycle"].required_facts):
        return "logical cycle plan lacks exact graph/core facts"
    if not {
        "logical_chain_limit",
        "logical_chain_limit_plus_one",
        "only_target_limit_lowered",
        "scanned_peak_within_limit",
        "retained_peak_within_limit",
        "production_traversal_core",
    }.issubset(ref_specs["branch_resource_limit"].required_facts):
        return "logical resource-limit plan lacks N/N+1 budget/core facts"
    origin_topology_facts = set(
        ref_specs["branch_origin_mismatch"].required_facts
    )
    for role in ("origin", "head"):
        for claim in (
            "transaction_id",
            "workspace_id",
            "state_root",
            "schema_epoch",
            "policy_root",
            "dependency_roots",
        ):
            if f"{role}_{claim}_claim" not in origin_topology_facts:
                return "origin/head topology lacks all twelve direct claim facts"
    if "origin_not_reachable_from_head" not in origin_topology_facts:
        return "origin/head topology lacks exact nonreachability evidence"
    if (
        not isinstance(expected_digest, str)
        or corruption_fixture_specs_sha256(specs) != expected_digest
    ):
        return "corruption fixture authority digest differs"
    return None


def corruption_fixture_plan_render_problem(
    key: tuple[str, str, str],
    spec: CorruptionFixtureSpec,
    digest: object,
    rendered: object,
) -> str | None:
    if not isinstance(digest, str) or re.fullmatch(r"[0-9a-f]{64}", digest) is None:
        return "fixture plan digest is not one lowercase SHA-256"
    if not isinstance(rendered, FixtureRender):
        return "fixture plan renderer did not return FixtureRender"
    if tuple(rendered.fact_assertions) != spec.required_facts:
        return "fixture assertion keys/order differ from required facts"
    assertion_values = tuple(rendered.fact_assertions.values())
    if len(set(assertion_values)) != len(assertion_values):
        return "fixture assertions are not unique"
    if not rendered.statements:
        return "fixture plan contains no statements"
    expected_first = f"let fixture = Fixture::new({json.dumps(corruption_fixture_label(key))});"
    if normalize_rust_tokens(rendered.statements[0]) != normalize_rust_tokens(
        expected_first
    ):
        return "fixture plan does not begin with one fresh Fixture"
    expected_last = f"let result = {error_operation_call(*key)};"
    if normalize_rust_tokens(rendered.statements[-1]) != normalize_rust_tokens(
        expected_last
    ):
        return "fixture plan does not end at the exact production recovery call"
    normalized_statements = tuple(
        normalize_rust_tokens(statement) for statement in rendered.statements
    )
    if len(set(normalized_statements)) != len(normalized_statements):
        return "fixture plan reuses one exact statement"
    for fact, assertion in rendered.fact_assertions.items():
        if not isinstance(assertion, str) or ASSERTION_MACRO.match(assertion) is None:
            return f"fixture fact {fact!r} is not one direct assertion macro"
        normalized = normalize_rust_tokens(assertion)
        if normalized_statements.count(normalized) != 1:
            return f"fixture fact {fact!r} is not one exact plan statement"
        operands = exact_assert_eq_operands(assertion)
        if operands is not None and code_only_normalized(
            operands[0]
        ) == code_only_normalized(operands[1]):
            return f"fixture fact {fact!r} is reflexive"
        predicate = exact_assert_predicate(assertion)
        if predicate is not None and re.fullmatch(RUST_IDENTIFIER, predicate):
            return f"fixture fact {fact!r} trusts one local boolean"
    if len(rendered.helper_ids) != 5 or len(set(rendered.helper_ids)) != 5:
        return "fixture plan does not bind five unique helper roots"
    projected = rust_code_projection("\n".join(rendered.statements))
    for helper in rendered.helper_ids:
        if re.fullmatch(RUST_IDENTIFIER, helper) is None:
            return f"fixture helper identifier is malformed: {helper!r}"
        calls = re.findall(rf"\b{re.escape(helper)}\s*\(", projected)
        if len(calls) != 1:
            return f"fixture helper {helper!r} is not called exactly once"
    operation = error_operation_call(*key)
    if code_only_normalized(projected).count(code_only_normalized(operation)) != 1:
        return "production recovery operation is not called exactly once"
    return None


def corruption_fixture_plan_metadata_problem() -> str | None:
    if tuple(CORRUPTION_FIXTURE_RENDERERS) != (
        "visible_revision",
        "accepted_head_pointer",
        "ref_owner",
    ):
        return "corruption fixture family renderer vocabulary/order differs"
    plan_digests: list[str] = []
    helper_roots: set[tuple[str, str]] = set()
    for key, spec in CORRUPTION_FIXTURE_SPECS.items():
        digest, rendered = corruption_fixture_plan(key, spec)
        if problem := corruption_fixture_plan_render_problem(
            key,
            spec,
            digest,
            rendered,
        ):
            return f"{key!r} {problem}"
        plan_digests.append(digest)
        helper_roots.update((spec.owner_source, helper) for helper in rendered.helper_ids)
    if len(plan_digests) != 235 or len(set(plan_digests)) != 235:
        return "corruption fixture plan digests are not exactly 235 unique values"
    if len(helper_roots) != 77:
        return "corruption fixture helper-root authority is not exactly 77 functions"
    return None


def multifault_expected_winner_authority(
    key: MultifaultKey,
) -> ErrorAuthority:
    row_id, subcase_id, leaf_id = key
    if leaf_id is not None:
        code, variant, chain = grouped_error_case_spec(
            row_id,
            subcase_id,
            leaf_id,
        )
        return code_error_authority(code, variant, chain)
    if row_id in ERROR_CASE_SPECS:
        code, variant, chain = error_case_spec(row_id, subcase_id)
        return code_error_authority(code, variant, chain)
    if row_id in OWNED_ENTRY_ERROR_CODES:
        variant = "commit.io" if row_id == "COR-02" else "branch.io"
        return code_error_authority(
            OWNED_ENTRY_ERROR_CODES[row_id],
            variant,
            ("io::Error(Other)",),
        )
    limit_authority = {
        ("LIMIT-02", "final_receipts"): code_error_authority(
            "TXN_RESOURCE_LIMIT",
            "commit.transaction",
        ),
        ("LIMIT-03", "final_origins"): code_error_authority(
            "BRANCH_RESOURCE_LIMIT",
            "branch.branch",
        ),
    }
    try:
        return limit_authority[(row_id, subcase_id)]
    except KeyError:
        fail(f"{key!r} lacks an independent multifault winner authority")


def error_authority_problem(authority: object) -> str | None:
    if not isinstance(authority, ErrorAuthority):
        return "is not typed ErrorAuthority"
    if authority.kind == "code":
        if (
            not isinstance(authority.code, str)
            or not authority.code
            or not authority.variant
            or authority.fields
        ):
            return "code authority fields differ"
    elif authority.kind == "enum_fields":
        if authority.code is not None or authority.source_chain:
            return "enum authority retains code or source-chain authority"
        if authority.variant not in {
            "RecoveryAncestryError::ClaimMismatch",
            "RecoveryAncestryError::Cycle",
        }:
            return "enum authority variant differs"
        expected_fields = (
            (("request_index", 0), ("claim_index", 0))
            if authority.variant.endswith("ClaimMismatch")
            else ()
        )
        if authority.fields != expected_fields:
            return "enum authority fields/order differ"
    else:
        return "kind is not code or enum_fields"
    if any(not isinstance(item, str) or not item for item in authority.source_chain):
        return "source chain is malformed"
    return None


def fault_overlay_problem(overlay: object) -> str | None:
    if not isinstance(overlay, FaultOverlay):
        return "is not typed FaultOverlay"
    if any(
        not isinstance(value, str) or not value
        for value in overlay[:-1]
    ):
        return "contains an empty closed identifier"
    if (
        not overlay.required_facts
        or len(overlay.required_facts) != len(set(overlay.required_facts))
        or any(not isinstance(fact, str) or not fact for fact in overlay.required_facts)
    ):
        return "required facts are empty, duplicated, or malformed"
    return None


def multifault_overlay_metadata_problem(
    registry: object = MULTIFAULT_OVERLAY_REGISTRY,
    expected_digest: object = MULTIFAULT_OVERLAY_REGISTRY_SHA256,
) -> str | None:
    expected_keys = (
        ("ANC-04", "accepted_nested_codec_before_cycle", None),
        ("ANC-04", "verifier_nested_codec_before_claim_mismatch", None),
        ("ANC-04", "verifier_nested_store_before_cycle", None),
        ("ANC-06", "ref_nested_codec_before_claim_mismatch", None),
        ("ANC-06", "ref_nested_store_before_cycle", None),
        ("COR-02", "symlink", None),
        ("LIMIT-02", "final_receipts", None),
        ("COR-04", "symlink", None),
        ("LIMIT-03", "final_origins", None),
        ("COR-06", "head_checksum", "head_shape_before_receipt_missing"),
        ("COR-06", "head_checksum", "head_checksum_before_receipt_corrupt"),
        ("COR-07", "origin_format", "branch_record_format_version"),
        ("COR-07", "origin_digest", "branch_record_digest_mismatch"),
        ("COR-07", "ref_format", "ref_format_version"),
        ("COR-07", "ref_digest", "ref_digest_mismatch"),
    )
    if not isinstance(registry, tuple) or len(registry) != 15:
        return "registry is not one exact 15-record tuple"
    if any(
        not isinstance(item, tuple)
        or len(item) != 2
        or not isinstance(item[0], tuple)
        or len(item[0]) != 3
        or not isinstance(item[1], MultifaultOverlaySpec)
        for item in registry
    ):
        return "registry contains a malformed record"
    keys = tuple(key for key, _spec in registry)
    if keys != expected_keys or len(set(keys)) != 15:
        return "registry keys/order differ or contain duplicates"
    for key, spec in registry:
        if any(
            not isinstance(value, str) or not value
            for value in (
                spec.owner_source,
                spec.recovery_operation,
                spec.fresh_fixture_recipe,
                spec.receiver_recipe,
                spec.guard_recipe,
                spec.distinctness_class,
                spec.repair_class,
                spec.operation_1_profile,
                spec.operation_2_profile,
            )
        ):
            return f"{key!r} contains an empty closed identifier"
        if spec.guard_recipe != "same_root_exclusive":
            return f"{key!r} does not bind one same-root exclusive guard"
        if problem := fault_overlay_problem(spec.primary):
            return f"{key!r} primary overlay {problem}"
        if problem := fault_overlay_problem(spec.secondary):
            return f"{key!r} secondary overlay {problem}"
        if problem := error_authority_problem(spec.winner):
            return f"{key!r} winner authority {problem}"
        if problem := error_authority_problem(spec.loser):
            return f"{key!r} loser authority {problem}"
        if spec.winner != multifault_expected_winner_authority(key):
            return f"{key!r} winner differs from independent error authority"
        operation = (
            grouped_error_operation_name(key[0], key[1], str(key[2]))
            if key[2] is not None
            else error_operation_name(key[0], key[1])
        )
        if spec.recovery_operation != operation:
            return f"{key!r} recovery operation differs"
        expected_owner = (
            REF_PROVENANCE_SOURCE
            if operation == "ref_recovery"
            else TXN_PROVENANCE_SOURCE
        )
        if spec.owner_source != expected_owner:
            return f"{key!r} owner source differs"
        is_limit = key[:2] in {
            ("LIMIT-02", "final_receipts"),
            ("LIMIT-03", "final_origins"),
        }
        if is_limit == (spec.operation_1_profile == spec.operation_2_profile):
            return f"{key!r} two-operation profile relationship differs"
    expected_cycle_epochs = {
        ("ANC-04", "accepted_nested_codec_before_cycle", None): (
            CycleEpochContract(2, 1, (1, 0), 1, (1, 1), "RIGHT_RECEIPT")
        ),
        ("ANC-04", "verifier_nested_store_before_cycle", None): (
            CycleEpochContract(2, 1, (1, 0), 1, (1, 1), "RIGHT_OBJECT")
        ),
        ("ANC-06", "ref_nested_store_before_cycle", None): CycleEpochContract(
            2,
            1,
            (1, 0),
            1,
            (1, 1),
            "DEPTH_ONE_RIGHT_ANCESTOR_OBJECT",
        ),
        ("COR-07", "ref_digest", "ref_digest_mismatch"): CycleEpochContract(
            1,
            0,
            (0, 0),
            1,
            (1, 1),
            None,
        ),
    }
    actual_cycle_epochs = {
        key: spec.cycle_epochs
        for key, spec in registry
        if spec.cycle_epochs is not None
    }
    if actual_cycle_epochs != expected_cycle_epochs:
        return "cycle epoch contracts differ from the exact four-case authority"
    if set(GROUPED_MULTIFAULT_SECONDARY_FIXTURE_KEYS) != set(expected_keys[9:]):
        return "grouped secondary fixture-reference coverage differs"
    overlay_map = dict(registry)
    for key, secondary_key in GROUPED_MULTIFAULT_SECONDARY_FIXTURE_KEYS.items():
        spec = overlay_map[key]
        primary_base = CORRUPTION_FIXTURE_SPECS[key]
        secondary_base = CORRUPTION_FIXTURE_SPECS[secondary_key]
        for label, overlay, base in (
            ("primary", spec.primary, primary_base),
            ("secondary", spec.secondary, secondary_base),
        ):
            if (
                overlay.role,
                overlay.identity_recipe,
                overlay.path_recipe,
                overlay.corrupter_class,
                overlay.probe_class,
            ) != (
                base.target_role,
                base.identity_recipe,
                base.path_recipe,
                base.corrupter_class,
                base.probe_class,
            ):
                return f"{key!r} {label} does not bind its exact grouped fixture"
    if MULTIFAULT_CASES != frozenset((row, subcase) for row, subcase, _ in expected_keys[:9]):
        return "derived non-grouped multifault view differs"
    if GROUPED_MULTIFAULT_CASES != frozenset(expected_keys[9:]):
        return "derived grouped multifault view differs"
    if (
        not isinstance(expected_digest, str)
        or multifault_overlay_registry_sha256(registry) != expected_digest
    ):
        return "registry digest differs"
    return None


def recovery_success_metadata_problem(
    expectations: object = RECOVERY_SUCCESS_EXPECTATIONS,
) -> str | None:
    expected = {
        "CROSS-01": ("old_transaction_id", "old_transaction_id", 1, 1, 1),
        "CROSS-02": ("old_transaction_id", "new_transaction_id", 1, 2, 0),
        "CROSS-03": ("new_transaction_id", "old_transaction_id", 2, 1, 1),
        "CROSS-04": ("new_transaction_id", "new_transaction_id", 2, 2, 0),
        "ANC-01": ("head_transaction_id", None, 4, None, None),
        "ANC-02": (None, None, None, 4, 0),
    }
    if not isinstance(expectations, dict) or expectations != expected:
        return "success topology and report expectations differ"
    if tuple(expectations) != (
        "CROSS-01",
        "CROSS-02",
        "CROSS-03",
        "CROSS-04",
        "ANC-01",
        "ANC-02",
    ):
        return "success-row order differs"
    return None


def require_evidence_metadata() -> None:
    if problem := limit_profile_metadata_problem():
        fail(f"exact limit profile metadata differs: {problem}")
    if problem := limit_event_metadata_problem():
        fail(f"exact limit event metadata differs: {problem}")
    if problem := durability_retry_protocol_problem(DURABILITY_RETRY_PROTOCOLS):
        fail(f"exact durability retry protocols differ: {problem}")
    if problem := durability_result_metadata_problem():
        fail(f"exact durability result metadata differs: {problem}")
    if problem := error_metadata_problem(
        ERROR_CASE_SPECS,
        ROW_ERROR_SPECS,
        ERROR_OPERATION_CALLS,
    ):
        fail(f"exact error metadata differs: {problem}")
    if problem := recovery_provenance_metadata_problem():
        fail(f"exact recovery provenance metadata differs: {problem}")
    if problem := grouped_error_metadata_problem():
        fail(f"grouped corruption error metadata differs: {problem}")
    if problem := corruption_fixture_metadata_problem():
        fail(f"grouped corruption fixture metadata differs: {problem}")
    if problem := corruption_fixture_plan_metadata_problem():
        fail(f"grouped corruption fixture plan metadata differs: {problem}")
    if problem := multifault_overlay_metadata_problem():
        fail(f"multifault overlay metadata differs: {problem}")
    if problem := multifault_fixture_renderer_metadata_problem():
        fail(f"multifault fixture renderer metadata differs: {problem}")
    if problem := recovery_success_metadata_problem():
        fail(f"recovery success metadata differs: {problem}")
    expected_gc_canary_kinds = frozenset(
        {
            *(
                ("COR-08", subcase_id, "gc_witness")
                for subcase_id in EVIDENCE_FAMILIES["COR-08"]
            ),
            ("GUARD-05", None, "gc_witness"),
            ("GUARD-06", None, "gc_witness"),
        }
    )
    if frozenset(PREFLIGHT_CANARY_KINDS) != expected_gc_canary_kinds:
        fail("GC witness canary-kind coverage differs")
    if frozenset(PREFLIGHT_CANARY_FIXTURE_ASSERTIONS) != expected_gc_canary_kinds:
        fail("GC witness fixture-assertion coverage differs")


def error_case_spec(
    row_id: str,
    subcase_id: str | None,
) -> tuple[str, str, tuple[str, ...]]:
    if subcase_id is None:
        try:
            return ROW_ERROR_SPECS[row_id]
        except KeyError:
            fail(f"{row_id} lacks an exact non-family error specification")
    try:
        return ERROR_CASE_SPECS[row_id][subcase_id]
    except KeyError:
        fail(f"{row_id}/{subcase_id} lacks an exact error specification")


def error_operation_name(row_id: str, subcase_id: str | None) -> str:
    key = (row_id, subcase_id)
    operations = tuple(
        operation for operation, cases in ERROR_OPERATION_CALLS.items() if key in cases
    )
    if len(operations) != 1:
        fail(f"{row_id}/{subcase_id} lacks one exact recovery operation")
    return operations[0]


def grouped_error_case_spec(
    row_id: str,
    group_id: str,
    leaf_id: str,
) -> tuple[str, str, tuple[str, ...]]:
    try:
        return GROUPED_ERROR_SPECS[(row_id, group_id, leaf_id)]
    except KeyError:
        fail(f"{row_id}/{group_id}/{leaf_id} lacks an exact error specification")


def grouped_error_operation_name(row_id: str, group_id: str, leaf_id: str) -> str:
    key = (row_id, group_id, leaf_id)
    operations = tuple(
        operation
        for operation, cases in GROUPED_ERROR_OPERATION_CALLS.items()
        if key in cases
    )
    if len(operations) != 1:
        fail(f"{row_id}/{group_id}/{leaf_id} lacks one exact recovery operation")
    return operations[0]


def error_operation_call(
    row_id: str,
    subcase_id: str | None,
    leaf_id: str | None = None,
) -> str:
    operation = (
        error_operation_name(row_id, subcase_id)
        if leaf_id is None
        else grouped_error_operation_name(row_id, str(subcase_id), leaf_id)
    )
    calls = {
        "transaction_recovery": ("repository.recover_with_maintenance(&maintenance)"),
        "ancestry_verifier": (
            "repository.verify_branch_recovery_ancestries_with_maintenance("
            "&maintenance, &requests)"
        ),
        "ref_recovery": (
            "branch_repository.recover_refs_with_maintenance(&maintenance)"
        ),
        "gc_witness_recovery": ("super::recover_gc_witness(&store, &maintenance)"),
    }
    return calls[operation]


def error_operation_owner_root(
    row_id: str,
    subcase_id: str | None,
    leaf_id: str | None = None,
) -> str:
    operation = (
        error_operation_name(row_id, subcase_id)
        if leaf_id is None
        else grouped_error_operation_name(row_id, str(subcase_id), leaf_id)
    )
    roots = {
        "transaction_recovery": "repository.root()",
        "ancestry_verifier": "repository.root()",
        "ref_recovery": "branch_repository.root()",
        "gc_witness_recovery": "store.root()",
    }
    return roots[operation]


def repository_exports_problem(source: str, required: tuple[str, ...]) -> str | None:
    matches = direct_code_matches(
        source, r"\bpub\s+use\s+repository::\{(?P<body>.*?)\};"
    )
    if len(matches) != 1:
        return "lacks one exact crate-root repository re-export block"
    exported = tuple(
        item.strip() for item in matches[0]["body"].split(",") if item.strip()
    )
    if any(re.fullmatch(RUST_IDENTIFIER, item) is None for item in exported):
        return "contains a non-identifier or aliased repository re-export"
    if exported != required:
        return f"ordered repository exports differ: {exported!r}"
    return None


def require_repository_exports(source: str, required: tuple[str, ...]) -> None:
    if problem := repository_exports_problem(source, required):
        fail(f"sley-txn repository re-export block differs: {problem}")


def mapped_commit_type_paths(relative: str) -> tuple[str, str]:
    if relative == "crates/sley-txn/src/repository.rs":
        return "super::CommitError", "crate::codec::TransactionCodecError"
    if relative == "crates/sley-repo/src/refs.rs":
        return "::sley_txn::CommitError", "::sley_txn::TransactionCodecError"
    fail(f"error evidence has no closed type-path context for {relative}")


def commit_variant_pattern(relative: str, variant: str) -> str:
    commit, codec = mapped_commit_type_paths(relative)
    patterns = {
        "commit.codec.scb": f"{commit}::Codec({codec}::Scb(_))",
        "commit.codec.transaction": f"{commit}::Codec({codec}::Transaction(_))",
        "commit.codec.candidate": f"{commit}::Codec({codec}::Candidate(_))",
        "commit.codec.candidate_result": (
            f"{commit}::Codec({codec}::CandidateResult(_))"
        ),
        "commit.codec.state_root.scb": (
            f"{commit}::Codec({codec}::StateRoot("
            "::sley_state_root::StateRootError::Scb(_)))"
        ),
        "commit.codec.state_root.schema": (
            f"{commit}::Codec({codec}::StateRoot("
            "::sley_state_root::StateRootError::Schema(_)))"
        ),
        "commit.codec.state_root.semantic": (
            f"{commit}::Codec({codec}::StateRoot("
            "::sley_state_root::StateRootError::StateRoot(_)))"
        ),
        "commit.codec.policy_root.scb": (
            f"{commit}::Codec({codec}::PolicyRoot("
            "::sley_policy::PolicyRootError::Scb(_)))"
        ),
        "commit.codec.policy_root.schema": (
            f"{commit}::Codec({codec}::PolicyRoot("
            "::sley_policy::PolicyRootError::Schema(_)))"
        ),
        "commit.codec.policy_root.semantic": (
            f"{commit}::Codec({codec}::PolicyRoot("
            "::sley_policy::PolicyRootError::PolicyRoot(_)))"
        ),
        "commit.store": f"{commit}::Store(_)",
        "commit.transaction": f"{commit}::Transaction(_)",
        "commit.io": f"{commit}::Io(_)",
    }
    try:
        return patterns[variant]
    except KeyError:
        fail(f"unknown closed commit variant path {variant!r}")


def error_variant_pattern(relative: str, variant: str) -> str:
    if variant == "gc.exclusive_lock_required":
        if relative != "crates/sley-repo/src/gc.rs":
            fail(f"GC error variant has the wrong source owner {relative}")
        return (
            "super::GcError { "
            'symbol: "GC_EXCLUSIVE_LOCK_REQUIRED", '
            "partial_report: ::core::option::Option::None, "
            "source: ::core::option::Option::None }"
        )
    if variant.startswith("commit."):
        return commit_variant_pattern(relative, variant)
    ancestry_prefix = "ancestry.verification."
    if variant.startswith(ancestry_prefix):
        inner = variant[len(ancestry_prefix) :]
        return (
            "super::RecoveryAncestryError::Verification("
            f"{commit_variant_pattern(relative, inner)})"
        )
    branch_prefix = "branch.transaction."
    if variant.startswith(branch_prefix):
        inner = variant[len(branch_prefix) :]
        return (
            "super::BranchError::Transaction("
            f"{commit_variant_pattern(relative, inner)})"
        )
    if variant == "branch.branch":
        return "super::BranchError::Branch(_)"
    if variant == "branch.io":
        return "super::BranchError::Io(_)"
    fail(f"unknown closed error variant path {variant!r}")


def exact_error_variant_assertion_problem(
    assertion: object,
    relative: str,
    variant: str,
    *,
    subject: str = "&error",
) -> str | None:
    if not isinstance(assertion, str):
        return "variant assertion is not text"
    predicate = exact_assert_predicate(assertion)
    expected = code_only_normalized(
        f"::core::matches!({subject},{error_variant_pattern(relative, variant)})"
    )
    if predicate != expected:
        return "variant assertion is not the exact closed matches! path"
    return None


def exact_error_result_assertion_problem(
    assertion: object,
    relative: str,
    variant: str,
    expected: str,
) -> str | None:
    if not isinstance(assertion, str):
        return "result assertion is not text"
    operands = exact_assert_eq_operands(assertion)
    if operands is None:
        return "result assertion is not exact two-operand assert_eq!"
    literal = json.dumps(expected)
    if operands[0].strip() == literal:
        claim = operands[1]
    elif operands[1].strip() == literal:
        claim = operands[0]
    else:
        return "result symbol is not an exact equality operand"
    if variant.startswith("ancestry.verification."):
        expected_claim = (
            "match &error { "
            "super::RecoveryAncestryError::Verification(inner) => inner.code(), "
            '_ => "", }'
        )
    elif variant.startswith("gc."):
        expected_claim = "error.symbol()"
    else:
        expected_claim = "error.code()"
    if normalize_rust_tokens(claim) != normalize_rust_tokens(expected_claim):
        return "result assertion does not project the exact owning error"
    return None


