def contiguous_code_ranges_problem(
    body: str,
    ranges: tuple[tuple[int, int], ...],
    label: str,
) -> str | None:
    if not ranges:
        return f"{label} has no statements"
    for left, right in zip(ranges, ranges[1:]):
        if left[0] >= left[1] or left[1] > right[0] or right[0] >= right[1]:
            return f"{label} statement ranges are misordered"
        if rust_code_projection(body[left[1] : right[0]]).strip():
            return f"{label} contains an unbound intervening statement"
    return None


def recovery_success_fixture_binding_problem(
    body: str,
    relative: str,
    row_id: str,
    operation_ranges: dict[str, tuple[int, int]],
) -> str | None:
    helper = snapshot_helper_path(relative, "exact_path_snapshot")
    if row_id.startswith("CROSS-"):
        fixed_lets = {
            "old_revision": (
                "let old_revision = transaction_repository"
                ".verified_revision(old_transaction_id).unwrap();"
            ),
            "new_revision": (
                "let new_revision = transaction_repository"
                ".verified_revision(new_transaction_id).unwrap();"
            ),
            "accepted_before": (
                "let accepted_before = transaction_repository.accepted_head().unwrap();"
            ),
            "branch_before": (
                "let branch_before = branch_repository"
                ".resolve_branch(&branch_name).unwrap();"
            ),
            "accepted_path": (
                "let accepted_path = transaction_repository.root()"
                '.join("refs").join("accepted");'
            ),
            "ref_path": (
                "let ref_path = branch_repository"
                ".checked_ref_path(&branch_name).unwrap();"
            ),
            "maintenance": (
                "let maintenance = branch_repository"
                ".acquire_exclusive_maintenance().unwrap();"
            ),
            "accepted_after": (
                "let accepted_after = transaction_repository.accepted_head().unwrap();"
            ),
            "branch_after": (
                "let branch_after = branch_repository"
                ".resolve_branch(&branch_name).unwrap();"
            ),
            "verified_old": (
                "let verified_old = transaction_repository"
                ".verified_revision(old_transaction_id).unwrap();"
            ),
            "verified_new": (
                "let verified_new = transaction_repository"
                ".verified_revision(new_transaction_id).unwrap();"
            ),
        }
        paths = ("accepted", "ref")
        rounds = (
            ("first", ("first_transaction_recovery", "first_ref_recovery")),
            ("second", ("second_transaction_recovery", "second_ref_recovery")),
        )
        guard_assertions = (
            "::core::assert!(maintenance.is_exclusive());",
            "::core::assert!(maintenance.covers(transaction_repository.root()));",
            "::core::assert!(maintenance.covers(branch_repository.root()));",
        )
        post_drop = ("accepted_after", "branch_after", "verified_old", "verified_new")
    elif row_id == "ANC-01":
        fixed_lets = {
            "genesis_revision": (
                "let genesis_revision = repository"
                ".verified_revision(genesis_transaction_id).unwrap();"
            ),
            "first_revision": (
                "let first_revision = repository"
                ".verified_revision(first_transaction_id).unwrap();"
            ),
            "second_revision": (
                "let second_revision = repository"
                ".verified_revision(second_transaction_id).unwrap();"
            ),
            "head_revision": (
                "let head_revision = repository"
                ".verified_revision(head_transaction_id).unwrap();"
            ),
            "accepted_before": (
                "let accepted_before = repository.accepted_head().unwrap();"
            ),
            "accepted_path": (
                'let accepted_path = repository.root().join("refs").join("accepted");'
            ),
            "maintenance": (
                "let maintenance = repository.acquire_exclusive_maintenance().unwrap();"
            ),
            "accepted_after": (
                "let accepted_after = repository.accepted_head().unwrap();"
            ),
        }
        paths = ("accepted",)
        rounds = (
            ("first", ("first_transaction_recovery",)),
            ("second", ("second_transaction_recovery",)),
        )
        guard_assertions = (
            "::core::assert!(maintenance.is_exclusive());",
            "::core::assert!(maintenance.covers(repository.root()));",
        )
        post_drop = ("accepted_after",)
    elif row_id == "ANC-02":
        fixed_lets = {
            "genesis_revision": (
                "let genesis_revision = transaction_repository"
                ".verified_revision(genesis_transaction_id).unwrap();"
            ),
            "shared_revision": (
                "let shared_revision = transaction_repository"
                ".verified_revision(shared_transaction_id).unwrap();"
            ),
            "alpha_revision": (
                "let alpha_revision = transaction_repository"
                ".verified_revision(alpha_transaction_id).unwrap();"
            ),
            "beta_revision": (
                "let beta_revision = transaction_repository"
                ".verified_revision(beta_transaction_id).unwrap();"
            ),
            "alpha_before": (
                "let alpha_before = branch_repository"
                ".resolve_branch(&alpha_branch_name).unwrap();"
            ),
            "beta_before": (
                "let beta_before = branch_repository"
                ".resolve_branch(&beta_branch_name).unwrap();"
            ),
            "alpha_path": (
                "let alpha_path = branch_repository"
                ".checked_ref_path(&alpha_branch_name).unwrap();"
            ),
            "beta_path": (
                "let beta_path = branch_repository"
                ".checked_ref_path(&beta_branch_name).unwrap();"
            ),
            "maintenance": (
                "let maintenance = branch_repository"
                ".acquire_exclusive_maintenance().unwrap();"
            ),
            "alpha_after": (
                "let alpha_after = branch_repository"
                ".resolve_branch(&alpha_branch_name).unwrap();"
            ),
            "beta_after": (
                "let beta_after = branch_repository"
                ".resolve_branch(&beta_branch_name).unwrap();"
            ),
        }
        paths = ("alpha", "beta")
        rounds = (
            ("first", ("first_ref_recovery",)),
            ("second", ("second_ref_recovery",)),
        )
        guard_assertions = (
            "::core::assert!(maintenance.is_exclusive());",
            "::core::assert!(maintenance.covers(transaction_repository.root()));",
            "::core::assert!(maintenance.covers(branch_repository.root()));",
        )
        post_drop = ("alpha_after", "beta_after")
    else:
        return "has no exact successful fixture contract"

    let_ranges: dict[str, tuple[int, int]] = {}
    for identifier, statement in fixed_lets.items():
        found = exact_recorded_let_range(body, identifier, statement)
        if found is None:
            return f"{identifier} fixture binding differs"
        let_ranges[identifier] = found
    maintenance = let_ranges["maintenance"]
    guard_ranges: list[tuple[int, int]] = []
    for assertion in guard_assertions:
        starts = exact_direct_statement_starts(body, assertion)
        if len(starts) != 1 or not (maintenance[1] <= starts[0]):
            return "exclusive same-root guard proof differs"
        guard_ranges.append((starts[0], starts[0] + len(assertion)))

    snapshot_ranges: dict[str, tuple[int, int]] = {}
    for round_name, _operations in rounds:
        for boundary in ("before", "after"):
            for path in paths:
                identifier = f"{path}_{boundary}_{round_name}_snapshot"
                statement = f"let {identifier} = {helper}(&{path}_path);"
                found = exact_snapshot_binding_range(body, identifier, statement)
                if found is None:
                    return f"{identifier} does not use the frozen path snapshot"
                snapshot_ranges[identifier] = found
    critical_ranges: list[tuple[int, int]] = [maintenance, *guard_ranges]
    for index, (round_name, operations) in enumerate(rounds):
        before = tuple(
            snapshot_ranges[f"{path}_before_{round_name}_snapshot"] for path in paths
        )
        after = tuple(
            snapshot_ranges[f"{path}_after_{round_name}_snapshot"] for path in paths
        )
        if max(end for _start, end in before) > min(
            operation_ranges[operation][0] for operation in operations
        ):
            return f"{round_name} before snapshots do not precede recovery"
        if min(start for start, _end in after) < max(
            operation_ranges[operation][1] for operation in operations
        ):
            return f"{round_name} after snapshots do not follow recovery"
        if index + 1 < len(rounds):
            next_name = rounds[index + 1][0]
            next_before = tuple(
                bounds
                for identifier, bounds in snapshot_ranges.items()
                if f"_before_{next_name}_" in identifier
            )
            if max(end for _start, end in after) > min(
                start for start, _end in next_before
            ):
                return "successful recovery round snapshots overlap"
        critical_ranges.extend(
            (
                *before,
                *(operation_ranges[operation] for operation in operations),
                *after,
            )
        )

    drops = exact_direct_statement_starts(body, "drop(maintenance);")
    if len(drops) != 1 or drops[0] < max(
        end for _start, end in snapshot_ranges.values()
    ):
        return "exclusive guard is not dropped after both snapshot rounds"
    drop_range = (drops[0], drops[0] + len("drop(maintenance);"))
    critical_ranges.append(drop_range)
    critical_ranges.extend(let_ranges[name] for name in post_drop)
    if problem := contiguous_code_ranges_problem(
        body,
        tuple(critical_ranges),
        "successful recovery critical window",
    ):
        return problem
    if any(let_ranges[name][0] < drops[0] for name in post_drop):
        return "post-recovery verification occurs before guard release"
    return None


def recovery_success_evidence_problem(
    row_id: str,
    entry: object,
    relative: str,
    body: str,
) -> str | None:
    if not isinstance(entry, dict) or tuple(entry) != RECOVERY_SUCCESS_EVIDENCE_FIELDS:
        return "evidence fields/order differ"
    if entry.get("result") != "PASS" or entry.get("fresh_fixture") is not True:
        return "result or fresh-fixture claim differs"
    if relative != recovery_success_owner(row_id):
        return "mapped test owner differs"
    expected_operations = recovery_success_operation_bindings(row_id)
    operations = entry.get("operation_bindings")
    if (
        not isinstance(operations, dict)
        or operations != expected_operations
        or tuple(operations) != tuple(expected_operations)
    ):
        return "operation bindings differ"
    operation_ranges: dict[str, tuple[int, int]] = {}
    for identifier, statement in operations.items():
        found = exact_recorded_let_range(body, identifier, statement)
        if found is None:
            return f"{identifier} is not one exact recovery result binding"
        operation_ranges[identifier] = found
    ranges = tuple(operation_ranges.values())
    if any(left[1] > right[0] for left, right in zip(ranges, ranges[1:])):
        return "successful recovery operations are misordered"
    if problem := recovery_success_fixture_binding_problem(
        body,
        relative,
        row_id,
        operation_ranges,
    ):
        return problem

    expected_groups = {
        "report_assertions": recovery_success_report_assertions(row_id),
        "pointer_assertions": recovery_success_pointer_assertions(row_id),
        "closure_assertions": recovery_success_closure_assertions(row_id),
    }
    assertions = entry.get("assertions")
    if not isinstance(assertions, list):
        return "assertions are not one list"
    used: set[str] = set()
    for field, expected in expected_groups.items():
        actual = entry.get(field)
        if (
            not isinstance(actual, dict)
            or actual != expected
            or tuple(actual) != tuple(expected)
        ):
            return f"{field} vocabulary, order, or values differ"
        for assertion in actual.values():
            if assertion in used:
                return "one assertion is reused across successful evidence fields"
            if assertion not in assertions or not exact_direct_statement_present(
                body, assertion
            ):
                return f"{field} assertion is absent from the exact mapped test"
            operands = exact_assert_eq_operands(assertion)
            if operands is not None and code_only_normalized(
                operands[0]
            ) == code_only_normalized(operands[1]):
                return f"{field} contains a reflexive assertion"
            used.add(assertion)
    return None


def require_recovery_success_evidence(
    row_id: str,
    entry: dict[str, object],
    relative: str,
    source: str,
) -> None:
    tests = entry.get("tests")
    if not isinstance(tests, list) or len(tests) != 1 or not isinstance(tests[0], str):
        fail(f"{row_id} lacks one exact successful recovery test")
    definition = exact_test_definition(source, tests[0])
    if definition is None:
        fail(f"{row_id} cannot isolate its successful recovery test")
    if problem := recovery_success_evidence_problem(
        row_id,
        entry,
        relative,
        definition[0],
    ):
        fail(f"{row_id} successful recovery evidence differs: {problem}")


def require_grouped_error_evidence(
    row_id: str,
    group_id: str,
    entry: dict[str, object],
    sources: dict[str, str],
    used_tests: list[str],
    test_owners: dict[str, str],
    qualified_tests: dict[str, str],
) -> None:
    label = f"{row_id}/{group_id}"
    if tuple(entry) != GROUPED_ERROR_EVIDENCE_FIELDS:
        fail(f"{label} grouped error-evidence fields/order differ")
    if entry.get("result") != "PASS":
        fail(f"{label} grouped error evidence is not PASS")
    cases = entry.get("cases")
    expected_leaves = GROUPED_ERROR_CASES[row_id][group_id]
    expected_leaf_ids = tuple(
        leaf_id for leaf_id, _code, _variant, _chain in expected_leaves
    )
    if not isinstance(cases, dict) or tuple(cases) != expected_leaf_ids:
        fail(f"{label} grouped error leaf order or vocabulary differs")
    for leaf_id, leaf_entry in cases.items():
        if not isinstance(leaf_entry, dict):
            fail(f"{label}/{leaf_id} error evidence is not an object")
        owner, qualified = require_evidence_tests(
            row_id,
            group_id,
            leaf_entry,
            sources,
            used_tests,
            leaf_id,
        )
        test_owners[used_tests[-1]] = crate_for_source(owner)
        qualified_tests[used_tests[-1]] = qualified
        require_error_case_evidence(
            row_id,
            group_id,
            leaf_entry,
            owner,
            sources[owner],
            leaf_id,
        )
        require_preflight_canary_evidence(
            row_id,
            group_id,
            leaf_entry,
            leaf_id,
        )
        if (row_id, group_id, leaf_id) in GROUPED_MULTIFAULT_CASES:
            require_multifault_evidence(
                row_id,
                group_id,
                leaf_entry,
                owner,
                sources[owner],
                leaf_id,
            )


def cross05_evidence_problem(entry: object) -> str | None:
    if not isinstance(entry, dict) or tuple(entry) != (
        "result",
        "fresh_fixture",
        *CROSS_05_EVIDENCE_FIELDS,
        "semantic_assertions",
        "tests",
        "assertions",
    ):
        return "evidence fields/order differ"
    if entry.get("result") != "PASS" or entry.get("fresh_fixture") is not True:
        return "result or fresh-fixture claim differs"
    if "no_mutation" in entry:
        return "incorrectly claims no mutation"
    semantic = entry.get("semantic_assertions")
    assertions = entry.get("assertions")
    if not isinstance(semantic, dict) or tuple(semantic) != CROSS_05_EVIDENCE_FIELDS:
        return "semantic assertion fields/order differ"
    if not isinstance(assertions, list):
        return "assertions are not a list"
    if len(set(semantic.values())) != len(CROSS_05_EVIDENCE_FIELDS):
        return "reuses a semantic assertion"
    for field in CROSS_05_EVIDENCE_FIELDS:
        if entry.get(field) is not True:
            return f"{field} is not exact true"
        assertion = semantic.get(field)
        if assertion not in assertions:
            return f"{field} assertion is absent"
        if problem := exact_value_assertion_problem(assertion, field, True):
            return f"{field} assertion differs: {problem}"
        if normalize_rust_tokens(assertion) != normalize_rust_tokens(
            f"::core::assert!({field});"
        ):
            return f"{field} is not the exact direct boolean assertion"
    return None


def cross05_exact_let_range(
    body: str, identifier: str, expected: str
) -> tuple[int, int] | None:
    bindings = top_level_let_statement_ranges(body, identifier)
    if len(bindings) != 1 or normalize_rust_tokens(
        bindings[0][2]
    ) != normalize_rust_tokens(expected):
        return None
    return bindings[0][0], bindings[0][1]


def cross05_thread_spawn_closures(
    body: str,
) -> tuple[tuple[int, int, str], ...] | None:
    projected = rust_code_projection(body)
    found: list[tuple[int, int, str]] = []
    for match in re.finditer(r"::\s*std\s*::\s*thread\s*::\s*spawn\s*\(", projected):
        opening = projected.find("(", match.start(), match.end())
        closing = matching_delimiter(
            projected, [True] * len(projected), opening, "(", ")"
        )
        if closing is None:
            return None
        argument = projected[opening + 1 : closing]
        prefix = re.match(r"\s*move\s*\|\s*\|\s*", argument)
        if prefix is None:
            return None
        brace = argument.find("{", prefix.end())
        if brace < 0 or argument[prefix.end() : brace].strip():
            return None
        absolute_brace = opening + 1 + brace
        brace_closing = matching_delimiter(
            projected,
            [True] * len(projected),
            absolute_brace,
            "{",
            "}",
        )
        if brace_closing is None or projected[brace_closing + 1 : closing].strip():
            return None
        found.append(
            (match.start(), closing + 1, body[absolute_brace + 1 : brace_closing])
        )
    return tuple(found)


def cross05_direct_code_ranges(
    source: str, pattern: str
) -> tuple[tuple[int, int], ...]:
    projected = rust_code_projection(source)
    return tuple(
        (match.start(), match.end())
        for match in re.finditer(pattern, projected, re.DOTALL)
        if delimiter_depth_at(source, match.start()) == (0, 0, 0)
    )


def cross05_top_level_statement_ranges(
    source: str, start: int
) -> tuple[tuple[int, int], ...] | None:
    projected = rust_code_projection(source)
    ranges: list[tuple[int, int]] = []
    cursor = start
    round_depth = square_depth = brace_depth = 0
    for index in range(start, len(projected)):
        character = projected[index]
        if character == "(":
            round_depth += 1
        elif character == ")":
            round_depth -= 1
        elif character == "[":
            square_depth += 1
        elif character == "]":
            square_depth -= 1
        elif character == "{":
            brace_depth += 1
        elif character == "}":
            brace_depth -= 1
        elif character == ";" and round_depth == square_depth == brace_depth == 0:
            statement_start = cursor
            while statement_start < index and projected[statement_start].isspace():
                statement_start += 1
            if statement_start <= index:
                ranges.append((statement_start, index + 1))
            cursor = index + 1
        if min(round_depth, square_depth, brace_depth) < 0:
            return None
    if round_depth or square_depth or brace_depth or projected[cursor:].strip():
        return None
    return tuple(ranges)


def cross05_normalized_statement_starts(source: str, expected: str) -> tuple[int, ...]:
    ranges = cross05_top_level_statement_ranges(source, 0)
    if ranges is None:
        return ()
    normalized = normalize_rust_tokens(expected)
    return tuple(
        start
        for start, end in ranges
        if normalize_rust_tokens(source[start:end]) == normalized
    )


def cross05_common_binding_problem(body: str) -> str | None:
    probe_template = (
        "let {name} = ::std::fs::OpenOptions::new()"
        '.read(true).write(true).open(canonical_root.join("locks")'
        '.join("maintenance.lock")).unwrap();'
    )
    for role in ("commit", "ref", "gc"):
        probe = f"{role}_probe"
        if (
            cross05_exact_let_range(body, probe, probe_template.format(name=probe))
            is None
        ):
            return f"{role} probe is not the exact canonical maintenance-lock open"

    blocked_templates = {
        "commit_blocked": (
            "let commit_blocked = ::core::matches!("
            "::std::fs::File::try_lock_shared(&commit_probe), "
            "Err(::std::fs::TryLockError::WouldBlock));"
        ),
        "ref_blocked": (
            "let ref_blocked = ::core::matches!("
            "::std::fs::File::try_lock_shared(&ref_probe), "
            "Err(::std::fs::TryLockError::WouldBlock));"
        ),
        "gc_blocked": (
            "let gc_blocked = ::core::matches!("
            "::std::fs::File::try_lock(&gc_probe), "
            "Err(::std::fs::TryLockError::WouldBlock));"
        ),
    }
    for field, expected in blocked_templates.items():
        if cross05_exact_let_range(body, field, expected) is None:
            return f"{field} is not derived from its exact WouldBlock probe"

    return cross05_witness_binding_problem(body)


def cross05_witness_binding_problem(body: str) -> str | None:
    witness = (
        "let gc_witness_absent_while_blocked = ::core::matches!("
        "::std::fs::symlink_metadata("
        'canonical_root.join("locks").join("gc.lock")), '
        "Err(error) if error.kind() == ::std::io::ErrorKind::NotFound);"
    )
    if (
        cross05_exact_let_range(body, "gc_witness_absent_while_blocked", witness)
        is None
    ):
        return "GC witness absence is not exact canonical-root NotFound metadata"
    return None


def cross05_assertion_order_problem(
    body: str, semantic: dict[str, object]
) -> str | None:
    assertion_starts: dict[str, int] = {}
    for field in CROSS_05_EVIDENCE_FIELDS:
        assertion = semantic.get(field)
        if not isinstance(assertion, str):
            return f"{field} semantic assertion is not text"
        starts = exact_direct_statement_starts(body, assertion)
        if len(starts) != 1:
            return f"{field} assertion is not one direct statement"
        assertion_starts[field] = starts[0]
    blocked = tuple(
        assertion_starts[field]
        for field in ("commit_blocked", "ref_blocked", "gc_blocked")
    )
    resumed = tuple(
        assertion_starts[field]
        for field in ("commit_resumed", "ref_resumed", "gc_resumed")
    )
    if not (
        assertion_starts["exclusive_observed"] < min(blocked)
        and max(blocked)
        < assertion_starts["gc_witness_absent_while_blocked"]
        < min(resumed)
        and max(resumed) < assertion_starts["recovery_completed"]
    ):
        return "blocked, witness, resume, and completion assertions are misordered"
    return None


def cross05_contender_expected_body(role: str) -> str:
    title = {"commit": "Commit", "ref": "Ref", "gc": "Gc"}[role]
    operation = {
        "commit": (
            "let commit_input = ::sley_txn::CommitInput::new("
            "commit_expected_parent, &commit_candidate_bytes, "
            "commit_principal_id, &[], NOW, "
            "::sley_policy::CandidateValidationLimits::full_v1(),);"
            "let operation_result = commit_repository.commit(commit_input);"
        ),
        "ref": (
            "let operation_result = ref_repository.create_branch("
            "branch_name, branch_target);"
        ),
        "gc": (
            "let operation_result = crate::gc::acquire_exclusive_gc(&gc_store)"
            ".and_then(|guard| crate::gc::gc_collect("
            "&gc_store, &gc_snapshot, &gc_verifier, &guard));"
        ),
    }[role]
    lock_call = (
        "::std::fs::File::try_lock(&maintenance_probe)"
        if role == "gc"
        else "::std::fs::File::try_lock_shared(&maintenance_probe)"
    )
    return (
        "let maintenance_probe = ::std::fs::OpenOptions::new()"
        ".read(true).write(true).open("
        f'{role}_root.join("locks").join("maintenance.lock")).unwrap();'
        "let blocked = ::core::matches!("
        f"{lock_call}, Err(::std::fs::TryLockError::WouldBlock));"
        f"::core::assert!({role}_blocked_tx.send("
        f"Cross05Blocked::{title}(blocked)).is_ok());"
        f"{operation}"
        f"::core::assert!({role}_completed_tx.send("
        f"Cross05Completed::{title}(operation_result.is_ok())).is_ok());"
    )


def cross05_contender_problem(closure: str, role: str) -> str | None:
    expected_body = cross05_contender_expected_body(role)
    if normalize_rust_tokens(closure) != normalize_rust_tokens(expected_body):
        return f"{role} closure contains authority outside the exact protocol"
    if len(named_call_argument_ranges(closure, "send")) != 2:
        return f"{role} closure has extra or missing rendezvous sends"
    if named_call_argument_ranges(closure, "spawn"):
        return f"{role} closure contains a nested thread"
    expected_calls = {
        "commit": ("commit",),
        "ref": ("create_branch",),
        "gc": ("acquire_exclusive_gc", "gc_collect"),
    }[role]
    for call in expected_calls:
        if len(named_call_argument_ranges(closure, call)) != 1:
            return f"{role} closure does not invoke exact {call} once"
    blocked_send = named_call_argument_ranges(closure, "send")[0]
    operation_range = top_level_let_statement_ranges(closure, "operation_result")
    if len(operation_range) != 1:
        return f"{role} production result binding differs"
    if blocked_send[1] >= operation_range[0][0]:
        return f"{role} production operation does not immediately follow blocked send"
    return None


def cross05_caller_held_problem(body: str) -> str | None:
    expected_setup = {
        "transaction_repository": (
            "let transaction_repository = "
            "::sley_txn::TransactionRepository::new(canonical_root.clone());"
        ),
        "branch_repository": (
            "let branch_repository = "
            "super::BranchRepository::new(canonical_root.clone());"
        ),
        "object_store": (
            "let object_store = ::sley_store::ObjectStore::new(canonical_root.clone());"
        ),
        "maintenance": (
            "let maintenance = transaction_repository"
            ".acquire_exclusive_maintenance().unwrap();"
        ),
        "transaction_recovery_result": (
            "let transaction_recovery_result = transaction_repository"
            ".recover_with_maintenance(&maintenance);"
        ),
        "ref_recovery_result": (
            "let ref_recovery_result = branch_repository"
            ".recover_refs_with_maintenance(&maintenance);"
        ),
        "gc_recovery_result": (
            "let gc_recovery_result = crate::gc::recover_gc_witness("
            "&object_store, &maintenance);"
        ),
        "exclusive_observed": (
            "let exclusive_observed = maintenance.is_exclusive() "
            "&& maintenance.covers(&canonical_root);"
        ),
        "cross05_blocked_tx": (
            "let (cross05_blocked_tx, cross05_blocked_rx) = "
            "::std::sync::mpsc::sync_channel::<Cross05Blocked>(0);"
        ),
        "cross05_completed_tx": (
            "let (cross05_completed_tx, cross05_completed_rx) = "
            "::std::sync::mpsc::sync_channel::<Cross05Completed>(0);"
        ),
    }
    ranges: dict[str, tuple[int, int]] = {}
    for identifier, expected in expected_setup.items():
        found = cross05_exact_let_range(body, identifier, expected)
        if found is None:
            return f"caller-held {identifier} binding differs"
        ranges[identifier] = found
    if not (
        ranges["maintenance"][0]
        < ranges["transaction_recovery_result"][0]
        < ranges["ref_recovery_result"][0]
        < ranges["gc_recovery_result"][0]
        < ranges["exclusive_observed"][0]
    ):
        return "guarded recovery is not transaction, ref, GC ordered"

    clone_templates = {
        "commit_blocked_tx": ("let commit_blocked_tx = cross05_blocked_tx.clone();"),
        "commit_completed_tx": (
            "let commit_completed_tx = cross05_completed_tx.clone();"
        ),
        "commit_root": "let commit_root = canonical_root.clone();",
        "commit_repository": (
            "let commit_repository = transaction_repository.clone();"
        ),
        "ref_blocked_tx": "let ref_blocked_tx = cross05_blocked_tx.clone();",
        "ref_completed_tx": ("let ref_completed_tx = cross05_completed_tx.clone();"),
        "ref_root": "let ref_root = canonical_root.clone();",
        "ref_repository": "let ref_repository = branch_repository.clone();",
        "gc_blocked_tx": "let gc_blocked_tx = cross05_blocked_tx.clone();",
        "gc_completed_tx": ("let gc_completed_tx = cross05_completed_tx.clone();"),
        "gc_root": "let gc_root = canonical_root.clone();",
        "gc_store": "let gc_store = object_store.clone();",
    }
    for identifier, expected in clone_templates.items():
        if cross05_exact_let_range(body, identifier, expected) is None:
            return f"caller-held {identifier} clone differs"

    closures = cross05_thread_spawn_closures(body)
    if closures is None or len(closures) != 3:
        return "caller-held protocol lacks exactly three move thread closures"
    by_role: dict[str, tuple[int, int, str]] = {}
    for closure in closures:
        roles = tuple(
            role
            for role, title in (("commit", "Commit"), ("ref", "Ref"), ("gc", "Gc"))
            if code_contains_snippet(closure[2], f"Cross05Blocked::{title}")
        )
        if len(roles) != 1 or roles[0] in by_role:
            return "caller-held contender roles are missing or duplicated"
        by_role[roles[0]] = closure
    if tuple(sorted(by_role)) != ("commit", "gc", "ref"):
        return "caller-held contender role set differs"
    for role, closure in by_role.items():
        if problem := cross05_contender_problem(closure[2], role):
            return problem
        expected_handle = (
            f"let {role}_handle = ::std::thread::spawn(move || {{"
            f"{cross05_contender_expected_body(role)}"
            "});"
        )
        handle = cross05_exact_let_range(
            body,
            f"{role}_handle",
            expected_handle,
        )
        if handle is None or not (handle[0] <= closure[0] < closure[1] <= handle[1]):
            return f"{role} contender is not bound to its exact join handle"

    blocked = (
        "let cross05_blocked = ["
        "cross05_blocked_rx.recv().unwrap(),"
        "cross05_blocked_rx.recv().unwrap(),"
        "cross05_blocked_rx.recv().unwrap(),];"
    )
    blocked_range = cross05_exact_let_range(body, "cross05_blocked", blocked)
    if blocked_range is None or blocked_range[0] <= max(
        closure[1] for closure in closures
    ):
        return "caller-held blocked receipts do not follow all contender starts"
    blocked_fields = {
        "commit_blocked": (
            "let commit_blocked = cross05_blocked.iter().any(|event| "
            "::core::matches!(event, Cross05Blocked::Commit(true)));"
        ),
        "ref_blocked": (
            "let ref_blocked = cross05_blocked.iter().any(|event| "
            "::core::matches!(event, Cross05Blocked::Ref(true)));"
        ),
        "gc_blocked": (
            "let gc_blocked = cross05_blocked.iter().any(|event| "
            "::core::matches!(event, Cross05Blocked::Gc(true)));"
        ),
    }
    for field, expected in blocked_fields.items():
        binding = cross05_exact_let_range(body, field, expected)
        if binding is None or binding[0] < blocked_range[1]:
            return f"caller-held {field} is not derived from its typed blocked token"
    if problem := cross05_witness_binding_problem(body):
        return problem

    for field in ("commit_blocked", "ref_blocked", "gc_blocked"):
        assertion = f"::core::assert!({field});"
        starts = exact_direct_statement_starts(body, assertion)
        if len(starts) != 1 or starts[0] < blocked_range[1]:
            return f"caller-held blocked set lacks exact {field} proof"

    release = exact_direct_statement_starts(body, "drop(maintenance);")
    if len(release) != 1:
        return "caller-held guard is not explicitly dropped exactly once"
    completed = (
        "let cross05_completed = ["
        "cross05_completed_rx.recv().unwrap(),"
        "cross05_completed_rx.recv().unwrap(),"
        "cross05_completed_rx.recv().unwrap(),];"
    )
    completed_range = cross05_exact_let_range(body, "cross05_completed", completed)
    if completed_range is None or completed_range[0] <= release[0]:
        return "caller-held completion receipts occur before guard release"

    resumed = {
        "commit_resumed": (
            "let commit_resumed = cross05_completed.iter().any(|event| "
            "::core::matches!(event, Cross05Completed::Commit(true)));"
        ),
        "ref_resumed": (
            "let ref_resumed = cross05_completed.iter().any(|event| "
            "::core::matches!(event, Cross05Completed::Ref(true)));"
        ),
        "gc_resumed": (
            "let gc_resumed = cross05_completed.iter().any(|event| "
            "::core::matches!(event, Cross05Completed::Gc(true)));"
        ),
        "recovery_completed": (
            "let recovery_completed = transaction_recovery_result.is_ok() "
            "&& ref_recovery_result.is_ok() && gc_recovery_result.is_ok();"
        ),
    }
    for identifier, expected in resumed.items():
        binding = cross05_exact_let_range(body, identifier, expected)
        if binding is None or binding[0] < completed_range[1]:
            return f"caller-held {identifier} is not derived after completion"
    for role in ("commit", "ref", "gc"):
        joins = exact_direct_statement_starts(body, f"{role}_handle.join().unwrap();")
        if len(joins) != 1 or joins[0] < completed_range[1]:
            return f"caller-held {role} contender is not joined after completion"
    return None


def cross05_wrapper_problem(body: str, subcase_id: str) -> str | None:
    transaction = subcase_id == "transaction_no_arg_wrapper"
    owner_constructor = (
        "super::TransactionRepository::new"
        if transaction
        else "super::BranchRepository::new"
    )
    wrapper = "recover" if transaction else "recover_refs"
    installer = CROSS_05_WRAPPER_INSTALLERS[subcase_id]
    setup = {
        "owner_repository": (
            f"let owner_repository = {owner_constructor}(canonical_root.clone());"
        ),
        "cross05_owner_tx": (
            "let (cross05_owner_tx, cross05_owner_rx) = "
            "::std::sync::mpsc::sync_channel::<Cross05OwnerSignal>(0);"
        ),
        "cross05_release_tx": (
            "let (cross05_release_tx, cross05_release_rx) = "
            "::std::sync::mpsc::sync_channel::<Cross05OwnerSignal>(0);"
        ),
        "exclusive_observed": (
            "let exclusive_observed = ::core::matches!("
            "cross05_owner_rx.recv().unwrap(), Cross05OwnerSignal::OwnerHeld);"
        ),
    }
    ranges: dict[str, tuple[int, int]] = {}
    for identifier, expected in setup.items():
        found = cross05_exact_let_range(body, identifier, expected)
        if found is None:
            return f"wrapper {identifier} binding differs"
        ranges[identifier] = found

    closures = cross05_thread_spawn_closures(body)
    handles = top_level_let_statement_ranges(body, "owner_handle")
    if closures is None or len(closures) != 1 or len(handles) != 1:
        return "wrapper protocol lacks exactly one bound owner thread"
    closure = closures[0]
    if not (handles[0][0] <= closure[0] < closure[1] <= handles[0][1]):
        return "wrapper owner closure is not bound to owner_handle"
    expected_closure = (
        f"{installer}(owner_repository.root(), cross05_owner_tx, "
        f"cross05_release_rx); owner_repository.{wrapper}()"
    )
    if normalize_rust_tokens(closure[2]) != normalize_rust_tokens(expected_closure):
        return "wrapper owner closure does not install the root-scoped hook then call its no-arg API"
    if ranges["exclusive_observed"][0] <= closure[1]:
        return "wrapper does not wait for OwnerHeld after spawning recovery"

    release_statement = (
        "::core::assert!(cross05_release_tx"
        ".send(Cross05OwnerSignal::ReleaseOwner).is_ok());"
    )
    release = cross05_normalized_statement_starts(body, release_statement)
    if len(release) != 1:
        return "wrapper lacks one exact ReleaseOwner send"
    recovery_result = cross05_exact_let_range(
        body,
        "recovery_result",
        "let recovery_result = owner_handle.join().unwrap();",
    )
    recovery_completed = cross05_exact_let_range(
        body,
        "recovery_completed",
        "let recovery_completed = recovery_result.is_ok();",
    )
    if (
        recovery_result is None
        or recovery_completed is None
        or not release[0] < recovery_result[0] < recovery_completed[0]
    ):
        return "wrapper release, join, and recovery result order differs"

    resumed = {
        "commit_resumed": (
            "let commit_resumed = "
            "::std::fs::File::try_lock_shared(&commit_probe).is_ok();"
        ),
        "ref_resumed": (
            "let ref_resumed = ::std::fs::File::try_lock_shared(&ref_probe).is_ok();"
        ),
        "gc_resumed": (
            "let gc_resumed = ::std::fs::File::try_lock(&gc_probe).is_ok();"
        ),
    }
    previous = recovery_completed[1]
    for role in ("commit", "ref", "gc"):
        field = f"{role}_resumed"
        binding = cross05_exact_let_range(body, field, resumed[field])
        unlock = exact_direct_statement_starts(
            body, f"::std::fs::File::unlock(&{role}_probe).unwrap();"
        )
        if (
            binding is None
            or len(unlock) != 1
            or not previous <= binding[0] < unlock[0]
        ):
            return f"wrapper {role} post-release probe/unlock differs"
        previous = unlock[0]
    return None


def cross05_test_body_problem(
    body: str, subcase_id: str, semantic: dict[str, object]
) -> str | None:
    projected = rust_code_projection(body)
    for token in CROSS_05_TIMING_TOKENS:
        if re.search(rf"\b{re.escape(token)}\b", projected):
            return f"uses timing/polling token {token}"
    fixture_statement = (
        "let Cross05CompositeFixture { fixture, commit_expected_parent, "
        "commit_candidate_bytes, commit_principal_id, branch_name, "
        "branch_target, gc_snapshot, gc_verifier, } = cross05_composite_fixture();"
        if subcase_id == "caller_held_exclusive_sequence"
        else "let fixture = cross05_recovery_fixture();"
    )
    fixture = cross05_exact_let_range(body, "fixture", fixture_statement)
    if fixture is None:
        return "fresh fixture is not the exact closed CROSS-05 fixture binding"
    canonical_root = cross05_exact_let_range(
        body,
        "canonical_root",
        "let canonical_root = ::std::fs::canonicalize(fixture.path()).unwrap();",
    )
    if canonical_root is None or fixture[1] > canonical_root[0]:
        return "canonical root is not the exact fresh-fixture canonicalization"
    expected_spawns = 3 if subcase_id == "caller_held_exclusive_sequence" else 1
    if len(named_call_argument_ranges(body, "spawn")) != expected_spawns:
        return "thread-spawn authority differs from the exact protocol"
    if re.search(r"\b(?:restore|restorer|restoration)\b", projected):
        return "contains restoration authority"
    if subcase_id == "caller_held_exclusive_sequence":
        if problem := cross05_caller_held_problem(body):
            return problem
    else:
        if problem := cross05_common_binding_problem(body):
            return problem
        if problem := cross05_wrapper_problem(body, subcase_id):
            return problem

    for field in CROSS_05_EVIDENCE_FIELDS:
        if len(top_level_let_statement_ranges(body, field)) != 1:
            return f"{field} is not one test-body result binding"
    if problem := cross05_assertion_order_problem(body, semantic):
        return problem

    witness_assertion = exact_direct_statement_starts(
        body, "::core::assert!(gc_witness_absent_while_blocked);"
    )
    release_token = (
        "drop(maintenance);"
        if subcase_id == "caller_held_exclusive_sequence"
        else (
            "::core::assert!(cross05_release_tx"
            ".send(Cross05OwnerSignal::ReleaseOwner).is_ok());"
        )
    )
    release = cross05_normalized_statement_starts(body, release_token)
    first_resumed = min(
        exact_direct_statement_starts(body, f"::core::assert!({field});")[0]
        for field in ("commit_resumed", "ref_resumed", "gc_resumed")
    )
    if (
        len(witness_assertion) != 1
        or len(release) != 1
        or not witness_assertion[0] < release[0] < first_resumed
    ):
        return "owner release is not between blocked witness and resumed proof"
    statements = cross05_top_level_statement_ranges(body, 0)
    expected_statements = 50 if subcase_id == "caller_held_exclusive_sequence" else 32
    if statements is None or len(statements) != expected_statements:
        return "protocol suffix contains an extra, missing, or unterminated statement"
    return None


def cross05_exact_cfg_struct_body(source: str, name: str) -> str | None:
    projected = rust_code_projection(source)
    matches = tuple(
        re.finditer(
            rf"#\s*\[\s*cfg\s*\(\s*test\s*\)\s*\]\s*"
            rf"struct\s+{re.escape(name)}\s*\{{",
            projected,
        )
    )
    definitions = tuple(re.finditer(rf"\bstruct\s+{re.escape(name)}\b", projected))
    if len(matches) != 1 or len(definitions) != 1:
        return None
    opening = projected.find("{", matches[0].start(), matches[0].end())
    closing = matching_delimiter(projected, [True] * len(projected), opening, "{", "}")
    if closing is None:
        return None
    return source[opening + 1 : closing]


def cross05_exact_test_struct_body(source: str, name: str) -> str | None:
    mask = rust_code_mask(source)
    module_range = exact_test_module_range(source, mask)
    if module_range is None:
        return None
    module_opening, module_closing = module_range
    module = source[module_opening + 1 : module_closing]
    projected = rust_code_projection(module)
    module_mask = rust_code_mask(module)
    matches = rust_item_matches(
        projected,
        rf"struct\s+{re.escape(name)}\s*\{{",
    )
    definitions = tuple(
        re.finditer(
            rf"\bstruct\s+{re.escape(name)}\b",
            rust_code_projection(source),
        )
    )
    if len(matches) != 1 or len(definitions) != 1:
        return None
    match = matches[0]
    if (
        brace_depth_at(module, module_mask, match.start()) != 0
        or has_preceding_code_attribute(module, module_mask, match.start())
    ):
        return None
    opening = projected.find("{", match.start(), match.end())
    closing = matching_delimiter(projected, [True] * len(projected), opening, "{", "}")
    if closing is None:
        return None
    return module[opening + 1 : closing]


def cross05_production_body_key(relative: str, owner: str, name: str) -> str:
    return f"{relative}:{owner}:{name}"


def cross05_production_body_sha256(body: str) -> str:
    normalized = normalize_rust_tokens(body)
    return hashlib.sha256(normalized.encode("utf-8")).hexdigest()


def gc_recovery_source_authority_problem(source: str) -> str | None:
    gate = cross05_exact_cfg_struct_body(source, "GcMaintenanceRaceGate")
    expected_gate = """
owner_tx: SyncSender<()>,
release_rx: Mutex<Receiver<()>>,
"""
    if gate is None or normalize_rust_tokens(gate) != normalize_rust_tokens(
        expected_gate
    ):
        return "GcMaintenanceRaceGate exact fields differ"
    exact_sync_import = """
#[cfg(test)]
use std::sync::{
    Arc, Mutex,
    mpsc::{Receiver, SyncSender},
};
"""
    if (
        normalize_rust_tokens(source).count(normalize_rust_tokens(exact_sync_import))
        != 1
    ):
        return "GC test synchronization import authority differs"
    if code_contains_token(normal_build_rust(source), "GcMaintenanceRaceGate"):
        return "GcMaintenanceRaceGate survives normal build"

    for owner, name, normal_only, expected in GC_RECOVERY_BODY_AUTHORITIES:
        authority_source = normal_build_source(source) if normal_only else source
        body = rust_named_function_raw_body(authority_source, name, owner)
        if body is None:
            return f"cannot isolate exact GC recovery body {owner}:{name}"
        if cross05_production_body_sha256(body) != expected:
            return f"exact GC recovery body digest differs: {owner}:{name}"

    for _row_id, _subcase_id, name, expected in GC_RECOVERY_TEST_AUTHORITIES:
        definition = exact_test_definition(source, name)
        if definition is None:
            return f"cannot isolate exact GC recovery test {name}"
        if cross05_production_body_sha256(definition[0]) != expected:
            return f"exact GC recovery test body digest differs: {name}"

    module_range = exact_test_module_range(source, rust_code_mask(source))
    if module_range is None:
        return "GC recovery source lacks one exact test module"
    module = source[module_range[0] + 1 : module_range[1]]
    reserved = {
        "std",
        "core",
        "sley_txn",
        "fs",
        "File",
        "OpenOptions",
        "Path",
        "PathBuf",
        "Arc",
        "Mutex",
        "ObjectStore",
        "RepositoryMaintenanceGuard",
        "GcDurabilityCut",
        "GcMaintenanceRaceGate",
        "GcWitnessRecoveryStatus",
        "GC_LOCK_BYTES",
        "GC_LOCK_DIR",
        "GC_LOCK_FILE",
        "acquire_exclusive_gc_with_gc_durability_cut",
        "recover_gc_witness_with_gc_durability_cut",
        "gc_collect_with_injected_pre_cleanup_sync_failure",
        "gc_collect_with_gc_durability_cut",
        "recover_gc_witness",
        "acquire_exclusive_repository_maintenance",
        "initialize_repository_maintenance",
        "sync_inventory_leaf_directories",
        "sync_dir",
        "initialize_exact_gc_witness",
        "exact_error_source_chain",
        "exact_path_snapshot",
        "exact_tree_snapshot",
    }
    for statement in rust_use_statements(module):
        bound = rust_use_tree_bound_names(statement)
        if not bound:
            return "cannot parse GC test-module import"
        if "*" in bound:
            if normalize_rust_tokens(statement) != normalize_rust_tokens(
                "use super::*;"
            ):
                return "GC test module has foreign glob authority"
            continue
        shadowed = sorted(reserved.intersection(bound))
        if shadowed:
            return f"GC test module shadows {shadowed[0]} authority"
    projection = rust_code_projection(module)
    type_names = reserved - {
        "GC_LOCK_BYTES",
        "GC_LOCK_DIR",
        "GC_LOCK_FILE",
        "acquire_exclusive_gc_with_gc_durability_cut",
        "recover_gc_witness_with_gc_durability_cut",
        "gc_collect_with_injected_pre_cleanup_sync_failure",
        "gc_collect_with_gc_durability_cut",
        "recover_gc_witness",
        "acquire_exclusive_repository_maintenance",
        "initialize_repository_maintenance",
        "sync_inventory_leaf_directories",
        "sync_dir",
        "initialize_exact_gc_witness",
        "exact_error_source_chain",
        "exact_path_snapshot",
        "exact_tree_snapshot",
    }
    for name in sorted(type_names):
        if re.search(
            rf"\b(?:mod|struct|enum|union|type|trait)\s+"
            rf"(?:r#)?{re.escape(name)}\b",
            projection,
        ):
            return f"GC test module defines shadow authority {name}"
    forbidden_values = (
        reserved
        - type_names
        - {
            "initialize_exact_gc_witness",
            "exact_error_source_chain",
            "exact_path_snapshot",
            "exact_tree_snapshot",
        }
    )
    for name in sorted(forbidden_values):
        if re.search(
            rf"\b(?:const|static|fn)\s+(?:r#)?{re.escape(name)}\b",
            projection,
        ):
            return f"GC test module defines shadow authority {name}"
    return None


def gc_recovery_row_mapping_problem(row_map: dict[str, object]) -> str | None:
    for row_id, subcase_id, expected_test, _digest in GC_RECOVERY_TEST_AUTHORITIES:
        entry = row_map.get(row_id)
        if not isinstance(entry, dict):
            return f"{row_id} lacks exact GC recovery mapping"
        if subcase_id is not None:
            subcases = entry.get("subcases")
            if not isinstance(subcases, dict):
                return f"{row_id} lacks exact GC recovery subcases"
            entry = subcases.get(subcase_id)
            if not isinstance(entry, dict):
                return f"{row_id}/{subcase_id} lacks exact GC recovery mapping"
        if entry.get("tests") != [expected_test]:
            label = row_id if subcase_id is None else f"{row_id}/{subcase_id}"
            return f"{label} exact GC recovery test mapping differs"
    return None


def cross05_body_digest_problem(body: str, key: str, expected: str) -> str | None:
    if cross05_production_body_sha256(body) != expected:
        return f"production body digest differs: {key}"
    return None


def cross05_named_body_digest_problem(
    source: str,
    relative: str,
    owner: str,
    name: str,
    expected: str,
) -> str | None:
    body = rust_named_function_raw_body(source, name, owner)
    if body is None:
        return f"cannot isolate production body {relative}:{owner}:{name}"
    key = cross05_production_body_key(relative, owner, name)
    return cross05_body_digest_problem(body, key, expected)


def cross05_exact_named_function_problem(
    source: str,
    relative: str,
    owner: str,
    name: str,
    expected_signature: str,
    expected_digest: str,
) -> str | None:
    authority_source = source
    authority_owner = owner
    if owner == "mod:tests" or owner.startswith("mod:tests/"):
        module_range = exact_test_module_range(source, rust_code_mask(source))
        if module_range is None:
            return f"cannot isolate exact test module in {relative}"
        authority_source = source[module_range[0] + 1 : module_range[1]]
        authority_owner = (
            "<crate>" if owner == "mod:tests" else owner.removeprefix("mod:tests/")
        )
    projected = rust_code_projection(authority_source)
    mask = rust_code_mask(authority_source)
    owner_ranges = rust_owner_ranges(authority_source, projected)
    matches = tuple(
        match
        for match in re.finditer(rf"\bfn\s+(?:r#)?{re.escape(name)}\b", projected)
        if rust_owner_chain(owner_ranges, match.start()) == authority_owner
    )
    if len(matches) != 1:
        return f"cannot isolate exact test function {relative}:{owner}:{name}"
    match = matches[0]
    if has_preceding_code_attribute(authority_source, mask, match.start()):
        return f"test function has extra authority attribute: {relative}:{owner}:{name}"
    opening = public_function_signature_end(projected, match.start())
    if opening is None or projected[opening] != "{":
        return f"test function signature is unbalanced: {relative}:{owner}:{name}"
    signature = authority_source[match.start() : opening]
    if normalize_rust_tokens(signature) != normalize_rust_tokens(expected_signature):
        return f"test function signature differs: {relative}:{owner}:{name}"
    closing = matching_delimiter(projected, [True] * len(projected), opening, "{", "}")
    if closing is None:
        return f"test function body is unbalanced: {relative}:{owner}:{name}"
    body = authority_source[opening + 1 : closing]
    key = cross05_production_body_key(relative, owner, name)
    if cross05_production_body_sha256(body) != expected_digest:
        return f"test function body digest differs: {key}"
    return None


def rust_use_statements(source: str) -> tuple[str, ...]:
    projected = rust_code_projection(source)
    statements: list[str] = []
    for match in re.finditer(r"\buse\b", projected):
        end = projected.find(";", match.end())
        if end < 0:
            return ()
        statements.append(source[match.start() : end + 1])
    return tuple(statements)


def split_top_level_rust_commas(value: str) -> tuple[str, ...]:
    parts: list[str] = []
    start = 0
    depths = {"(": 0, "[": 0, "{": 0, "<": 0}
    closers = {")": "(", "]": "[", "}": "{", ">": "<"}
    for index, character in enumerate(value):
        if character in depths:
            depths[character] += 1
        elif character in closers and depths[closers[character]]:
            depths[closers[character]] -= 1
        elif character == "," and not any(depths.values()):
            parts.append(value[start:index])
            start = index + 1
    parts.append(value[start:])
    return tuple(part for part in parts if part.strip())


def rust_use_tree_bound_names(
    value: str, prefix: tuple[str, ...] = ()
) -> tuple[str, ...]:
    tree = value.strip().removeprefix("use").removesuffix(";").strip()
    alias = re.search(rf"\bas\s+(?P<name>{RUST_IDENTIFIER})\s*$", tree)
    if alias is not None:
        return (semantic_rust_identifier(alias.group("name")),)

    opening = -1
    depth = 0
    for index, character in enumerate(tree):
        if character == "{" and depth == 0:
            opening = index
            break
        if character in "([<":
            depth += 1
        elif character in ")]>":
            depth -= 1
    if opening >= 0:
        closing = matching_delimiter(tree, [True] * len(tree), opening, "{", "}")
        if closing is None or tree[closing + 1 :].strip():
            return ()
        base = tuple(
            semantic_rust_identifier(identifier)
            for identifier in re.findall(RUST_IDENTIFIER, tree[:opening])
        )
        qualified = prefix + base
        names: list[str] = []
        for member in split_top_level_rust_commas(tree[opening + 1 : closing]):
            if member.strip() == "self":
                if not qualified:
                    return ()
                names.append(qualified[-1])
            elif member.strip() == "*":
                names.append("*")
            else:
                names.extend(rust_use_tree_bound_names(member, qualified))
        return tuple(names)

    identifiers = tuple(
        semantic_rust_identifier(identifier)
        for identifier in re.findall(RUST_IDENTIFIER, tree)
    )
    if re.search(r"(?:^|::)\s*\*\s*$", tree):
        return ("*",)
    if not identifiers:
        return ()
    if identifiers[-1] == "self":
        qualified = prefix + identifiers[:-1]
        return (qualified[-1],) if qualified else ()
    return (identifiers[-1],)


def cross05_authority_binding_problem(sources: dict[str, str]) -> str | None:
    expected_relatives = tuple(CROSS_05_AUTHORITY_IMPORTS)
    if tuple(CROSS_05_AUTHORITY_IMPORT_NAME_COUNTS) != expected_relatives:
        return "authority import count source set or order differs"

    standard_names = {"std", "fs", "File", "OpenOptions", "io", "Path", "PathBuf"}
    for relative in expected_relatives:
        source = sources.get(relative)
        if source is None:
            return f"authority import source is absent: {relative}"
        normal = normal_build_source(source)
        statements = rust_use_statements(normal)
        if not statements and CROSS_05_AUTHORITY_IMPORTS[relative]:
            return f"cannot isolate authority imports in {relative}"
        normalized_statements = tuple(
            normalize_rust_tokens(item) for item in statements
        )
        expected_imports = tuple(
            normalize_rust_tokens(item) for item in CROSS_05_AUTHORITY_IMPORTS[relative]
        )
        for expected in expected_imports:
            if normalized_statements.count(expected) != 1:
                return f"exact authority import differs in {relative}"

        counts = {name: 0 for name in CROSS_05_AUTHORITY_IMPORT_NAME_COUNTS[relative]}
        for statement in statements:
            bound = rust_use_tree_bound_names(statement)
            if not bound:
                return f"cannot parse authority import in {relative}"
            if "*" in bound:
                return f"normal-build glob import is forbidden in {relative}"
            for name in bound:
                if name in counts:
                    counts[name] += 1
        if counts != CROSS_05_AUTHORITY_IMPORT_NAME_COUNTS[relative]:
            return f"authority import binding counts differ in {relative}"

        projection = rust_code_projection(normal)
        forbidden_type_definitions = standard_names | {
            name for name, count in counts.items() if count > 0
        }
        for name in sorted(forbidden_type_definitions):
            if re.search(
                rf"\b(?:mod|struct|enum|union|type|trait)\s+"
                rf"(?:r#)?{re.escape(name)}\b",
                projection,
            ):
                return f"normal-build authority shadow {name} in {relative}"
        for name, count in counts.items():
            if count == 0 or not (
                name.startswith("acquire_") or name.startswith("initialize_")
            ):
                continue
            if re.search(
                rf"\b(?:const|static|fn)\s+(?:r#)?{re.escape(name)}\b",
                projection,
            ):
                return f"normal-build authority shadow {name} in {relative}"
        if re.search(r"\bextern\s+crate\b", projection):
            return f"normal-build extern-crate authority differs in {relative}"
        if re.search(r"\bmacro_rules\s*!", projection):
            return f"normal-build macro authority differs in {relative}"
    return None


def cross05_root_authority_problem(sources: dict[str, str]) -> str | None:
    if tuple(CROSS_05_IMMUTABLE_LOCK_SOURCE_SHA256) != (
        "crates/sley-txn/src/maintenance.rs",
    ):
        return "immutable lock-authority source set or order differs"
    for relative in PUBLIC_API_SOURCE_PATHS:
        source = sources.get(relative)
        if source is None:
            return f"root authority source is absent: {relative}"
        normal = normal_build_source(source)
        for statement in rust_use_statements(normal):
            bound = rust_use_tree_bound_names(statement)
            if not bound:
                return f"cannot parse root authority import in {relative}"
            shadowed = sorted(CROSS_05_ROOT_AUTHORITY_NAMES.intersection(bound))
            if shadowed:
                return f"normal-build root authority shadow {shadowed[0]} in {relative}"
        projection = rust_code_projection(normal)
        for name in sorted(CROSS_05_ROOT_AUTHORITY_NAMES):
            if re.search(
                rf"\b(?:mod|struct|enum|union|type|trait)\s+"
                rf"(?:r#)?{re.escape(name)}\b",
                projection,
            ):
                return f"normal-build root authority shadow {name} in {relative}"
            if re.search(
                rf"\bextern\s+crate\b[^;]*\bas\s+(?:r#)?{re.escape(name)}\b",
                projection,
            ):
                return f"normal-build root extern alias {name} in {relative}"
        if problem := cross05_deferred_authority_problem(source):
            return f"normal-build deferred authority in {relative}: {problem}"
        if relative != "crates/sley-txn/src/maintenance.rs" and (
            code_contains_token(normal, "MAINTENANCE_LOCK_FILE")
            or any(
                "maintenance.lock" in value
                for value in rust_string_literal_values(normal)
            )
        ):
            return f"maintenance-lock path authority escaped into {relative}"

    for relative, expected in CROSS_05_IMMUTABLE_LOCK_SOURCE_SHA256.items():
        normalized = normalize_rust_tokens(normal_build_source(sources[relative]))
        digest = hashlib.sha256(normalized.encode("utf-8")).hexdigest()
        if digest != expected:
            return f"immutable lock-authority source digest differs in {relative}"
    return None


def cross05_fixture_authority_problem(store: str, txn: str, refs: str) -> str | None:
    sources = {
        "crates/sley-store/src/lib.rs": store,
        "crates/sley-txn/src/repository.rs": txn,
        "crates/sley-repo/src/refs.rs": refs,
    }
    expected_keys = tuple(
        cross05_production_body_key(relative, owner, name)
        for relative, owner, name, _signature in CROSS_05_TEST_FUNCTION_AUTHORITIES
    )
    if tuple(CROSS_05_TEST_FUNCTION_BODY_SHA256) != expected_keys:
        return "test fixture body authority key set or order differs"
    for relative, owner, name, signature in CROSS_05_TEST_FUNCTION_AUTHORITIES:
        key = cross05_production_body_key(relative, owner, name)
        if problem := cross05_exact_named_function_problem(
            sources[relative],
            relative,
            owner,
            name,
            signature,
            CROSS_05_TEST_FUNCTION_BODY_SHA256[key],
        ):
            return problem

    for relative, source in sources.items():
        temp_fields = cross05_exact_test_struct_body(source, "TempDir")
        if temp_fields is None or normalize_rust_tokens(
            temp_fields
        ) != normalize_rust_tokens("path: ::std::path::PathBuf,"):
            return f"{relative} TempDir exact owned path field differs"

        module_range = exact_test_module_range(source, rust_code_mask(source))
        if module_range is None:
            return f"{relative} exact tests module is absent"
        tests = source[module_range[0] + 1 : module_range[1]]
        projected_tests = rust_code_projection(tests)
        reserved = {
            "std",
            "fs",
            "Path",
            "PathBuf",
            "AtomicU64",
            "Ordering",
            "ObjectStore",
            "TransactionRepository",
            "BranchRepository",
            "RepositoryMaintenanceGuard",
        }
        for name in sorted(reserved):
            if re.search(
                rf"\b(?:mod|struct|enum|union|type|trait|const|static)\s+"
                rf"(?:r#)?{re.escape(name)}\b",
                projected_tests,
            ):
                return f"{relative} test fixture shadows {name} authority"

    store_temp_fields = cross05_exact_test_struct_body(store, "TempDir")
    if store_temp_fields is None or normalize_rust_tokens(
        store_temp_fields
    ) != normalize_rust_tokens("path: ::std::path::PathBuf,"):
        return "store TempDir exact owned path field differs"

    txn_fixture_fields = cross05_exact_test_struct_body(txn, "Fixture")
    expected_txn_fixture_fields = """
temp: TempDir,
repository: super::TransactionRepository,
principal_id: PrincipalId,
genesis_transaction_id: TransactionId,
candidate: ImportedCandidate,
"""
    if txn_fixture_fields is None or normalize_rust_tokens(
        txn_fixture_fields
    ) != normalize_rust_tokens(expected_txn_fixture_fields):
        return "transaction Fixture exact owned fields differ"

    ref_fixture_fields = cross05_exact_test_struct_body(refs, "Fixture")
    expected_ref_fixture_fields = """
temp: TempDir,
transactions: ::sley_txn::TransactionRepository,
branches: super::BranchRepository,
principal_id: PrincipalId,
genesis_transaction_id: TransactionId,
"""
    if ref_fixture_fields is None or normalize_rust_tokens(
        ref_fixture_fields
    ) != normalize_rust_tokens(expected_ref_fixture_fields):
        return "ref Fixture exact owned fields differ"

    composite_fields = cross05_exact_test_struct_body(refs, "Cross05CompositeFixture")
    expected_composite_fields = """
fixture: Fixture,
commit_expected_parent: TransactionId,
commit_candidate_bytes: Vec<u8>,
commit_principal_id: PrincipalId,
branch_name: Vec<u8>,
branch_target: TransactionId,
gc_snapshot: RetentionSnapshot,
gc_verifier: Cross05GcVerifier,
"""
    if composite_fields is None or normalize_rust_tokens(
        composite_fields
    ) != normalize_rust_tokens(expected_composite_fields):
        return "Cross05CompositeFixture exact owned fields differ"

    verifier_fields = cross05_exact_test_struct_body(refs, "Cross05GcVerifier")
    if verifier_fields is None or normalize_rust_tokens(
        verifier_fields
    ) != normalize_rust_tokens("schema_epoch_id: SchemaEpochId,"):
        return "Cross05GcVerifier exact schema field differs"

    for source, names in (
        (
            txn,
            (
                "cross05_recovery_fixture",
                "Cross05CompositeFixture",
                "Cross05GcVerifier",
            ),
        ),
        (
            refs,
            (
                "cross05_recovery_fixture",
                "cross05_composite_fixture",
                "Cross05CompositeFixture",
                "Cross05GcVerifier",
            ),
        ),
    ):
        normal = normal_build_rust(source)
        for name in names:
            if code_contains_token(normal, name):
                return f"test fixture authority survives normal build: {name}"
    return None


def cross05_production_body_problem(
    sources: dict[str, str], expected: dict[str, str]
) -> str | None:
    expected_keys = tuple(
        cross05_production_body_key(relative, owner, name)
        for relative, owner, name in CROSS_05_PRODUCTION_BODY_AUTHORITIES
    )
    if tuple(expected) != expected_keys:
        return "production body authority key set or order differs"
    normal_sources = {
        relative: normal_build_source(source) for relative, source in sources.items()
    }
    for relative, owner, name in CROSS_05_PRODUCTION_BODY_AUTHORITIES:
        source = sources.get(relative)
        if source is None:
            return f"production body source is absent: {relative}"
        key = cross05_production_body_key(relative, owner, name)
        if problem := cross05_named_body_digest_problem(
            normal_sources[relative], relative, owner, name, expected[key]
        ):
            return problem
    return None


def cross05_evolving_guarded_core_problem(sources: dict[str, str]) -> str | None:
    for (
        relative,
        type_name,
        wrapper_name,
        wrapper_delegate,
        core_name,
        validator,
    ) in CROSS_05_EVOLVING_GUARDED_CORES:
        normal = normal_build_source(sources[relative])
        impls = rust_impl_bodies(normal, type_name)
        if len(impls) != 1:
            return f"{type_name} exact implementation owner differs"
        owner = f"impl{type_name}"
        core_signatures = rust_direct_function_signature(impls[0], core_name, "private")
        if not core_signatures:
            name = wrapper_name
            signatures = rust_direct_function_signature(impls[0], name, "public")
        else:
            if len(core_signatures) != 1:
                return f"{type_name}::{core_name} exact implementation count differs"
            wrapper_body = rust_named_function_raw_body(normal, wrapper_name, owner)
            if wrapper_body is None or normalize_rust_tokens(
                wrapper_body
            ) != normalize_rust_tokens(wrapper_delegate):
                return f"{type_name}::{wrapper_name} exact guarded delegate differs"
            name = core_name
            signatures = core_signatures
        if len(signatures) != 1 or (
            "maintenance:&RepositoryMaintenanceGuard"
            not in normalize_rust_tokens(signatures[0])
        ):
            return f"{type_name}::{name} exact borrowed-guard signature differs"
        body = rust_named_function_raw_body(normal, name, owner)
        if body is None:
            return f"cannot isolate evolving guarded core {type_name}::{name}"
        validation = f"self.{validator}(maintenance)?;"
        starts = exact_direct_statement_starts(body, validation)
        if len(starts) != 1 or rust_code_projection(body[: starts[0]]).strip():
            return f"{type_name}::{name} guard validation is not first"
        projection = rust_code_projection(body)
        for forbidden in (
            "acquire_shared_maintenance",
            "acquire_exclusive_maintenance",
            "acquire_shared_repository_maintenance",
            "acquire_exclusive_repository_maintenance",
            "initialize_repository_maintenance",
        ):
            if code_contains_token(projection, forbidden):
                return f"{type_name}::{name} reacquires maintenance via {forbidden}"
        if re.search(
            r"\b(?:drop|forget|unlock)\s*\(\s*maintenance\b|"
            r"\bmaintenance\s*=",
            projection,
        ):
            return f"{type_name}::{name} releases or replaces its guard"
    return None


def cross05_deferred_authority_problem(source: str) -> str | None:
    projected = rust_code_projection(normal_build_source(source))
    forbidden = (
        (r"\basync\b", "async"),
        (r"\bspawn(?:_blocking)?\b", "spawn"),
        (r"\bthread\b", "thread"),
        (r"\b(?:tokio|rayon)\b", "task runtime"),
        (r"\bCommand\b", "process command"),
        (r"\bStdio\b", "process stdio"),
        (r"\b(?:extern|unsafe)\b", "foreign or unsafe execution"),
        (r"\b(?:forget|ManuallyDrop)\b", "guard lifetime escape"),
        (r"\b(?:set_hook|take_hook)\b", "panic hook registry"),
        (
            r"\b(?:OnceLock|LazyLock|OnceCell|set_global_default|"
            r"set_boxed_logger|set_logger)\b",
            "global callback registry",
        ),
    )
    for pattern, label in forbidden:
        if re.search(pattern, projected):
            return label
    return None


def cross05_guard_struct_problem(
    store: str, maintenance: str, txn: str, refs: str, gc: str
) -> str | None:
    store_fields = rust_item_body(normal_build_source(store), "struct", "ObjectStore")
    if normalize_rust_tokens(store_fields) != normalize_rust_tokens("root: PathBuf,"):
        return "ObjectStore exact root field differs"
    store_impls = rust_impl_bodies(normal_build_source(store), "ObjectStore")
    store_new = (
        rust_named_function_raw_body(store_impls[0], "new", "<crate>")
        if len(store_impls) == 1
        else None
    )
    if store_new is None or normalize_rust_tokens(store_new) != normalize_rust_tokens(
        "Self { root: root.into() }"
    ):
        return "ObjectStore exact same-root constructor differs"
    store_root = rust_named_function_raw_body(store_impls[0], "root", "<crate>")
    if store_root is None or normalize_rust_tokens(store_root) != normalize_rust_tokens(
        "&self.root"
    ):
        return "ObjectStore exact root accessor differs"

    maintenance_fields = rust_item_body(
        normal_build_source(maintenance),
        "struct",
        "RepositoryMaintenanceGuard",
    )
    expected_maintenance = """
repository_root: PathBuf,
exclusive: bool,
_file: ::std::fs::File,
"""
    if normalize_rust_tokens(maintenance_fields) != normalize_rust_tokens(
        expected_maintenance
    ):
        return "RepositoryMaintenanceGuard exact root/mode/file fields differ"
    txn_fields = rust_item_body(
        normal_build_source(txn), "struct", "TransactionRepository"
    )
    expected_txn = """
root: PathBuf,
object_store: ObjectStore,
"""
    if normalize_rust_tokens(txn_fields) != normalize_rust_tokens(expected_txn):
        return "TransactionRepository exact root/store fields differ"
    txn_root = rust_named_function_raw_body(
        normal_build_source(txn), "root", "implTransactionRepository"
    )
    if txn_root is None or normalize_rust_tokens(txn_root) != normalize_rust_tokens(
        "&self.root"
    ):
        return "TransactionRepository exact root accessor differs"
    ref_fields = rust_item_body(normal_build_source(refs), "struct", "BranchRepository")
    expected_refs = """
root: PathBuf,
transactions: TransactionRepository,
"""
    if normalize_rust_tokens(ref_fields) != normalize_rust_tokens(expected_refs):
        return "BranchRepository exact root/transaction fields differ"
    ref_root = rust_named_function_raw_body(
        normal_build_source(refs), "root", "implBranchRepository"
    )
    if ref_root is None or normalize_rust_tokens(ref_root) != normalize_rust_tokens(
        "&self.root"
    ):
        return "BranchRepository exact root accessor differs"
    gc_fields = rust_item_body(normal_build_source(gc), "struct", "ExclusiveGcGuard")
    expected_gc = """
store_root: PathBuf,
lock_path: PathBuf,
maintenance: RepositoryMaintenanceGuard,
active: bool,
"""
    if normalize_rust_tokens(gc_fields) != normalize_rust_tokens(expected_gc):
        return "ExclusiveGcGuard exact root/witness/maintenance/state fields differ"
    return None


def cross05_hook_authority_problem(
    source: str, installer: str, hook: str
) -> str | None:
    signal = exact_cfg_test_item(source, "enum", "Cross05OwnerSignal", "<crate>")
    if signal is None or normalize_rust_tokens(signal[1]) != normalize_rust_tokens(
        "OwnerHeld, ReleaseOwner,"
    ):
        return "Cross05OwnerSignal exact test enum differs"
    hold_fields = cross05_exact_cfg_struct_body(source, "Cross05RecoveryHold")
    expected_fields = """
root: PathBuf,
owner_tx: ::std::sync::mpsc::SyncSender<Cross05OwnerSignal>,
release_rx: ::std::sync::mpsc::Receiver<Cross05OwnerSignal>,
"""
    if hold_fields is None or normalize_rust_tokens(
        hold_fields
    ) != normalize_rust_tokens(expected_fields):
        return "Cross05RecoveryHold exact fields differ"

    projected = rust_code_projection(source)
    thread_locals = tuple(
        re.finditer(
            r"#\s*\[\s*cfg\s*\(\s*test\s*\)\s*\]\s*"
            r"::\s*std\s*::\s*thread_local\s*!\s*\{",
            projected,
        )
    )
    if len(thread_locals) != 1:
        return "CROSS05_RECOVERY_HOLD thread-local authority differs"
    opening = projected.find("{", thread_locals[0].start(), thread_locals[0].end())
    closing = matching_delimiter(projected, [True] * len(projected), opening, "{", "}")
    if closing is None:
        return "CROSS05_RECOVERY_HOLD thread-local item is unbalanced"
    expected_thread_local = """
#[cfg(test)]
::std::thread_local! {
    static CROSS05_RECOVERY_HOLD:
        ::std::cell::RefCell<Option<Cross05RecoveryHold>> =
        const { ::std::cell::RefCell::new(None) };
}
"""
    actual_thread_local = source[thread_locals[0].start() : closing + 1]
    if normalize_rust_tokens(actual_thread_local) != normalize_rust_tokens(
        expected_thread_local
    ):
        return "CROSS05_RECOVERY_HOLD thread-local body differs"

    installer_item = exact_cfg_test_item(source, "fn", installer, "<crate>")
    expected_installer_signature = f"""
fn {installer}(
    root: &Path,
    owner_tx: ::std::sync::mpsc::SyncSender<Cross05OwnerSignal>,
    release_rx: ::std::sync::mpsc::Receiver<Cross05OwnerSignal>,
)
"""
    expected_installer_body = """
CROSS05_RECOVERY_HOLD.with(|slot| {
    let mut slot = slot.borrow_mut();
    ::core::assert!(slot.is_none());
    *slot = Some(Cross05RecoveryHold {
        root: root.to_path_buf(),
        owner_tx,
        release_rx,
    });
});
"""
    if installer_item is None or normalize_rust_tokens(
        installer_item[0]
    ) != normalize_rust_tokens(expected_installer_signature):
        return f"{installer} exact test-only signature differs"
    if normalize_rust_tokens(installer_item[1]) != normalize_rust_tokens(
        expected_installer_body
    ):
        return f"{installer} exact root-scoped body differs"

    hook_item = exact_cfg_test_item(source, "fn", hook, "<crate>")
    hook_trailing_comma = (
        "," if hook == "hold_transaction_recovery_before_exclusive_drop" else ""
    )
    expected_hook_signature = f"""
fn {hook}(
    root: &Path,
    maintenance: &RepositoryMaintenanceGuard{hook_trailing_comma}
)
"""
    expected_hook_body = """
CROSS05_RECOVERY_HOLD.with(|slot| {
    let Some(hold) = slot.borrow_mut().take() else {
        return;
    };
    ::core::assert_eq!(hold.root, root);
    ::core::assert!(maintenance.is_exclusive());
    ::core::assert!(maintenance.covers(root));
    ::core::assert!(hold
        .owner_tx
        .send(Cross05OwnerSignal::OwnerHeld)
        .is_ok());
    let release = hold.release_rx.recv().unwrap();
    ::core::assert!(::core::matches!(
        release,
        Cross05OwnerSignal::ReleaseOwner
    ));
});
"""
    if hook_item is None or normalize_rust_tokens(
        hook_item[0]
    ) != normalize_rust_tokens(expected_hook_signature):
        return f"{hook} exact test-only signature differs"
    if normalize_rust_tokens(hook_item[1]) != normalize_rust_tokens(expected_hook_body):
        return f"{hook} exact guard/root rendezvous body differs"

    normal = normal_build_rust(source)
    for name in (
        "Cross05OwnerSignal",
        "Cross05RecoveryHold",
        "CROSS05_RECOVERY_HOLD",
        installer,
        hook,
    ):
        if code_contains_token(normal, name):
            return f"test-only CROSS-05 authority survives normal build: {name}"
    return None


def cross05_support_enum_problem(source: str, name: str) -> str | None:
    item = exact_cfg_test_item(source, "enum", name, "<crate>")
    expected = "Commit(bool), Ref(bool), Gc(bool),"
    if item is None or normalize_rust_tokens(item[1]) != normalize_rust_tokens(
        expected
    ):
        return f"{name} exact test-only enum differs"
    if code_contains_token(normal_build_rust(source), name):
        return f"{name} survives normal build"
    return None


def cross05_recovery_wrapper_problem(
    source: str,
    owner: str,
    wrapper: str,
    guarded: str,
    hook: str,
) -> str | None:
    body = rust_named_function_raw_body(source, wrapper, owner)
    if body is None:
        return f"cannot isolate {wrapper} wrapper"
    expected = f"""
let maintenance = self.acquire_exclusive_maintenance()?;
let result = self.{guarded}(&maintenance);
#[cfg(test)]
{hook}(&self.root, &maintenance);
result
"""
    if normalize_rust_tokens(body) != normalize_rust_tokens(expected):
        return f"{wrapper} acquire/guarded-core/hook/result body differs"
    normal_body = rust_named_function_raw_body(
        normal_build_source(source), wrapper, owner
    )
    expected_normal = f"""
let maintenance = self.acquire_exclusive_maintenance()?;
let result = self.{guarded}(&maintenance);
result
"""
    if normal_body is None or normalize_rust_tokens(
        normal_body
    ) != normalize_rust_tokens(expected_normal):
        return f"{wrapper} normal-build body differs"
    return None


def cross05_shared_wrapper_problem(
    source: str, owner: str, wrapper: str, expected: str, core: str
) -> str | None:
    body = rust_named_function_raw_body(normal_build_source(source), wrapper, owner)
    if body is None or normalize_rust_tokens(body) != normalize_rust_tokens(expected):
        return f"{wrapper} shared-maintenance delegation differs"
    core_body = rust_named_function_raw_body(normal_build_source(source), core, owner)
    if core_body is None:
        return f"{wrapper} guarded core {core} is absent"
    signatures = tuple(
        signature
        for impl_body in rust_impl_bodies(
            normal_build_source(source), owner.removeprefix("impl")
        )
        for signature in rust_direct_function_signature(impl_body, core, "private")
    )
    if len(
        signatures
    ) != 1 or "maintenance:&RepositoryMaintenanceGuard" not in normalize_rust_tokens(
        signatures[0]
    ):
        return f"{core} does not borrow the exact maintenance guard"
    return None


def cross05_gc_acquisition_problem(source: str) -> str | None:
    normal = normal_build_source(source)
    body = rust_named_function_raw_body(normal, "acquire_exclusive_gc", "<crate>")
    if body is None:
        return "cannot isolate acquire_exclusive_gc"
    maintenance = top_level_let_statement_ranges(body, "maintenance")
    if len(maintenance) != 1:
        return "GC acquisition does not bind one maintenance guard"
    maintenance_statement = normalize_rust_tokens(maintenance[0][2])
    if (
        "acquire_exclusive_repository_maintenance(&store_root)"
        not in maintenance_statement
        or not maintenance_statement.endswith("?;")
    ):
        return "GC acquisition does not bind exact exclusive maintenance"
    forbidden_before = rust_code_projection(body[: maintenance[0][0]])
    if (
        any(
            token in forbidden_before
            for token in (
                "GC_LOCK_FILE",
                "lock_path",
                "create_new",
                "write_all",
                "remove_file",
            )
        )
        or "gc.lock" in body[: maintenance[0][0]]
    ):
        return "GC witness authority precedes exclusive maintenance"
    tail = body[maintenance[0][1] :]
    expected_tail = (
        "acquire_exclusive_gc_with_maintenance(store, store_root, maintenance)"
    )
    if normalize_rust_tokens(tail) != normalize_rust_tokens(expected_tail):
        return "GC acquisition does not tail-delegate with the owned guard"

    core = rust_named_function_raw_body(
        normal, "acquire_exclusive_gc_with_maintenance", "<crate>"
    )
    if core is None:
        return "GC guarded witness core is absent"
    core_projection = rust_code_projection(core)
    for token in ("GC_LOCK_FILE", "create_new", "write_all", "ExclusiveGcGuard"):
        if token not in core_projection:
            return f"GC guarded witness core lacks {token}"
    if "acquire_exclusive_repository_maintenance" in core_projection:
        return "GC guarded witness core reacquires maintenance"
    guard_fields = rust_item_body(normal, "struct", "ExclusiveGcGuard")
    if (
        len(
            re.findall(
                r"(?m)^\s*maintenance\s*:\s*RepositoryMaintenanceGuard\s*,\s*$",
                guard_fields,
            )
        )
        != 1
    ):
        return "ExclusiveGcGuard does not own exact maintenance authority"
    return None


def cross05_gc_recovery_problem(source: str) -> str | None:
    normal = normal_build_source(source)
    body = rust_named_function_raw_body(normal, "recover_gc_witness", "<crate>")
    if body is None:
        return "cannot isolate recover_gc_witness"
    validation = top_level_let_statement_ranges(body, "store_root")
    expected_validation = (
        "let store_root = validate_gc_recovery_maintenance(store, maintenance)?;"
    )
    if (
        len(validation) != 1
        or normalize_rust_tokens(validation[0][2])
        != normalize_rust_tokens(expected_validation)
        or rust_code_projection(body[: validation[0][0]]).strip()
    ):
        return "GC witness recovery guard validation is not first"
    tail = normalize_rust_tokens(rust_code_projection(body[validation[0][1] :]))
    ordered_tokens = (
        "GC_LOCK_DIR",
        "ensure_real_dir",
        "GC_LOCK_FILE",
        "symlink_metadata",
        "metadata.len",
        "GC_LOCK_BYTES.len",
        "File::open",
        "read_exact",
        "witness.read",
        "remove_file",
        "sync_dir",
    )
    cursor = 0
    for token in ordered_tokens:
        position = tail.find(token, cursor)
        if position < 0:
            return f"GC witness recovery lacks ordered {token} authority"
        cursor = position + len(token)
    if re.search(
        r"\b(?:acquire_shared_repository_maintenance|"
        r"acquire_exclusive_repository_maintenance|"
        r"initialize_repository_maintenance)\b",
        tail,
    ):
        return "GC witness recovery reacquires maintenance"
    if re.search(
        r"\b(?:drop|forget|unlock)\s*\(\s*maintenance\b|"
        r"\bmaintenance\s*=",
        tail,
    ):
        return "GC witness recovery releases or replaces its guard"
    return None


def cross05_production_contract_problem(sources: dict[str, str]) -> str | None:
    store = sources["crates/sley-store/src/lib.rs"]
    maintenance = sources["crates/sley-txn/src/maintenance.rs"]
    txn = sources["crates/sley-txn/src/repository.rs"]
    refs = sources["crates/sley-repo/src/refs.rs"]
    gc = sources["crates/sley-repo/src/gc.rs"]

    if problem := cross05_root_authority_problem(sources):
        return problem
    if problem := cross05_authority_binding_problem(sources):
        return problem
    if problem := cross05_guard_struct_problem(store, maintenance, txn, refs, gc):
        return problem
    if problem := cross05_fixture_authority_problem(store, txn, refs):
        return problem
    if problem := cross05_hook_authority_problem(
        txn,
        "install_transaction_recovery_hold",
        "hold_transaction_recovery_before_exclusive_drop",
    ):
        return f"transaction hook authority: {problem}"
    if problem := cross05_hook_authority_problem(
        refs,
        "install_ref_recovery_hold",
        "hold_ref_recovery_before_exclusive_drop",
    ):
        return f"ref hook authority: {problem}"
    for enum_name in ("Cross05Blocked", "Cross05Completed"):
        if problem := cross05_support_enum_problem(refs, enum_name):
            return problem

    if problem := cross05_recovery_wrapper_problem(
        txn,
        "implTransactionRepository",
        "recover",
        "recover_with_maintenance",
        "hold_transaction_recovery_before_exclusive_drop",
    ):
        return problem
    if problem := cross05_recovery_wrapper_problem(
        refs,
        "implBranchRepository",
        "recover_refs",
        "recover_refs_with_maintenance",
        "hold_ref_recovery_before_exclusive_drop",
    ):
        return problem

    shared_wrappers = (
        (
            txn,
            "implTransactionRepository",
            "commit",
            "commit_with_maintenance",
            """
let maintenance = self.acquire_shared_maintenance()?;
self.commit_with_maintenance(input, &maintenance)
""",
        ),
        (
            refs,
            "implBranchRepository",
            "create_branch",
            "create_branch_with_maintenance",
            """
let maintenance = self.acquire_shared_maintenance()?;
self.create_branch_with_maintenance(name, origin_transaction_id, &maintenance)
""",
        ),
        (
            refs,
            "implBranchRepository",
            "advance_branch",
            "advance_branch_with_maintenance",
            """
let maintenance = self.acquire_shared_maintenance()?;
self.advance_branch_with_maintenance(
    name,
    expected_head,
    new_head,
    &maintenance
)
""",
        ),
    )
    for source, owner, wrapper, core, expected in shared_wrappers:
        if problem := cross05_shared_wrapper_problem(
            source, owner, wrapper, expected, core
        ):
            return problem
    if problem := cross05_evolving_guarded_core_problem(sources):
        return problem
    if problem := cross05_gc_acquisition_problem(gc):
        return problem
    if problem := cross05_gc_recovery_problem(gc):
        return problem
    return cross05_production_body_problem(sources, CROSS_05_PRODUCTION_BODY_SHA256)


def require_cross05_evidence(
    subcase_id: str,
    entry: object,
    relative: str,
    source: str,
) -> None:
    if relative != CROSS_05_TEST_OWNERS[subcase_id]:
        fail(f"CROSS-05/{subcase_id} test owner differs")
    if problem := cross05_evidence_problem(entry):
        fail(f"CROSS-05/{subcase_id} evidence differs: {problem}")
    assert isinstance(entry, dict)
    semantic = entry["semantic_assertions"]
    tests = entry["tests"]
    assert isinstance(semantic, dict)
    assert isinstance(tests, list) and len(tests) == 1 and isinstance(tests[0], str)
    definition = exact_test_definition(source, tests[0])
    if definition is None:
        fail(f"CROSS-05/{subcase_id} cannot isolate its mapped test")
    if problem := cross05_test_body_problem(definition[0], subcase_id, semantic):
        fail(f"CROSS-05/{subcase_id} operation binding differs: {problem}")


def crate_for_source(relative: str) -> str:
    if relative.startswith("crates/sley-store/"):
        return "sley-store"
    if relative.startswith("crates/sley-txn/"):
        return "sley-txn"
    if relative.startswith("crates/sley-repo/"):
        return "sley-repo"
    fail(f"mapped test source has no owning crate: {relative}")


def qualified_test_name(relative: str, local_qualified: str) -> str:
    prefixes = {
        "crates/sley-store/src/lib.rs": "",
        "crates/sley-txn/src/repository.rs": "repository",
        "crates/sley-repo/src/refs.rs": "refs",
        "crates/sley-repo/src/gc.rs": "gc",
    }
    try:
        prefix = prefixes[relative]
    except KeyError:
        fail(f"mapped test source has no qualified-name rule: {relative}")
    if prefix:
        crate = crate_for_source(relative)
        library = production_rust(ROOT / f"crates/{crate}/src/lib.rs")
        require_rust_pattern(
            library,
            rf"(?:^|\n)\s*mod\s+{re.escape(prefix)}\s*;",
            f"exact {prefix} module declaration",
        )
        return f"{prefix}::{local_qualified}"
    return local_qualified


def require_owned_entry_evidence(
    row_id: str,
    subcase_id: str,
    entry: object,
    relative: str,
    source: str,
) -> None:
    if not isinstance(entry, dict):
        fail(f"{row_id}/{subcase_id} evidence is not an object")
    if subcase_id == "owned_stage":
        expected = {
            "expected_result": "PASS_REMOVED_AND_SYNCED",
            "owned_stage_removed": True,
            "preserved": False,
            "no_mutation": False,
        }
    else:
        result = (
            OWNED_ENTRY_ERROR_CODES[row_id]
            if subcase_id in OWNED_ENTRY_FATAL_SUBCASES
            else "PASS_PRESERVED"
        )
        expected = {
            "expected_result": result,
            "owned_stage_removed": False,
            "preserved": True,
            "no_mutation": True,
        }
    for field, value in expected.items():
        if not exact_json_scalar_equal(entry.get(field), value):
            fail(f"{row_id}/{subcase_id} {field} differs")
    require_semantic_assertions(
        f"{row_id}/{subcase_id}",
        entry,
        ("expected_result", "owned_stage_removed", "preserved", "no_mutation"),
    )
    require_exact_result_assertion(
        f"{row_id}/{subcase_id}",
        entry,
        "expected_result",
        expected["expected_result"],
        require_projection=subcase_id in OWNED_ENTRY_FATAL_SUBCASES,
    )
    require_owned_entry_coverage(row_id, subcase_id, entry)
    tests = entry.get("tests")
    if not isinstance(tests, list) or len(tests) != 1 or not isinstance(tests[0], str):
        fail(f"{row_id}/{subcase_id} lacks one exact owned-entry test")
    definition = exact_test_definition(source, tests[0])
    if definition is None:
        fail(f"{row_id}/{subcase_id} cannot isolate its owned-entry test")
    if problem := owned_entry_operation_binding_problem(
        definition[0],
        relative,
        row_id,
        subcase_id,
    ):
        fail(f"{row_id}/{subcase_id} owned-entry binding differs: {problem}")


def require_gc_partial_report_evidence(
    row_id: str, subcase_id: str, entry: object
) -> None:
    label = f"{row_id}/{subcase_id}"
    if not isinstance(entry, dict):
        fail(f"{label} evidence is not an object")
    expected: dict[str, object] = {
        "expected_result": "GC_DELETE_IO",
        "candidate_count": 3,
        "candidate_order_verified": True,
        "failed_candidate_index": 1,
        "durable_prefix_count": 1,
        "original_deletion_candidates_exact": True,
        "reachable_objects_unchanged": True,
        "deleted_objects_exact_prefix": True,
        "failed_object_exact_current": True,
        "failed_current_excluded": True,
        "suffix_untouched": True,
        "retry_complete": True,
        "third_run_empty": True,
        "failed_current_present": row_id == "GC-01",
    }
    if row_id == "GC-01":
        expected["retry_deleted_exact_remaining"] = True
    else:
        expected["retry_resynced_failed_leaf_before_replan"] = True
        expected["retry_deleted_exact_suffix"] = True
        expected["retry_did_not_claim_failed_current"] = True
    for field, value in expected.items():
        if not exact_json_scalar_equal(entry.get(field), value):
            fail(f"{label} {field} differs")
    fields = tuple(expected)
    require_semantic_assertions(label, entry, fields)
    require_exact_result_assertion(
        label,
        entry,
        "expected_result",
        "GC_DELETE_IO",
        require_projection=True,
    )


def owned_entry_coverage_tokens(row_id: str, subcase_id: str) -> tuple[str, ...]:
    simple = {
        "owned_stage": ("owned_stage",),
        "prefix_suffix_lookalikes": ("prefix_lookalike", "suffix_lookalike"),
        "object_id_fanout_mismatch": ("object_id_fanout_mismatch",),
        "unknown_ascii_regular": ("unknown_ascii_regular",),
        "unknown_non_utf8_regular": ("unknown_non_utf8_regular",),
    }
    if subcase_id in simple:
        return simple[subcase_id]
    if subcase_id == "object_id_case_width":
        return ("object_id_uppercase", "object_id_short", "object_id_long")
    if subcase_id == "pid_zero_case_width":
        return ("pid_zero", "pid_uppercase", "pid_short", "pid_long")
    if subcase_id == "counter_case_width":
        return ("counter_uppercase", "counter_short", "counter_long")
    if subcase_id == "pid_decimal_grammar":
        return ("pid_zero", "pid_leading_zero", "pid_overflow", "pid_nondigit")
    if subcase_id == "token_case_width":
        return ("token_uppercase", "token_short", "token_long")
    if subcase_id == "fanout_case_shape":
        return ("malformed_fanout", "uppercase_fanout")
    if subcase_id == "final_name_fanout_binding":
        return ("malformed_final_name", "uppercase_final_name", "final_fanout_mismatch")
    if subcase_id in {"symlink", "non_regular"}:
        suffix = "symlink" if subcase_id == "symlink" else "non_regular"
        if row_id == "COR-03":
            return (f"stage_{suffix}", f"accepted_{suffix}")
        return (f"fanout_{suffix}", f"stage_{suffix}", f"final_{suffix}")
    fail(f"{row_id}/{subcase_id} has no exact owned-entry coverage vocabulary")


def owned_entry_contract(row_id: str) -> dict[str, object]:
    try:
        return OWNED_ENTRY_ROW_CONTRACTS[row_id]
    except KeyError:
        fail(f"{row_id} has no owned-entry row contract")


def owned_entry_rust_path(parts: tuple[str | bytes, ...]) -> str:
    if not parts:
        return "::std::path::PathBuf::new()"
    prefix: list[str] = []
    suffix: bytes | None = None
    for component in parts:
        if isinstance(component, bytes):
            if suffix is not None or component is not parts[-1]:
                fail("owned-entry non-UTF8 path component is not one final component")
            suffix = component
        else:
            if suffix is not None:
                fail("owned-entry text component follows a non-UTF8 component")
            prefix.append(component)
    expression = f"::std::path::PathBuf::from({json.dumps('/'.join(prefix))})"
    if suffix is not None:
        values = ", ".join(str(value) for value in suffix)
        expression += (
            ".join(<::std::ffi::OsString as "
            "::std::os::unix::ffi::OsStringExt>::from_vec("
            f"::std::vec![{values}]))"
        )
    return expression


def owned_entry_path_sort_key(parts: tuple[str | bytes, ...]) -> bytes:
    encoded = tuple(
        component.encode("utf-8") if isinstance(component, str) else component
        for component in parts
    )
    return b"/".join(encoded)


def owned_entry_stage_name(
    row_id: str,
    *,
    object_id: str = OWNED_ENTRY_OBJECT_ID,
    object_pid: str = "00000001",
    object_counter: str = "00000001",
    pid: str = "1",
    token: str = "0000000000000001",
    include_prefix: bool = True,
    include_suffix: bool = True,
) -> str:
    contract = owned_entry_contract(row_id)
    prefix = contract["stage_prefix"] if include_prefix else "foreign-stage-"
    if not isinstance(prefix, str):
        fail("owned-entry stage prefix metadata differs")
    if row_id == "COR-01":
        body = f"{object_id}{object_pid}{object_counter}"
    else:
        body = f"{pid}-{token}"
    suffix = ".tmp" if include_suffix else ""
    return f"{prefix}{body}{suffix}"


def owned_entry_final_name(row_id: str, pair: tuple[str, str]) -> str:
    suffix = owned_entry_contract(row_id)["final_suffix"]
    if not isinstance(suffix, str):
        fail(f"{row_id} has no fan-out final-name contract")
    return f"{''.join(pair)}{'7' * 60}{suffix}"


def owned_entry_path_spec(
    row_id: str,
    name: str,
    parts: tuple[str | bytes, ...],
    kind: str,
    *,
    coverage: bool = True,
) -> dict[str, object]:
    spec: dict[str, object] = {
        "name": name,
        "parts": parts,
        "kind": kind,
        "coverage": coverage,
    }
    if kind == "regular":
        spec["bytes"] = f"S20-530:{row_id}:{name}".encode("ascii")
    elif kind == "symlink":
        spec["target"] = f"../../../../s20-530-{row_id.lower()}-{name}"
    elif kind == "non_regular":
        spec["mode"] = 0o140000
    elif kind != "directory":
        fail(f"{row_id}/{name} has an unknown owned-entry fixture kind {kind}")
    return spec


def owned_entry_canary_spec(row_id: str) -> dict[str, object]:
    contract = owned_entry_contract(row_id)
    base = contract["base"]
    if not isinstance(base, tuple) or any(not isinstance(value, str) for value in base):
        fail("owned-entry base metadata differs")
    name = PREFLIGHT_CANARIES[row_id][0]
    if row_id == "COR-01":
        stage = owned_entry_stage_name(
            row_id,
            object_id=OWNED_ENTRY_CANARY_OBJECT_ID,
            object_pid="00000001",
            object_counter="00000000",
        )
        parts: tuple[str | bytes, ...] = (*base, "00", "00", stage)
    elif row_id == "COR-03":
        stage = owned_entry_stage_name(row_id, pid="1", token="0000000000000000")
        parts = (*base, stage)
    else:
        stage = owned_entry_stage_name(row_id, pid="1", token="0000000000000000")
        parts = (*base, "00", "00", stage)
    return owned_entry_path_spec(row_id, name, parts, "regular", coverage=False)


def owned_entry_fixture_specs(
    row_id: str,
    subcase_id: str,
) -> tuple[dict[str, object], ...]:
    expected = owned_entry_coverage_tokens(row_id, subcase_id)
    contract = owned_entry_contract(row_id)
    base = contract["base"]
    if not isinstance(base, tuple) or any(not isinstance(value, str) for value in base):
        fail("owned-entry base metadata differs")

    def leaf(
        name: str,
        filename: str | bytes,
        kind: str = "regular",
        pair: tuple[str, str] = ("10", "20"),
    ) -> dict[str, object]:
        parts: tuple[str | bytes, ...]
        if row_id == "COR-03":
            parts = (*base, filename)
        else:
            parts = (*base, *pair, filename)
        return owned_entry_path_spec(row_id, name, parts, kind)

    specs: list[dict[str, object]] = []
    if subcase_id == "owned_stage":
        specs.append(leaf("owned_stage", owned_entry_stage_name(row_id)))
    elif subcase_id == "prefix_suffix_lookalikes":
        specs.extend(
            (
                leaf(
                    "prefix_lookalike",
                    owned_entry_stage_name(row_id, include_suffix=False),
                ),
                leaf(
                    "suffix_lookalike",
                    owned_entry_stage_name(row_id, include_prefix=False),
                ),
            )
        )
    elif subcase_id == "object_id_case_width":
        specs.extend(
            (
                leaf(
                    "object_id_uppercase",
                    owned_entry_stage_name(
                        row_id,
                        object_id=(OWNED_ENTRY_OBJECT_ID[:-1] + "A"),
                    ),
                ),
                leaf(
                    "object_id_short",
                    owned_entry_stage_name(
                        row_id,
                        object_id=OWNED_ENTRY_OBJECT_ID[:-1],
                    ),
                ),
                leaf(
                    "object_id_long",
                    owned_entry_stage_name(
                        row_id,
                        object_id=OWNED_ENTRY_OBJECT_ID + "3",
                    ),
                ),
            )
        )
    elif subcase_id == "pid_zero_case_width":
        specs.extend(
            (
                leaf(
                    "pid_zero",
                    owned_entry_stage_name(row_id, object_pid="00000000"),
                ),
                leaf(
                    "pid_uppercase",
                    owned_entry_stage_name(row_id, object_pid="0000000A"),
                ),
                leaf(
                    "pid_short",
                    owned_entry_stage_name(row_id, object_pid="0000001"),
                ),
                leaf(
                    "pid_long",
                    owned_entry_stage_name(row_id, object_pid="000000001"),
                ),
            )
        )
    elif subcase_id == "counter_case_width":
        specs.extend(
            (
                leaf(
                    "counter_uppercase",
                    owned_entry_stage_name(row_id, object_counter="0000000A"),
                ),
                leaf(
                    "counter_short",
                    owned_entry_stage_name(row_id, object_counter="0000001"),
                ),
                leaf(
                    "counter_long",
                    owned_entry_stage_name(row_id, object_counter="000000001"),
                ),
            )
        )
    elif subcase_id == "pid_decimal_grammar":
        specs.extend(
            leaf(name, owned_entry_stage_name(row_id, pid=pid))
            for name, pid in (
                ("pid_zero", "0"),
                ("pid_leading_zero", "01"),
                ("pid_overflow", "4294967296"),
                ("pid_nondigit", "one"),
            )
        )
    elif subcase_id == "token_case_width":
        specs.extend(
            leaf(name, owned_entry_stage_name(row_id, token=token))
            for name, token in (
                ("token_uppercase", "000000000000000A"),
                ("token_short", "000000000000001"),
                ("token_long", "00000000000000001"),
            )
        )
    elif subcase_id == "object_id_fanout_mismatch":
        specs.append(
            leaf(
                "object_id_fanout_mismatch",
                owned_entry_stage_name(row_id, object_id=OWNED_ENTRY_MISMATCH_ID),
            )
        )
    elif subcase_id == "fanout_case_shape":
        if row_id == "COR-03":
            fail("accepted-head owner cannot have a fan-out subcase")
        specs.extend(
            (
                owned_entry_path_spec(
                    row_id,
                    "malformed_fanout",
                    (*base, "f"),
                    "directory",
                ),
                owned_entry_path_spec(
                    row_id,
                    "uppercase_fanout",
                    (*base, "FE"),
                    "directory",
                ),
            )
        )
    elif subcase_id == "final_name_fanout_binding":
        if row_id == "COR-03":
            fail("accepted-head owner cannot have a final-name subcase")
        suffix = contract["final_suffix"]
        if not isinstance(suffix, str):
            fail("owned-entry final suffix metadata differs")
        specs.extend(
            (
                leaf(
                    "malformed_final_name",
                    f"{'g' * 64}{suffix}",
                    pair=("fd", "00"),
                ),
                leaf(
                    "uppercase_final_name",
                    f"{'A' * 64}{suffix}",
                    pair=("fe", "00"),
                ),
                leaf(
                    "final_fanout_mismatch",
                    f"{OWNED_ENTRY_MISMATCH_ID}{suffix}",
                    pair=("ff", "00"),
                ),
            )
        )
    elif subcase_id == "unknown_ascii_regular":
        specs.append(leaf("unknown_ascii_regular", "unknown-owned-entry.keep"))
    elif subcase_id == "unknown_non_utf8_regular":
        specs.append(leaf("unknown_non_utf8_regular", b"unknown-\xff-entry"))
    elif subcase_id in {"symlink", "non_regular"}:
        kind = "symlink" if subcase_id == "symlink" else "non_regular"
        suffix = "symlink" if subcase_id == "symlink" else "non_regular"
        if row_id == "COR-03":
            specs.extend(
                (
                    leaf(
                        f"stage_{suffix}",
                        owned_entry_stage_name(
                            row_id,
                            pid="2",
                            token="0000000000000002",
                        ),
                        kind,
                    ),
                    owned_entry_path_spec(
                        row_id,
                        f"accepted_{suffix}",
                        (*base, "accepted"),
                        kind,
                    ),
                )
            )
        else:
            specs.extend(
                (
                    owned_entry_path_spec(
                        row_id,
                        f"fanout_{suffix}",
                        (*base, "fd"),
                        kind,
                    ),
                    leaf(
                        f"stage_{suffix}",
                        owned_entry_stage_name(row_id, pid="2", token="2" * 16),
                        kind,
                        pair=("fe", "00"),
                    ),
                    leaf(
                        f"final_{suffix}",
                        owned_entry_final_name(row_id, ("ff", "00")),
                        kind,
                        pair=("ff", "00"),
                    ),
                )
            )
    else:
        fail(f"{row_id}/{subcase_id} has no owned-entry fixture specification")

    found = tuple(str(spec["name"]) for spec in specs)
    if found != expected:
        fail(
            f"{row_id}/{subcase_id} fixture specification order differs: "
            f"expected {expected!r}, found {found!r}"
        )
    if subcase_id in OWNED_ENTRY_FATAL_SUBCASES:
        specs.insert(0, owned_entry_canary_spec(row_id))
    return tuple(specs)


def owned_entry_expected_added_paths(
    row_id: str,
    subcase_id: str,
) -> tuple[tuple[str | bytes, ...], ...]:
    contract = owned_entry_contract(row_id)
    baseline = contract["baseline_directories"]
    if not isinstance(baseline, tuple):
        fail("owned-entry baseline directory metadata differs")
    baseline_set = set(baseline)
    added: set[tuple[str | bytes, ...]] = set()
    for spec in owned_entry_fixture_specs(row_id, subcase_id):
        parts = spec["parts"]
        kind = spec["kind"]
        if not isinstance(parts, tuple) or not isinstance(kind, str):
            fail("owned-entry fixture path metadata differs")
        for length in range(1, len(parts)):
            parent = parts[:length]
            if parent not in baseline_set:
                added.add(parent)
        added.add(parts)
    return tuple(sorted(added, key=owned_entry_path_sort_key))


def owned_entry_fixture_fact_assertions(
    spec: dict[str, object],
) -> tuple[str, ...]:
    name = spec["name"]
    kind = spec["kind"]
    if not isinstance(name, str) or not isinstance(kind, str):
        fail("owned-entry fixture fact metadata differs")
    snapshot = f"{name}_before_snapshot"
    assertions = [
        f"::core::assert_eq!({snapshot}.0, {json.dumps(kind)});"
    ]
    if kind == "regular":
        payload = spec.get("bytes")
        if not isinstance(payload, bytes):
            fail("owned-entry regular fixture lacks exact bytes")
        assertions.append(
            f"::core::assert_eq!({snapshot}.2, {json.dumps(payload.decode('ascii'))}.as_bytes().to_vec());"
        )
    elif kind == "symlink":
        target = spec.get("target")
        if not isinstance(target, str):
            fail("owned-entry symlink fixture lacks an exact target")
        assertions.append(
            f"::core::assert_eq!({snapshot}.3, "
            "::core::option::Option::Some(::std::path::PathBuf::from("
            f"{json.dumps(target)})));"
        )
    elif kind == "non_regular":
        mode = spec.get("mode")
        if type(mode) is not int:
            fail("owned-entry non-regular fixture lacks an exact mode")
        assertions.append(
            f"::core::assert_eq!({snapshot}.1 & 0o170000, 0o{mode:o});"
        )
    return tuple(assertions)


def owned_entry_coverage_assertion(
    spec: dict[str, object],
) -> str:
    assertions = owned_entry_fixture_fact_assertions(spec)
    return assertions[-1]


def owned_entry_label(row_id: str, subcase_id: str) -> str:
    return f"s20-530-{row_id.lower()}-{subcase_id.replace('_', '-')}"


def owned_entry_fresh_statements(
    row_id: str,
    subcase_id: str,
    relative: str,
) -> tuple[str, ...]:
    helper = snapshot_helper_path(relative, "exact_tree_snapshot")
    label = json.dumps(owned_entry_label(row_id, subcase_id))
    if row_id == "COR-01":
        fixture = (
            f"let temp = TempDir::new({label});",
            "let store = super::ObjectStore::new(temp.path());",
            "let owner_root = store.root();",
            "::core::assert_eq!(owner_root, temp.path());",
        )
    elif row_id in {"COR-02", "COR-03"}:
        fixture = (
            f"let fixture = Fixture::new({label});",
            "let repository: &super::TransactionRepository = &fixture.repository;",
            "let owner_root = repository.root();",
            "::core::assert_eq!(owner_root, fixture.path());",
            (
                "let maintenance: super::RepositoryMaintenanceGuard = repository"
                ".acquire_exclusive_maintenance().unwrap();"
            ),
        )
    else:
        fixture = (
            f"let fixture = Fixture::new({label});",
            "let branch_repository: &super::BranchRepository = &fixture.branches;",
            "let owner_root = branch_repository.root();",
            "::core::assert_eq!(owner_root, fixture.path());",
            (
                "let maintenance: super::RepositoryMaintenanceGuard = "
                "branch_repository"
                ".acquire_exclusive_maintenance().unwrap();"
            ),
        )
    return (
        *fixture,
        f"let fresh_owner_tree_snapshot = {helper}(owner_root);",
    )


def owned_entry_path_binding_statements(
    row_id: str,
    subcase_id: str,
) -> tuple[str, ...]:
    statements: list[str] = []
    for spec in owned_entry_fixture_specs(row_id, subcase_id):
        name = spec["name"]
        parts = spec["parts"]
        if not isinstance(name, str) or not isinstance(parts, tuple):
            fail("owned-entry path-binding metadata differs")
        relative = f"{name}_relative_path"
        path = f"{name}_path"
        statements.extend(
            (
                f"let {relative} = {owned_entry_rust_path(parts)};",
                f"let {path} = owner_root.join(&{relative});",
                (
                    f"::core::assert_eq!({path}.strip_prefix(owner_root).unwrap(), "
                    f"{relative});"
                ),
            )
        )
    return tuple(statements)


def owned_entry_fixture_setup_statements(
    row_id: str,
    subcase_id: str,
) -> tuple[str, ...]:
    statements: list[str] = []
    for spec in owned_entry_fixture_specs(row_id, subcase_id):
        name = spec["name"]
        kind = spec["kind"]
        if not isinstance(name, str) or not isinstance(kind, str):
            fail("owned-entry fixture setup metadata differs")
        path = f"{name}_path"
        if kind == "directory":
            statements.append(
                f"::std::fs::create_dir_all(&{path}).unwrap();"
            )
            continue
        statements.append(
            f"::std::fs::create_dir_all({path}.parent().unwrap()).unwrap();"
        )
        if kind == "regular":
            payload = spec.get("bytes")
            if not isinstance(payload, bytes):
                fail("owned-entry regular setup lacks exact bytes")
            statements.append(
                f"::std::fs::write(&{path}, "
                f"{json.dumps(payload.decode('ascii'))}.as_bytes()).unwrap();"
            )
        elif kind == "symlink":
            target = spec.get("target")
            if not isinstance(target, str):
                fail("owned-entry symlink setup lacks an exact target")
            statements.append(
                "::std::os::unix::fs::symlink("
                f"{json.dumps(target)}, &{path}).unwrap();"
            )
        elif kind == "non_regular":
            statements.append(
                f"let _{name}_socket = "
                f"::std::os::unix::net::UnixDatagram::bind(&{path}).unwrap();"
            )
        else:
            fail(f"owned-entry fixture setup kind differs: {kind}")
    return tuple(statements)


def owned_entry_path_vec(
    paths: tuple[tuple[str | bytes, ...], ...],
) -> str:
    values = ",".join(owned_entry_rust_path(path) for path in paths)
    return f"::std::vec![{values}]"


def owned_entry_empty_path_vec() -> str:
    return "::std::vec::Vec::<::std::path::PathBuf>::new()"


def owned_entry_operation_call(row_id: str) -> str:
    if row_id == "COR-01":
        return "store.recover_staged()"
    if row_id in {"COR-02", "COR-03"}:
        return "repository.recover_with_maintenance(&maintenance)"
    if row_id in {"COR-04", "COR-05"}:
        return "branch_repository.recover_refs_with_maintenance(&maintenance)"
    fail(f"{row_id} has no owned-entry operation")


def owned_entry_before_statements(
    row_id: str,
    subcase_id: str,
    relative: str,
) -> tuple[str, ...]:
    tree_helper = snapshot_helper_path(relative, "exact_tree_snapshot")
    delta_helper = snapshot_helper_path(relative, "exact_tree_delta_paths")
    path_helper = snapshot_helper_path(relative, "exact_path_snapshot")
    added = owned_entry_path_vec(
        owned_entry_expected_added_paths(row_id, subcase_id)
    )
    statements = [
        f"let owner_tree_before_snapshot = {tree_helper}(owner_root);",
        (
            "let fixture_delta = "
            f"{delta_helper}(&fresh_owner_tree_snapshot, "
            "&owner_tree_before_snapshot);"
        ),
        f"::core::assert_eq!(fixture_delta.0, {added});",
        f"::core::assert_eq!(fixture_delta.1, {owned_entry_empty_path_vec()});",
        f"::core::assert_eq!(fixture_delta.2, {owned_entry_empty_path_vec()});",
    ]
    specs = owned_entry_fixture_specs(row_id, subcase_id)
    for spec in specs:
        name = spec["name"]
        if not isinstance(name, str):
            fail("owned-entry before-snapshot name metadata differs")
        statements.extend(
            (
                (
                    f"let {name}_before_snapshot = "
                    f"{path_helper}(&{name}_path);"
                ),
                f"let {name}_before_kind = {name}_before_snapshot.0;",
                *owned_entry_fixture_fact_assertions(spec),
            )
        )
    if subcase_id in OWNED_ENTRY_FATAL_SUBCASES:
        canary = specs[0]["name"]
        if not isinstance(canary, str):
            fail("owned-entry canary metadata differs")
        for spec in specs[1:]:
            name = spec["name"]
            if not isinstance(name, str):
                fail("owned-entry ordered-fault metadata differs")
            statements.append(
                f"::core::assert!({canary}_relative_path < {name}_relative_path);"
            )
    statements.append(f"let result = {owned_entry_operation_call(row_id)};")
    return tuple(statements)


def owned_entry_operation_delta_removed_paths(
    row_id: str,
    subcase_id: str,
) -> tuple[tuple[str | bytes, ...], ...]:
    if subcase_id != "owned_stage":
        return ()
    specs = owned_entry_fixture_specs(row_id, subcase_id)
    parts = specs[0]["parts"]
    if not isinstance(parts, tuple):
        fail("owned-entry removed-path metadata differs")
    return (parts,)


def owned_entry_error_variant_assertion(row_id: str, relative: str) -> str | None:
    if row_id == "COR-01":
        return None
    variant = "commit.io" if row_id in {"COR-02", "COR-03"} else "branch.io"
    return (
        "::core::assert!(::core::matches!((&error), "
        f"{error_variant_pattern(relative, variant)}));"
    )


def owned_entry_report_assertions(
    row_id: str,
    subcase_id: str,
) -> tuple[str, ...]:
    removed = 1 if subcase_id == "owned_stage" else 0
    contract = owned_entry_contract(row_id)
    report_field = contract["report_field"]
    other_fields = contract["other_report_fields"]
    if row_id == "COR-01":
        if removed:
            return (
                "::core::assert_eq!(report.len(), 1);",
                '::core::assert_eq!(report[0].code, "RECOVERY_STAGED_OBJECT");',
                (
                    "::core::assert_eq!(report[0].relative_path, "
                    "owned_stage_relative_path);"
                ),
            )
        return ("::core::assert!(report.is_empty());",)
    if not isinstance(report_field, str) or not isinstance(other_fields, tuple):
        fail("owned-entry report metadata differs")
    assertions = [f"::core::assert_eq!(report.{report_field}, {removed});"]
    assertions.extend(
        f"::core::assert_eq!(report.{field}, 0);" for field in other_fields
    )
    return tuple(assertions)


def owned_entry_after_statements(
    row_id: str,
    subcase_id: str,
    relative: str,
) -> tuple[str, ...]:
    fatal = subcase_id in OWNED_ENTRY_FATAL_SUBCASES
    tree_helper = snapshot_helper_path(relative, "exact_tree_snapshot")
    delta_helper = snapshot_helper_path(relative, "exact_tree_delta_paths")
    path_helper = snapshot_helper_path(relative, "exact_path_snapshot")
    optional_helper = snapshot_helper_path(relative, "exact_optional_path_snapshot")
    statements: list[str] = []
    if fatal:
        statements.extend(
            (
                "::core::assert!(result.is_err());",
                'let error = result.expect_err("expected owned-entry recovery error");',
            )
        )
    else:
        statements.extend(
            (
                "::core::assert!(result.is_ok());",
                'let report = result.expect("expected owned-entry recovery success");',
            )
        )
    statements.extend(
        (
            f"let owner_tree_after_snapshot = {tree_helper}(owner_root);",
            (
                "let operation_delta = "
                f"{delta_helper}(&owner_tree_before_snapshot, "
                "&owner_tree_after_snapshot);"
            ),
            (
                f"::core::assert_eq!(operation_delta.0, "
                f"{owned_entry_empty_path_vec()});"
            ),
            (
                f"::core::assert_eq!(operation_delta.1, "
                f"{owned_entry_empty_path_vec()});"
            ),
            (
                f"::core::assert_eq!(operation_delta.2, "
                f"{owned_entry_path_vec(owned_entry_operation_delta_removed_paths(row_id, subcase_id))});"
            ),
        )
    )
    for spec in owned_entry_fixture_specs(row_id, subcase_id):
        name = spec["name"]
        if not isinstance(name, str):
            fail("owned-entry after-snapshot name metadata differs")
        if subcase_id == "owned_stage" and name == "owned_stage":
            statements.extend(
                (
                    (
                        f"let {name}_after_snapshot = "
                        f"{optional_helper}(&{name}_path);"
                    ),
                    (
                        f"::core::assert_eq!({name}_after_snapshot, "
                        "::core::option::Option::None);"
                    ),
                )
            )
        else:
            statements.extend(
                (
                    (
                        f"let {name}_after_snapshot = "
                        f"{path_helper}(&{name}_path);"
                    ),
                    f"let {name}_after_kind = {name}_after_snapshot.0;",
                    (
                        f"::core::assert_eq!({name}_after_snapshot, "
                        f"{name}_before_snapshot);"
                    ),
                )
            )
    if fatal:
        code = OWNED_ENTRY_ERROR_CODES[row_id]
        projection = "error.symbol()" if row_id == "COR-01" else "error.code()"
        statements.append(
            f"::core::assert_eq!({projection}, {json.dumps(code)});"
        )
        variant = owned_entry_error_variant_assertion(row_id, relative)
        if variant is not None:
            statements.append(variant)
    else:
        statements.extend(owned_entry_report_assertions(row_id, subcase_id))
    return tuple(statements)


def owned_entry_operation_binding_problem(
    body: str,
    relative: str,
    row_id: str,
    subcase_id: str,
) -> str | None:
    contract = owned_entry_contract(row_id)
    if relative != contract["source"]:
        return "mapped test owner differs from its exact recovery owner"
    projected = rust_code_projection(body)
    if re.search(
        r"\b(?:restore|restorer|restoration)\b|"
        r"(?:\b(?:std\s*::\s*)?thread\s*::\s*spawn\b|"
        r"\b(?:std\s*::\s*)?process\s*::\s*Command\s*::\s*new\b)",
        projected,
    ):
        return "mapped owned-entry test contains restoration authority"

    fresh = owned_entry_fresh_statements(row_id, subcase_id, relative)
    fresh_range = exact_statement_sequence_range(body, fresh)
    if fresh_range is None or rust_code_projection(body[: fresh_range[0]]).strip():
        return "fresh owner fixture/root/baseline binding is not the exact prefix"
    paths = owned_entry_path_binding_statements(row_id, subcase_id)
    path_range = exact_statement_sequence_range(body, paths)
    if path_range is None or rust_code_projection(
        body[fresh_range[1] : path_range[0]]
    ).strip():
        return "case paths are not bound exactly after the fresh baseline"

    setup = owned_entry_fixture_setup_statements(row_id, subcase_id)
    setup_range = exact_statement_sequence_range(body, setup)
    if setup_range is None or rust_code_projection(
        body[path_range[1] : setup_range[0]]
    ).strip():
        return "case fixture is not materialized exactly after path binding"

    before = owned_entry_before_statements(row_id, subcase_id, relative)
    before_range = exact_statement_sequence_range(body, before)
    if before_range is None or rust_code_projection(
        body[setup_range[1] : before_range[0]]
    ).strip():
        return "fixture delta/facts and recovery operation are not one exact sequence"

    operation = owned_entry_operation_call(row_id)
    if code_only_normalized(body).count(code_only_normalized(operation)) != 1:
        return "exact owner recovery operation is not invoked exactly once"

    after = owned_entry_after_statements(row_id, subcase_id, relative)
    after_range = exact_statement_sequence_range(body, after)
    if after_range is None or rust_code_projection(
        body[before_range[1] : after_range[0]]
    ).strip():
        return "post-operation snapshots/outcome are not one immediate exact sequence"
    if rust_code_projection(body[after_range[1] :]).strip():
        return "mapped owned-entry test has trailing unreviewed authority"
    return None


def require_owned_entry_coverage(
    row_id: str,
    subcase_id: str,
    entry: dict[str, object],
) -> None:
    expected = owned_entry_coverage_tokens(row_id, subcase_id)
    mapping = entry.get("coverage_assertions")
    assertions = entry.get("assertions")
    if not isinstance(mapping, dict) or tuple(mapping) != expected:
        fail(f"{row_id}/{subcase_id} coverage-assertion cases/order differ")
    if not isinstance(assertions, list) or len(set(mapping.values())) != len(expected):
        fail(f"{row_id}/{subcase_id} reuses or lacks coverage assertions")
    specs = {
        str(spec["name"]): spec
        for spec in owned_entry_fixture_specs(row_id, subcase_id)
        if spec["coverage"] is True
    }
    if tuple(specs) != expected:
        fail(f"{row_id}/{subcase_id} checker fixture coverage differs")
    for case, assertion in mapping.items():
        if not isinstance(assertion, str) or assertion not in assertions:
            fail(f"{row_id}/{subcase_id} coverage case {case} lacks an exact assertion")
        frozen = owned_entry_coverage_assertion(specs[case])
        if normalize_rust_tokens(assertion) != normalize_rust_tokens(frozen):
            fail(
                f"{row_id}/{subcase_id} coverage case {case} assertion differs: "
                "not the exact concrete fixture fact"
            )


def require_semantic_assertions(
    label: str,
    entry: dict[str, object],
    fields: tuple[str, ...],
    *,
    custom_fields: frozenset[str] = frozenset(),
) -> None:
    mapping = entry.get("semantic_assertions")
    assertions = entry.get("assertions")
    if not isinstance(mapping, dict) or tuple(mapping) != fields:
        fail(f"{label} semantic-assertion fields/order differ")
    if not isinstance(assertions, list):
        fail(f"{label} lacks an assertion list")
    if len(set(mapping.values())) != len(fields):
        fail(f"{label} reuses one assertion for multiple semantic fields")
    for field, assertion in mapping.items():
        if not isinstance(assertion, str) or assertion not in assertions:
            fail(f"{label} semantic field {field} lacks an exact assertion")
        if field in custom_fields:
            continue
        expected = entry.get(field)
        if isinstance(expected, (bool, int, str)):
            if problem := exact_value_assertion_problem(assertion, field, expected):
                fail(f"{label} semantic field {field} assertion differs: {problem}")
        elif not code_contains_token(assertion, field):
            fail(f"{label} semantic field {field} lacks a bound assertion")


def preflight_canary_problem(
    row_id: str,
    subcase_id: str | None,
    entry: dict[str, object],
) -> str | None:
    names = PREFLIGHT_CANARIES[row_id]
    expected_hash_fields = (
        *(
            field
            for name in names
            for field in (f"{name}_before_sha256", f"{name}_after_sha256")
        ),
        "owner_tree_before_sha256",
        "owner_tree_after_sha256",
    )
    hashes = entry.get("cleanup_canary_hashes")
    if not isinstance(hashes, dict) or tuple(hashes) != expected_hash_fields:
        return "cleanup-canary hash fields/order differ"
    expected_kind_fields = tuple(
        field
        for name in names
        for field in (f"{name}_before_kind", f"{name}_after_kind")
    )
    kinds = entry.get("cleanup_canary_kinds")
    if not isinstance(kinds, dict) or tuple(kinds) != expected_kind_fields:
        return "cleanup-canary kind fields/order differ"
    expected_assertion_fields: list[str] = []
    for name in names:
        expected_assertion_fields.extend(
            (
                f"{name}_bytes",
                f"{name}_kind",
                f"{name}_expected_kind",
            )
        )
        if (row_id, subcase_id, name) in PREFLIGHT_CANARY_FIXTURE_ASSERTIONS:
            expected_assertion_fields.append(f"{name}_fixture")
    expected_assertion_fields.append("owner_tree")
    expected_assertions = tuple(expected_assertion_fields)
    mapping = entry.get("cleanup_canary_assertions")
    if not isinstance(mapping, dict) or tuple(mapping) != expected_assertions:
        return "cleanup-canary assertion fields/order differ"
    assertions = entry.get("assertions")
    if not isinstance(assertions, list):
        return "assertion list is missing"
    if len(set(mapping.values())) != len(expected_assertions):
        return "cleanup-canary assertions are missing or reused"
    for name in names:
        before_name = f"{name}_before_sha256"
        after_name = f"{name}_after_sha256"
        before = hashes.get(before_name)
        after = hashes.get(after_name)
        if (
            not isinstance(before, str)
            or re.fullmatch(r"[0-9a-f]{64}", before) is None
            or after != before
        ):
            return f"{name} before/after byte hashes differ or are malformed"
        before_kind = f"{name}_before_kind"
        after_kind = f"{name}_after_kind"
        expected_kind = PREFLIGHT_CANARY_KINDS.get(
            (row_id, subcase_id, name),
            "regular",
        )
        if (
            kinds.get(before_kind) != expected_kind
            or kinds.get(after_kind) != expected_kind
        ):
            return f"{name} does not remain an exact {expected_kind} entry"
        assertion = mapping.get(f"{name}_bytes")
        if not isinstance(assertion, str) or assertion not in assertions:
            return f"{name} lacks a mapped byte assertion"
        operands = exact_assert_eq_operands(assertion)
        if operands is None or {
            code_only_normalized(operands[0]),
            code_only_normalized(operands[1]),
        } != {f"{name}_before_snapshot", f"{name}_after_snapshot"}:
            return f"{name} assertion does not compare exact before/after snapshots"
        kind_assertion = mapping.get(f"{name}_kind")
        if not isinstance(kind_assertion, str) or kind_assertion not in assertions:
            return f"{name} lacks a mapped kind assertion"
        kind_operands = exact_assert_eq_operands(kind_assertion)
        if kind_operands is None or {
            code_only_normalized(kind_operands[0]),
            code_only_normalized(kind_operands[1]),
        } != {before_kind, after_kind}:
            return f"{name} assertion does not compare exact before/after kinds"
        expected_kind_assertion = mapping.get(f"{name}_expected_kind")
        frozen_expected_kind_assertion = (
            f"::core::assert_eq!({before_kind}, {json.dumps(expected_kind)});"
        )
        if (
            not isinstance(expected_kind_assertion, str)
            or expected_kind_assertion not in assertions
            or normalize_rust_tokens(expected_kind_assertion)
            != normalize_rust_tokens(frozen_expected_kind_assertion)
        ):
            return f"{name} expected-kind assertion differs"
        frozen_fixture_assertion = PREFLIGHT_CANARY_FIXTURE_ASSERTIONS.get(
            (row_id, subcase_id, name)
        )
        if frozen_fixture_assertion is not None:
            fixture_assertion = mapping.get(f"{name}_fixture")
            if (
                not isinstance(fixture_assertion, str)
                or fixture_assertion not in assertions
                or normalize_rust_tokens(fixture_assertion)
                != normalize_rust_tokens(frozen_fixture_assertion)
            ):
                return f"{name} exact fixture assertion differs"
    tree_before = hashes.get("owner_tree_before_sha256")
    tree_after = hashes.get("owner_tree_after_sha256")
    if (
        not isinstance(tree_before, str)
        or re.fullmatch(r"[0-9a-f]{64}", tree_before) is None
        or tree_after != tree_before
    ):
        return "owner-tree before/after byte hashes differ or are malformed"
    tree_assertion = mapping.get("owner_tree")
    if not isinstance(tree_assertion, str) or tree_assertion not in assertions:
        return "owner tree lacks a mapped byte assertion"
    tree_operands = exact_assert_eq_operands(tree_assertion)
    if tree_operands is None or {
        code_only_normalized(tree_operands[0]),
        code_only_normalized(tree_operands[1]),
    } != {"owner_tree_before_snapshot", "owner_tree_after_snapshot"}:
        return "owner-tree assertion does not compare exact before/after snapshots"
    return None


def require_preflight_canary_evidence(
    row_id: str,
    subcase_id: str | None,
    entry: dict[str, object],
    leaf_id: str | None = None,
) -> None:
    if problem := preflight_canary_problem(row_id, subcase_id, entry):
        label = (
            row_id
            if subcase_id is None
            else f"{row_id}/{subcase_id}"
            if leaf_id is None
            else f"{row_id}/{subcase_id}/{leaf_id}"
        )
        fail(f"{label} preflight cleanup canary differs: {problem}")


def parse_validation_log(
    payload: bytes, command: str, execution_profile_sha256: str
) -> tuple[int, bytes] | None:
    prefix = (
        f"$ {command}\n"
        f"execution_profile_sha256: {execution_profile_sha256}\n"
        "exit_status: "
    ).encode("utf-8")
    if not payload.startswith(prefix):
        return None
    status_end = payload.find(b"\n", len(prefix))
    if status_end < 0:
        return None
    encoded_status = payload[len(prefix) : status_end]
    if re.fullmatch(rb"0|[1-9][0-9]*", encoded_status) is None:
        return None
    return int(encoded_status), payload[status_end + 1 :]


def cargo_listed_tests(payload: bytes) -> list[str] | None:
    try:
        text = payload.decode("utf-8", errors="strict")
    except UnicodeDecodeError:
        return None
    return sorted(
        {
            match["name"].strip()
            for line in text.splitlines()
            if (match := re.fullmatch(r"(?P<name>.+): test", line.strip()))
        }
    )


def cargo_passed_tests(payload: bytes) -> list[str] | None:
    try:
        text = payload.decode("utf-8", errors="strict")
    except UnicodeDecodeError:
        return None
    return sorted(
        {
            match["name"]
            for line in text.splitlines()
            if (match := re.fullmatch(r"test (?P<name>[^\s]+) \.\.\. ok", line.strip()))
        }
    )


def validation_log_problem(
    result: dict[str, object],
    command: str,
    expected_relative: str,
    used_logs: set[str],
    verify_log: bool,
    execution_profile_sha256: str,
    *,
    derive: str | None = None,
) -> str | None:
    relative = result.get("output_log")
    digest = result.get("output_sha256")
    if (
        not isinstance(relative, str)
        or relative != expected_relative
        or Path(relative).is_absolute()
        or ".." in Path(relative).parts
    ):
        return f"{command} output-log path is not the exact expected output"
    if relative in used_logs:
        return f"{command} reuses output log {relative}"
    used_logs.add(relative)
    if not isinstance(digest, str) or re.fullmatch(r"[0-9a-f]{64}", digest) is None:
        return f"{command} lacks an output SHA-256"
    if verify_log:
        path = ROOT / relative
        try:
            metadata = path.lstat()
        except OSError:
            return f"{command} output log is missing"
        if not stat.S_ISREG(metadata.st_mode):
            return f"{command} output log is not a regular file"
        payload = path.read_bytes()
        if hashlib.sha256(payload).hexdigest() != digest:
            return f"{command} output log digest differs"
        parsed = parse_validation_log(payload, command, execution_profile_sha256)
        if parsed is None:
            return f"{command} output log header is malformed or unbound"
        parsed_status, command_output = parsed
        if parsed_status != result.get("exit_status"):
            return f"{command} output log exit status differs"
        if derive == "listed":
            derived = cargo_listed_tests(command_output)
            if derived is None or derived != result.get("listed_tests"):
                return f"{command} listed tests differ from hashed log bytes"
        elif derive == "passed":
            derived = cargo_passed_tests(command_output)
            if derived is None or derived != result.get("passed_tests"):
                return f"{command} passed tests differ from hashed log bytes"
    return None


def execution_profile_payload(
    source_set_sha256: str,
    validated_commit: str,
    validated_tree: str,
    tools: dict[str, object],
    git_authority: dict[str, object],
) -> dict[str, object]:
    return {
        "trust_boundary": EXECUTION_TRUST_BOUNDARY,
        "assumptions": list(EXECUTION_ASSUMPTIONS),
        "source_snapshot": "fresh-exact-validated-commit-git-archive-per-command",
        "source_set_sha256": source_set_sha256,
        "validated_commit": validated_commit,
        "validated_tree": validated_tree,
        "environment": EXECUTION_ENVIRONMENT,
        "git_environment": GIT_ENVIRONMENT,
        "git_local_authority": git_authority,
        "tools": tools,
        "python_launcher_sha256": hashlib.sha256(PYTHON_LAUNCHER).hexdigest(),
        "command_timeout_seconds": COMMAND_TIMEOUT_SECONDS,
        "command_output_limit_bytes": COMMAND_OUTPUT_LIMIT_BYTES,
        "test_list_commands": list(TEST_LIST_COMMANDS),
        "tier_2_commands": list(TIER_2_COMMANDS),
    }


def tool_manifest_problem(tools: object, *, verify_tools: bool) -> str | None:
    if not isinstance(tools, dict) or tuple(tools) != EXECUTION_TOOL_NAMES:
        return "execution tool names/order differ"
    for name, record in tools.items():
        if not isinstance(record, dict) or tuple(record) != (
            "path",
            "uid",
            "gid",
            "mode",
            "sha256",
        ):
            return f"{name} tool record fields/order differ"
        path_value = record.get("path")
        uid = record.get("uid")
        gid = record.get("gid")
        mode = record.get("mode")
        digest = record.get("sha256")
        if (
            not isinstance(path_value, str)
            or not Path(path_value).is_absolute()
            or type(uid) is not int
            or uid < 0
            or type(gid) is not int
            or gid < 0
            or not isinstance(mode, str)
            or re.fullmatch(r"0[0-7]{3}", mode) is None
            or int(mode, 8) & 0o022
            or not isinstance(digest, str)
            or re.fullmatch(r"[0-9a-f]{64}", digest) is None
        ):
            return f"{name} tool record is malformed"
        if verify_tools:
            path = Path(path_value)
            try:
                metadata = path.lstat()
            except OSError:
                return f"{name} tool path is missing"
            if (
                not stat.S_ISREG(metadata.st_mode)
                or metadata.st_uid != uid
                or metadata.st_gid != gid
                or f"{stat.S_IMODE(metadata.st_mode):04o}" != mode
                or file_sha256(path) != digest
            ):
                return f"{name} tool identity differs"
    return None


def execution_binding_problem(
    validation: object,
    tests: list[str],
    test_owners: dict[str, str],
    qualified_tests: dict[str, str],
    workspace_inputs: dict[str, dict[str, str]],
    *,
    verify_repository: bool = True,
    verify_logs: bool = True,
) -> str | None:
    if not isinstance(validation, dict):
        return "validation is not an object"
    expected_validation_fields = (
        "workspace_inputs",
        "source_set_sha256",
        "runner",
        "runner_sha256",
        "execution_trust_boundary",
        "environment",
        "environment_sha256",
        "git_local_authority",
        "tools",
        "tools_sha256",
        "execution_profile_sha256",
        "executed_tests",
        "test_names_sha256",
        "test_owners",
        "qualified_tests",
        "validated_commit",
        "validated_tree",
        "test_lists",
        "commands",
    )
    if tuple(validation) != expected_validation_fields:
        return "validation fields/order differ"
    recorded_inputs = validation.get("workspace_inputs")
    if not isinstance(recorded_inputs, dict) or tuple(recorded_inputs) != tuple(
        workspace_inputs
    ):
        return "workspace-input paths/order differ"
    if recorded_inputs != workspace_inputs:
        return "workspace-input hashes are stale"
    source_set_sha256 = canonical_json_sha256(workspace_inputs)
    if validation.get("source_set_sha256") != source_set_sha256:
        return "source-set digest differs"
    if validation.get("runner") != str(RUNNER.relative_to(ROOT)):
        return "validation runner path differs"
    if validation.get("runner_sha256") != FROZEN_RUNNER_SHA256:
        return "validation runner hash differs"
    if validation.get("execution_trust_boundary") != EXECUTION_TRUST_BOUNDARY:
        return "execution trust boundary differs"
    environment = validation.get("environment")
    if environment != EXECUTION_ENVIRONMENT:
        return "execution environment differs"
    environment_sha256 = canonical_json_sha256(EXECUTION_ENVIRONMENT)
    if validation.get("environment_sha256") != environment_sha256:
        return "execution environment digest differs"
    tools = validation.get("tools")
    if problem := tool_manifest_problem(tools, verify_tools=verify_repository):
        return problem
    assert isinstance(tools, dict)
    tools_sha256 = canonical_json_sha256(tools)
    if validation.get("tools_sha256") != tools_sha256:
        return "execution tool-manifest digest differs"
    if validation.get("executed_tests") != tests:
        return "executed test list differs"
    test_names_sha256 = canonical_json_sha256(tests)
    if validation.get("test_names_sha256") != test_names_sha256:
        return "executed test-list digest differs"
    if validation.get("test_owners") != test_owners:
        return "mapped test-owner bindings differ"
    if validation.get("qualified_tests") != qualified_tests:
        return "mapped Cargo-qualified test bindings differ"
    revision = validation.get("validated_commit")
    tree = validation.get("validated_tree")
    if (
        not isinstance(revision, str)
        or re.fullmatch(r"[0-9a-f]{40,64}", revision) is None
    ):
        return "validated Git commit is malformed"
    if not isinstance(tree, str) or re.fullmatch(r"[0-9a-f]{40,64}", tree) is None:
        return "validated Git tree is malformed"
    git_authority = validation.get("git_local_authority")
    if problem := git_local_authority_record_problem(git_authority):
        return problem
    assert isinstance(git_authority, dict)
    profile = execution_profile_payload(
        source_set_sha256, revision, tree, tools, git_authority
    )
    execution_profile_sha256 = canonical_json_sha256(profile)
    if validation.get("execution_profile_sha256") != execution_profile_sha256:
        return "execution profile digest differs"
    if verify_repository:
        if git_local_authority() != git_authority:
            return "Git local authority differs from validated execution"
        dirty = workspace_input_dirtiness(allow_post_validation_outputs=True)
        if dirty:
            return f"workspace inputs are dirty: {dirty!r}"
        if flags := index_flag_problems():
            return f"Git index carries non-default input flags: {flags!r}"
        if not revision_is_ancestor(revision):
            return "validated commit is not an ancestor of HEAD"
        if non_output_changes_since(revision):
            return "non-output input changed after validation"
        if git_text("rev-parse", f"{revision}^{{tree}}") != tree:
            return "validated Git tree differs"
        if commit_input_hashes(revision) != workspace_inputs:
            return "recorded workspace inputs differ from validated commit blobs"
        current_non_outputs = {
            path: descriptor
            for path, descriptor in workspace_input_hashes().items()
            if not is_validation_output_path(path)
        }
        committed_non_outputs = {
            path: descriptor
            for path, descriptor in workspace_inputs.items()
            if not is_validation_output_path(path)
        }
        if current_non_outputs != committed_non_outputs:
            return "current non-output bytes/modes differ from validated commit"

    used_logs: set[str] = set()
    test_lists = validation.get("test_lists")
    if not isinstance(test_lists, dict) or tuple(test_lists) != TEST_LIST_COMMANDS:
        return "Cargo test-list command set/order differs"
    listed_by_crate: dict[str, list[str]] = {}
    list_fields = (
        "result",
        "exit_status",
        "crate",
        "source_set_sha256",
        "validated_commit",
        "validated_tree",
        "output_log",
        "output_sha256",
        "listed_tests",
        "listed_tests_sha256",
        "execution_profile_sha256",
        "duration_seconds",
        "skipped_checks",
    )
    for index, (command, result) in enumerate(test_lists.items()):
        if not isinstance(result, dict) or tuple(result) != list_fields:
            return f"{command} test-list result fields/order differ"
        crate = TEST_LIST_CRATES[index]
        exit_status = result.get("exit_status")
        if (
            result.get("result") != "PASS"
            or type(exit_status) is not int
            or isinstance(exit_status, bool)
            or exit_status != 0
        ):
            return f"{command} is not a zero-exit PASS"
        if result.get("crate") != crate:
            return f"{command} crate binding differs"
        if result.get("source_set_sha256") != source_set_sha256:
            return f"{command} test list is bound to stale source"
        if (
            result.get("validated_commit") != revision
            or result.get("validated_tree") != tree
        ):
            return f"{command} test list Git binding differs"
        listed = result.get("listed_tests")
        if (
            not isinstance(listed, list)
            or any(not isinstance(name, str) or not name for name in listed)
            or listed != sorted(set(listed))
        ):
            return f"{command} listed-test vocabulary is not sorted and unique"
        if result.get("listed_tests_sha256") != canonical_json_sha256(listed):
            return f"{command} listed-test digest differs"
        listed_by_crate[crate] = listed
        if result.get("execution_profile_sha256") != execution_profile_sha256:
            return f"{command} test list execution-profile binding differs"
        duration = result.get("duration_seconds")
        if (
            not isinstance(duration, (int, float))
            or isinstance(duration, bool)
            or not math.isfinite(duration)
            or duration < 0
        ):
            return f"{command} lacks a valid duration"
        if result.get("skipped_checks") != []:
            return f"{command} test listing reports skipped checks"
        expected_log = validation_log_relative("test-list", index + 1, command)
        if problem := validation_log_problem(
            result,
            command,
            expected_log,
            used_logs,
            verify_logs,
            execution_profile_sha256,
            derive="listed",
        ):
            return problem
    for test, crate in test_owners.items():
        qualified = qualified_tests[test]
        if qualified not in listed_by_crate[crate]:
            return (
                f"mapped test {test} is absent as exact {qualified} from the "
                f"{crate} Cargo test list"
            )

    commands = validation.get("commands")
    if not isinstance(commands, dict) or tuple(commands) != TIER_2_COMMANDS:
        return "Tier 2 command set/order differs"
    command_fields = (
        "result",
        "exit_status",
        "source_set_sha256",
        "test_names_sha256",
        "validated_commit",
        "validated_tree",
        "output_log",
        "output_sha256",
        "execution_profile_sha256",
        "duration_seconds",
        "skipped_checks",
    )
    passed_by_crate: dict[str, list[str]] = {}
    for index, (command, result) in enumerate(commands.items()):
        expected_fields = command_fields
        if index < len(TEST_LIST_CRATES):
            expected_fields = (
                *command_fields[:8],
                "passed_tests",
                "passed_tests_sha256",
                *command_fields[8:],
            )
        if not isinstance(result, dict) or tuple(result) != expected_fields:
            return f"{command} result fields/order differ"
        exit_status = result.get("exit_status")
        if (
            result.get("result") != "PASS"
            or type(exit_status) is not int
            or isinstance(exit_status, bool)
            or exit_status != 0
        ):
            return f"{command} is not a zero-exit PASS"
        if result.get("source_set_sha256") != source_set_sha256:
            return f"{command} is bound to a stale source set"
        if result.get("test_names_sha256") != test_names_sha256:
            return f"{command} is bound to a stale test list"
        if (
            result.get("validated_commit") != revision
            or result.get("validated_tree") != tree
        ):
            return f"{command} Git binding differs"
        if result.get("execution_profile_sha256") != execution_profile_sha256:
            return f"{command} execution-profile binding differs"
        if index < len(TEST_LIST_CRATES):
            passed = result.get("passed_tests")
            if (
                not isinstance(passed, list)
                or any(not isinstance(name, str) or not name for name in passed)
                or passed != sorted(set(passed))
            ):
                return f"{command} passed-test vocabulary is not sorted and unique"
            if result.get("passed_tests_sha256") != canonical_json_sha256(passed):
                return f"{command} passed-test digest differs"
            passed_by_crate[TEST_LIST_CRATES[index]] = passed
        duration = result.get("duration_seconds")
        if (
            not isinstance(duration, (int, float))
            or isinstance(duration, bool)
            or not math.isfinite(duration)
            or duration < 0
        ):
            return f"{command} lacks a valid duration"
        if result.get("skipped_checks") != []:
            return f"{command} reports skipped checks"
        expected_log = validation_log_relative("tier2", index + 1, command)
        if problem := validation_log_problem(
            result,
            command,
            expected_log,
            used_logs,
            verify_logs,
            execution_profile_sha256,
            derive="passed" if index < len(TEST_LIST_CRATES) else None,
        ):
            return problem
    for test, crate in test_owners.items():
        qualified = qualified_tests[test]
        if qualified not in passed_by_crate[crate]:
            return (
                f"mapped test {test} did not finish as exact {qualified} ... ok "
                f"in the {crate} native lib harness"
            )
    return None


def require_execution_evidence(
    evidence: dict[str, object],
    tests: list[str],
    test_owners: dict[str, str],
    qualified_tests: dict[str, str],
) -> tuple[str, str]:
    validation = evidence.get("validation")
    if not isinstance(validation, dict):
        fail(
            "closeout execution evidence is missing or stale: validation is not an object"
        )
    revision = validation.get("validated_commit")
    if (
        not isinstance(revision, str)
        or re.fullmatch(r"[0-9a-f]{40,64}", revision) is None
    ):
        fail("closeout execution evidence is missing or stale: commit is malformed")
    inputs = commit_input_hashes(revision)
    problem = execution_binding_problem(
        validation, tests, test_owners, qualified_tests, inputs
    )
    if problem is not None:
        fail(f"closeout execution evidence is missing or stale: {problem}")
    source_set_sha256 = validation["source_set_sha256"]
    validated_commit = validation["validated_commit"]
    assert isinstance(source_set_sha256, str)
    assert isinstance(validated_commit, str)
    return source_set_sha256, validated_commit


def allowed_test_sources(row_id: str) -> tuple[str, ...]:
    store = "crates/sley-store/src/lib.rs"
    txn = "crates/sley-txn/src/repository.rs"
    refs = "crates/sley-repo/src/refs.rs"
    gc = "crates/sley-repo/src/gc.rs"
    if row_id.startswith(("OBJ-", "OLAY-")) or row_id in {"COR-01", "LIMIT-01"}:
        return (store,)
    if row_id.startswith(("GCW-", "GC-")) or row_id in {
        "COR-08",
        "GUARD-05",
        "GUARD-06",
    }:
        return (gc,)
    if row_id.startswith(("RLAY-", "REF-")) or row_id in {
        "COR-04",
        "COR-05",
        "COR-07",
        "GUARD-03",
        "GUARD-04",
    }:
        return (refs,)
    if row_id == "LIMIT-03":
        return (refs, txn)
    if row_id.startswith("CROSS-"):
        return (refs, txn)
    if row_id.startswith("ANC-"):
        return (txn,) if row_id in {"ANC-01", "ANC-03", "ANC-04", "ANC-07"} else (refs,)
    return (txn,)


def has_preceding_code_attribute(source: str, mask: list[bool], start: int) -> bool:
    cursor = start - 1
    while cursor >= 0 and (source[cursor].isspace() or not mask[cursor]):
        cursor -= 1
    if cursor < 0 or source[cursor] != "]":
        return False
    depth = 1
    cursor -= 1
    while cursor >= 0:
        if not mask[cursor]:
            cursor -= 1
            continue
        if source[cursor] == "]":
            depth += 1
        elif source[cursor] == "[":
            depth -= 1
            if depth == 0:
                prefix = cursor - 1
                while prefix >= 0 and (source[prefix].isspace() or not mask[prefix]):
                    prefix -= 1
                return prefix >= 0 and source[prefix] == "#" and mask[prefix]
        cursor -= 1
    return False


def brace_depth_at(source: str, mask: list[bool], end: int) -> int:
    depth = 0
    for index in range(end):
        if not mask[index]:
            continue
        if source[index] == "{":
            depth += 1
        elif source[index] == "}":
            depth -= 1
            if depth < 0:
                return -1
    return depth


def exact_test_module_range(source: str, mask: list[bool]) -> tuple[int, int] | None:
    pattern = re.compile(r"(?P<attrs>(?:#\[[^\]]+\]\s*)+)mod\s+tests\s*\{")
    ranges: list[tuple[int, int]] = []
    for match in pattern.finditer(source):
        attrs_start = match.start("attrs")
        mod_start = source.find("mod", match.end("attrs"), match.end())
        opening = source.rfind("{", match.start(), match.end())
        if (
            mod_start < 0
            or opening < 0
            or not all(mask[attrs_start : match.end()])
            or has_preceding_code_attribute(source, mask, attrs_start)
            or re.sub(r"\s+", "", match["attrs"]) != "#[cfg(test)]"
            or brace_depth_at(source, mask, mod_start) != 0
        ):
            continue
        closing = matching_delimiter(source, mask, opening, "{", "}")
        if closing is not None:
            ranges.append((opening, closing))
    return ranges[0] if len(ranges) == 1 else None


def rust_function_body_opening(
    source: str,
    mask: list[bool],
    parameter_opening: int,
    limit: int,
) -> int | None:
    parameter_closing = matching_delimiter(source, mask, parameter_opening, "(", ")")
    if parameter_closing is None or parameter_closing >= limit:
        return None
    round_depth = square_depth = angle_depth = 0
    cursor = parameter_closing + 1
    while cursor < limit:
        if not mask[cursor]:
            cursor += 1
            continue
        character = source[cursor]
        if character == "(":
            round_depth += 1
        elif character == ")":
            if round_depth == 0:
                return None
            round_depth -= 1
        elif character == "[":
            square_depth += 1
        elif character == "]":
            if square_depth == 0:
                return None
            square_depth -= 1
        elif character == "<":
            angle_depth += 1
        elif (
            character == ">"
            and angle_depth
            and (cursor == 0 or source[cursor - 1] not in "-=")
        ):
            angle_depth -= 1
        elif character == "{":
            if round_depth == square_depth == angle_depth == 0:
                return cursor
            closing = matching_delimiter(source, mask, cursor, "{", "}")
            if closing is None or closing >= limit:
                return None
            cursor = closing
        elif character == ";" and round_depth == square_depth == angle_depth == 0:
            return None
        cursor += 1
    return None


def exact_test_definition(source: str, name: str) -> tuple[str, str] | None:
    mask = rust_code_mask(source)
    module_range = exact_test_module_range(source, mask)
    if module_range is None:
        return None
    module_opening, module_closing = module_range
    pattern = re.compile(rf"(?P<attrs>(?:#\[[^\]]+\]\s*)+)fn\s+{re.escape(name)}\s*\(")
    definitions: list[tuple[str, str]] = []
    for match in pattern.finditer(source):
        fn_start = source.find("fn", match.end("attrs"), match.end())
        if (
            fn_start < 0
            or not (module_opening < match.start("attrs") < module_closing)
            or not all(mask[match.start("attrs") : match.end()])
            or not all(mask[fn_start : fn_start + 2])
            or has_preceding_code_attribute(source, mask, match.start("attrs"))
            or brace_depth_at(source, mask, fn_start) != 1
        ):
            continue
        attrs = match["attrs"]
        if re.sub(r"\s+", "", attrs) != "#[test]":
            continue
        parameter_opening = source.rfind("(", fn_start, match.end())
        if parameter_opening < 0:
            continue
        opening = rust_function_body_opening(
            source,
            mask,
            parameter_opening,
            module_closing,
        )
        if opening is None:
            continue
        closing = matching_delimiter(source, mask, opening, "{", "}")
        if closing is None or closing >= module_closing:
            continue
        definitions.append((source[opening + 1 : closing], f"tests::{name}"))
    return definitions[0] if len(definitions) == 1 else None


def exact_test_body(source: str, name: str) -> str | None:
    definition = exact_test_definition(source, name)
    return None if definition is None else definition[0]


def code_contains_snippet(source: str, snippet: str) -> bool:
    mask = rust_code_mask(source)
    offset = len(snippet) - len(snippet.lstrip())
    search_from = 0
    while (found := source.find(snippet, search_from)) >= 0:
        code_start = found + offset
        if code_start < len(mask) and mask[code_start]:
            return True
        search_from = found + 1
    return False


def delimiter_depth_at(source: str, end: int) -> tuple[int, int, int]:
    projected = rust_code_projection(source)
    round_depth = square_depth = brace_depth = 0
    for character in projected[:end]:
        if character == "(":
            round_depth += 1
        elif character == ")":
            round_depth -= 1
        elif character == "[":
            square_depth += 1
        elif character == "]":
            square_depth -= 1
        elif character == "{":
            brace_depth += 1
        elif character == "}":
            brace_depth -= 1
    return round_depth, square_depth, brace_depth


def exact_direct_statement_starts(source: str, statement: str) -> tuple[int, ...]:
    projected = rust_code_projection(source)
    statement_projection = rust_code_projection(statement)
    leading = len(statement_projection) - len(statement_projection.lstrip())
    search_from = 0
    starts: list[int] = []
    while (found := source.find(statement, search_from)) >= 0:
        start = found + leading
        end = found + len(statement)
        if projected[found:end] != statement_projection:
            search_from = found + 1
            continue
        if delimiter_depth_at(source, start) != (0, 0, 0):
            search_from = found + 1
            continue
        cursor = start - 1
        while cursor >= 0 and projected[cursor].isspace():
            cursor -= 1
        if cursor >= 0 and projected[cursor] not in ";}":
            search_from = found + 1
            continue
        if not statement_projection.rstrip().endswith(";"):
            search_from = found + 1
            continue
        starts.append(found)
        search_from = end
    return tuple(starts)


def exact_direct_statement_present(source: str, statement: str) -> bool:
    return bool(exact_direct_statement_starts(source, statement))


def unsafe_mapped_test_macro_problem(source: str) -> str | None:
    projected = rust_code_projection(source)
    allowed = {
        "::core::assert",
        "::core::assert_eq",
        "::core::assert_ne",
        "::core::matches",
        "::std::assert",
        "::std::assert_eq",
        "::std::assert_ne",
        "::std::format",
        "::std::matches",
        "::std::vec",
    }
    for match in re.finditer(
        r"(?P<path>(?:::)?[A-Za-z_][A-Za-z0-9_]*(?:::[A-Za-z_][A-Za-z0-9_]*)*)\s*!",
        projected,
    ):
        path = match["path"]
        if path not in allowed:
            return path
    return None


def mapped_source_macro_authority_problem(source: str) -> str | None:
    projected = rust_code_projection(source)
    if re.search(r"\bmacro_rules\s*!", projected):
        return "macro_rules! definition"
    if re.search(r"#\s*\[\s*macro_export\b", projected):
        return "macro_export attribute"
    if re.search(
        r"\bmod\s+(?:r#)?(?:core|std)\b",
        projected,
    ):
        return "local core/std module"
    if re.search(
        rf"\bextern\s+crate\s+{RUST_IDENTIFIER}\s+as\s+(?:r#)?(?:core|std)\b",
        projected,
    ):
        return "extern-crate core/std alias"
    for use in re.finditer(
        r"\b(?:pub(?:\([^)]*\))?\s+)?use\s+(?P<body>.*?);", projected, re.DOTALL
    ):
        body = use["body"]
        if re.search(r"\bas\s+(?:r#)?(?:core|std)\b", body):
            return "use core/std alias"
        if re.search(r"::\s*(?:r#)?(?:core|std)\s*(?:,|\}|$)", body):
            return "use-bound core/std namespace"
        if re.search(r"\{[^}]*\b(?:r#)?(?:core|std)\b[^}]*\}", body):
            return "brace-imported core/std namespace"
        if "*" in body and normalize_rust_tokens(body) not in {
            "super::*",
            "gc::*",
            "refs::*",
        }:
            return "unbound glob macro namespace"
    return None


def mapped_source_process_authority_problem(source: str) -> str | None:
    projected = rust_code_projection(source)
    termination_identifiers = (
        "exit",
        "abort",
        "exec",
        "_exit",
        "quick_exit",
        "exit_group",
        "ExitProcess",
        "TerminateProcess",
    )
    for identifier in termination_identifiers:
        if re.search(rf"\b(?:r#)?{re.escape(identifier)}\b", projected):
            return f"process termination or replacement token {identifier}"
    return None


def mapped_source_raw_output_authority_problem(source: str) -> str | None:
    projected = rust_code_projection(source)
    if re.search(r"\b(?:std\s*::\s*)?io\s*::\s*(?:stdout|stderr)\s*\(", projected):
        return "raw stdout/stderr handle"
    if re.search(r"\b(?:from_raw_fd|borrow_raw|as_raw_fd|into_raw_fd)\s*\(", projected):
        return "raw file-descriptor authority"
    for forbidden_path in (
        "/proc/self/fd/",
        "/proc/thread-self/fd/",
        "/dev/fd/",
        "/dev/stdout",
        "/dev/stderr",
    ):
        if forbidden_path in source:
            return "raw stdout/stderr path"
    return None


def mapped_source_ffi_authority_problem(source: str) -> str | None:
    projected = rust_code_projection(source)
    if re.search(r"\b(?:r#)?unsafe\b", projected):
        return "unsafe code authority"
    if re.search(r"\bextern(?:\s+\"[^\"]+\")?\s*\{", projected):
        return "foreign-block authority"
    for identifier in (
        "link_name",
        "link_ordinal",
        "no_mangle",
        "export_name",
        "link_section",
        "global_asm",
        "asm",
    ):
        if re.search(rf"\b(?:r#)?{re.escape(identifier)}\b", projected):
            return f"ABI/linkage authority {identifier}"
    return None


def mapped_test_raw_output_authority_problem(source: str) -> str | None:
    if problem := mapped_source_raw_output_authority_problem(source):
        return problem
    if re.search(
        r"\b(?:print|println|eprint|eprintln)\s*!", rust_code_projection(source)
    ):
        return "direct stdout/stderr macro"
    return None


def code_contains_token(source: str, token: str) -> bool:
    mask = rust_code_mask(source)
    for match in re.finditer(rf"\b{re.escape(token)}\b", source):
        if all(mask[match.start() : match.end()]):
            return True
    return False


def mapped_test_control_flow_problem(source: str) -> str | None:
    if code_contains_token(source, "return"):
        return "an early-return path"
    if "?" in rust_code_projection(source):
        return "a question-mark early-exit path"
    if problem := mapped_source_process_authority_problem(source):
        return problem
    if problem := mapped_test_raw_output_authority_problem(source):
        return problem
    return None


def code_only_normalized(source: str) -> str:
    mask = rust_code_mask(source)
    return re.sub(
        r"\s+",
        "",
        "".join(
            character if mask[index] else " " for index, character in enumerate(source)
        ),
    )


def exact_assert_eq_operands(assertion: str) -> tuple[str, str] | None:
    mask = rust_code_mask(assertion)
    match = re.match(r"^\s*::core::assert_eq\s*!\s*\(", assertion)
    if match is None:
        return None
    opening = assertion.rfind("(", 0, match.end())
    if opening < 0 or not mask[opening]:
        return None
    closing = matching_delimiter(assertion, mask, opening, "(", ")")
    if closing is None or assertion[closing + 1 :].strip() != ";":
        return None
    parts: list[str] = []
    start = opening + 1
    round_depth = square_depth = brace_depth = 0
    for index in range(opening + 1, closing):
        if not mask[index]:
            continue
        character = assertion[index]
        if character == "(":
            round_depth += 1
        elif character == ")":
            round_depth -= 1
        elif character == "[":
            square_depth += 1
        elif character == "]":
            square_depth -= 1
        elif character == "{":
            brace_depth += 1
        elif character == "}":
            brace_depth -= 1
        elif (
            character == ","
            and round_depth == 0
            and square_depth == 0
            and brace_depth == 0
        ):
            parts.append(assertion[start:index].strip())
            start = index + 1
        if min(round_depth, square_depth, brace_depth) < 0:
            return None
    parts.append(assertion[start:closing].strip())
    if len(parts) != 2 or any(not part for part in parts):
        return None
    return parts[0], parts[1]


def exact_comparison_assertion(
    assertion: str,
) -> tuple[str, tuple[str, str]] | None:
    for macro in ("assert_eq", "assert_ne"):
        match = re.match(rf"^(\s*::core::){macro}(\s*!\s*\()", assertion)
        if match is None:
            continue
        canonical = (
            assertion[: match.start()]
            + match.group(1)
            + "assert_eq"
            + match.group(2)
            + assertion[match.end() :]
        )
        operands = exact_assert_eq_operands(canonical)
        if operands is not None:
            return macro, operands
    return None


def exact_assert_predicate(assertion: str) -> str | None:
    mask = rust_code_mask(assertion)
    match = re.match(r"^\s*::core::assert\s*!\s*\(", assertion)
    if match is None:
        return None
    opening = assertion.rfind("(", 0, match.end())
    if opening < 0 or not mask[opening]:
        return None
    closing = matching_delimiter(assertion, mask, opening, "(", ")")
    if closing is None or assertion[closing + 1 :].strip() != ";":
        return None
    predicate = assertion[opening + 1 : closing].strip()
    if not predicate:
        return None
    return code_only_normalized(predicate)


def exact_value_assertion_problem(
    assertion: object,
    field: str,
    expected: bool | int | str,
) -> str | None:
    if not isinstance(assertion, str):
        return "mapped assertion is not text"
    if type(expected) not in {bool, int, str}:
        return "semantic value is not an exact bool, integer, or string"
    normalized_field = normalize_rust_tokens(field)
    if isinstance(expected, bool):
        predicate = exact_assert_predicate(assertion)
        expected_predicate = normalized_field if expected else f"!{normalized_field}"
        if predicate == expected_predicate:
            return None
    operands = exact_assert_eq_operands(assertion)
    if operands is None:
        return (
            "mapped assertion is not an exact field predicate or two-operand assert_eq!"
        )
    literal = json.dumps(expected, ensure_ascii=False)
    if operands[0].strip() == literal:
        claimed = operands[1]
    elif operands[1].strip() == literal:
        claimed = operands[0]
    else:
        return "expected value is not an exact equality operand"
    normalized_claim = code_only_normalized(claimed)
    allowed_claims = {normalized_field}
    if isinstance(expected, str):
        allowed_claims.update(
            {f"{normalized_field}.code()", f"{normalized_field}.symbol()"}
        )
    if normalized_claim not in allowed_claims:
        return "semantic field is not the exact compared value or code projection"
    return None


def exact_result_assertion_problem(
    assertion: object,
    field: str,
    expected: str,
    *,
    require_projection: bool,
) -> str | None:
    if not isinstance(assertion, str):
        return "mapped assertion is not text"
    operands = exact_assert_eq_operands(assertion)
    if operands is None:
        return "mapped assertion is not an exact two-operand assert_eq!"
    literal = json.dumps(expected)
    if operands[0].strip() == literal:
        claimed = operands[1]
    elif operands[1].strip() == literal:
        claimed = operands[0]
    else:
        return "exact symbolic result is not an equality operand"
    normalized = code_only_normalized(claimed)
    expected_claims = {field}
    if require_projection:
        expected_claims = {f"{field}.code()", f"{field}.symbol()"}
    if normalized not in expected_claims:
        return "result field is not the exact compared value or error-code projection"
    return None


def require_exact_result_assertion(
    label: str,
    entry: dict[str, object],
    field: str,
    expected: str,
    *,
    require_projection: bool,
) -> None:
    semantic = entry.get("semantic_assertions")
    if not isinstance(semantic, dict):
        fail(f"{label} lacks semantic assertion mapping")
    problem = exact_result_assertion_problem(
        semantic.get(field), field, expected, require_projection=require_projection
    )
    if problem is not None:
        fail(f"{label} exact {field} assertion differs: {problem}")


def require_exact_limit_default_assertion(
    row_id: str, subcase_id: str, entry: dict[str, object]
) -> None:
    _owner, constant, expected = LIMIT_DEFAULTS[row_id][subcase_id]
    if not exact_json_scalar_equal(entry.get("frozen_default"), expected):
        fail(f"{row_id}/{subcase_id} frozen default differs")
    semantic = entry.get("semantic_assertions")
    if not isinstance(semantic, dict):
        fail(f"{row_id}/{subcase_id} lacks semantic assertion mapping")
    assertion = semantic.get("frozen_default")
    if not isinstance(assertion, str):
        fail(f"{row_id}/{subcase_id} frozen-default assertion is not text")
    operands = exact_assert_eq_operands(assertion)
    expected_literal = f"{expected:_}"
    if operands is None or {
        code_only_normalized(operands[0]),
        code_only_normalized(operands[1]),
    } != {constant, expected_literal}:
        fail(
            f"{row_id}/{subcase_id} does not compare {constant} to "
            f"{expected_literal} exactly"
        )


def is_transaction_owned_branch_limit(row_id: str, subcase_id: str) -> bool:
    return row_id == "LIMIT-03" and (
        subcase_id in TRANSACTION_OWNED_BRANCH_LIMIT_SUBCASES
    )


def limit_plus_one_expected_result(row_id: str, subcase_id: str) -> str:
    if is_transaction_owned_branch_limit(row_id, subcase_id):
        return "RecoveryAncestryError::LimitExceeded"
    return LIMIT_CODES[row_id]


def require_exact_limit_error_assertion(
    row_id: str,
    subcase_id: str,
    entry: dict[str, object],
    expected_result: str,
) -> None:
    label = f"{row_id}/{subcase_id}"
    semantic = entry.get("semantic_assertions")
    if not isinstance(semantic, dict):
        fail(f"{label} lacks semantic assertion mapping")
    assertion = semantic.get("limit_plus_one_code")
    if not isinstance(assertion, str):
        fail(f"{label} limit assertion is not text")
    if is_transaction_owned_branch_limit(row_id, subcase_id):
        predicate = exact_assert_predicate(assertion)
        expected = code_only_normalized(
            "::core::matches!(&limit_plus_one_error, "
            "super::RecoveryAncestryError::LimitExceeded)"
        )
        if predicate != expected:
            fail(f"{label} does not match the exact transaction-owned limit variant")
        return
    projection = {
        "LIMIT-01": "limit_plus_one_error.symbol()",
        "LIMIT-02": "limit_plus_one_error.code()",
        "LIMIT-03": "limit_plus_one_error.code()",
    }[row_id]
    expected_assertion = (
        f"::core::assert_eq!({projection}, {json.dumps(expected_result)});"
    )
    if normalize_rust_tokens(assertion) != normalize_rust_tokens(expected_assertion):
        fail(f"{label} limit error projection differs")


def limit_operation_kind(row_id: str, subcase_id: str) -> str:
    if row_id == "LIMIT-01":
        return "store_recovery"
    if row_id == "LIMIT-02":
        return "transaction_recovery"
    if is_transaction_owned_branch_limit(row_id, subcase_id):
        return "ancestry_verifier"
    if row_id == "LIMIT-03":
        return "ref_recovery"
    fail(f"{row_id}/{subcase_id} lacks a limit operation kind")


def limit_operation_call(kind: str, prefix: str) -> str:
    calls = {
        "store_recovery": (
            f"{prefix}_store.recover_staged_with_limits({prefix}_limits)"
        ),
        "transaction_recovery": (
            f"{prefix}_repository.recover_with_maintenance_and_limits("
            f"&{prefix}_maintenance, {prefix}_recovery_limits, "
            f"{prefix}_ancestry_limits)"
        ),
        "ancestry_verifier": (
            f"{prefix}_repository.verify_recovery_ancestries_with_limits("
            f"&{prefix}_maintenance, &{prefix}_requests, {prefix}_limits)"
        ),
        "ref_recovery": (
            f"{prefix}_branch_repository.recover_refs_with_maintenance_and_limits("
            f"&{prefix}_maintenance, {prefix}_limits)"
        ),
    }
    try:
        return calls[kind]
    except KeyError:
        fail(f"unknown limit operation kind {kind!r}")


def limit_operation_root(kind: str, prefix: str) -> str:
    roots = {
        "store_recovery": f"{prefix}_store.root()",
        "transaction_recovery": f"{prefix}_repository.root()",
        "ancestry_verifier": f"{prefix}_repository.root()",
        "ref_recovery": f"{prefix}_branch_repository.root()",
    }
    try:
        return roots[kind]
    except KeyError:
        fail(f"unknown limit operation kind {kind!r}")


def limit_operation_binding_problem(
    body: str,
    relative: str,
    row_id: str,
    subcase_id: str,
    semantic: dict[str, object],
) -> str | None:
    kind = limit_operation_kind(row_id, subcase_id)
    exact_call = limit_operation_call(kind, "exact")
    plus_call = limit_operation_call(kind, "plus_one")
    exact_result = exact_snapshot_binding_range(
        body,
        "exact_result",
        f"let exact_result = {exact_call};",
    )
    plus_result = exact_snapshot_binding_range(
        body,
        "plus_one_result",
        f"let plus_one_result = {plus_call};",
    )
    if exact_result is None or plus_result is None:
        return "exact-limit and limit-plus-one operations are not bound exactly"
    normalized_body = code_only_normalized(body)
    if normalized_body.count(code_only_normalized(exact_call)) != 1:
        return "exact-limit operation is not invoked exactly once"
    if normalized_body.count(code_only_normalized(plus_call)) != 1:
        return "limit-plus-one operation is not invoked exactly once"
    if exact_result[1] > plus_result[0]:
        return "exact-limit operation does not precede limit-plus-one"

    exact_root = exact_snapshot_binding_range(
        body,
        "exact_owner_root",
        f"let exact_owner_root = {limit_operation_root(kind, 'exact')};",
    )
    plus_root = exact_snapshot_binding_range(
        body,
        "plus_one_owner_root",
        f"let plus_one_owner_root = {limit_operation_root(kind, 'plus_one')};",
    )
    if exact_root is None or plus_root is None:
        return "limit fixture roots are not bound to their operation receivers"
    distinct = "::core::assert_ne!(exact_owner_root, plus_one_owner_root);"
    distinct_starts = exact_direct_statement_starts(body, distinct)
    if len(distinct_starts) != 1 or distinct_starts[0] >= exact_result[0]:
        return "limit fixtures are not proven to use distinct roots"

    tree_helper = snapshot_helper_path(relative, "exact_tree_snapshot")
    before_tree = exact_snapshot_binding_range(
        body,
        "plus_one_owner_tree_before_snapshot",
        (
            "let plus_one_owner_tree_before_snapshot = "
            f"{tree_helper}(plus_one_owner_root);"
        ),
    )
    after_tree = exact_snapshot_binding_range(
        body,
        "plus_one_owner_tree_after_snapshot",
        (
            "let plus_one_owner_tree_after_snapshot = "
            f"{tree_helper}(plus_one_owner_root);"
        ),
    )
    if before_tree is None or after_tree is None:
        return "limit-plus-one owner snapshots are not exact"
    if not (plus_root[1] <= before_tree[0] and before_tree[1] <= plus_result[0]):
        return "limit-plus-one before snapshot does not precede its operation"

    errors = top_level_let_statement_ranges(body, "limit_plus_one_error")
    expected_error = (
        "let limit_plus_one_error = plus_one_result.expect_err("
        '"expected limit-plus-one error");'
    )
    if len(errors) != 1 or normalize_rust_tokens(errors[0][2]) != (
        normalize_rust_tokens(expected_error)
    ):
        return "limit-plus-one error is not extracted from its operation"
    error_start, error_end, _statement = errors[0]
    if error_start <= plus_result[1]:
        return "limit-plus-one error extraction does not follow its operation"
    if after_tree[0] < error_end:
        return "limit-plus-one after snapshot precedes error extraction"
    if rust_code_projection(body[error_end : after_tree[0]]).strip():
        return "limit-plus-one after snapshot is not immediate after extraction"

    expected_assertions = {
        "exact_limit_success": "::core::assert!(exact_result.is_ok());",
        "no_partial_report": "::core::assert!(plus_one_result.is_err());",
        "no_mutation": (
            "::core::assert_eq!(plus_one_owner_tree_before_snapshot, "
            "plus_one_owner_tree_after_snapshot);"
        ),
    }
    for field, expected_assertion in expected_assertions.items():
        assertion = semantic.get(field)
        if not isinstance(assertion, str) or normalize_rust_tokens(
            assertion
        ) != normalize_rust_tokens(expected_assertion):
            return f"{field} is not bound to the exact limit operation"
        starts = exact_direct_statement_starts(body, assertion)
        if len(starts) != 1:
            return f"{field} assertion is not one direct statement"
        if field == "exact_limit_success" and starts[0] < exact_result[1]:
            return "exact-limit success assertion precedes its operation"
        if field == "no_partial_report" and not (
            plus_result[1] <= starts[0] < error_start
        ):
            return "no-partial-report assertion does not bind limit-plus-one result"
        if field == "no_mutation" and starts[0] < after_tree[1]:
            return "no-mutation assertion precedes the after snapshot"

    limit_assertion = semantic.get("limit_plus_one_code")
    if not isinstance(limit_assertion, str):
        return "limit-plus-one assertion is not text"
    limit_starts = exact_direct_statement_starts(body, limit_assertion)
    if len(limit_starts) != 1 or limit_starts[0] < after_tree[1]:
        return "limit-plus-one assertion does not follow error and snapshot binding"
    if re.search(
        r"\b(?:restore|restorer|restoration)\b|"
        r"(?:\b(?:std\s*::\s*)?thread\s*::\s*spawn\b|"
        r"\b(?:std\s*::\s*)?process\s*::\s*Command\s*::\s*new\b)",
        rust_code_projection(body),
    ):
        return "limit test contains restoration authority"
    return None


def require_limit_operation_evidence(
    row_id: str,
    subcase_id: str,
    entry: dict[str, object],
    relative: str,
    source: str,
) -> None:
    tests = entry.get("tests")
    semantic = entry.get("semantic_assertions")
    if not isinstance(tests, list) or len(tests) != 1 or not isinstance(tests[0], str):
        fail(f"{row_id}/{subcase_id} lacks one exact limit operation test")
    if not isinstance(semantic, dict):
        fail(f"{row_id}/{subcase_id} lacks limit semantic assertions")
    definition = exact_test_definition(source, tests[0])
    if definition is None:
        fail(f"{row_id}/{subcase_id} cannot isolate its limit operation test")
    if problem := limit_operation_binding_problem(
        definition[0],
        relative,
        row_id,
        subcase_id,
        semantic,
    ):
        fail(f"{row_id}/{subcase_id} limit operation binding differs: {problem}")


def require_checker_negative_controls() -> None:
    def test_module(items: str) -> str:
        return f"#[cfg(test)]\nmod tests {{\n{items}\n}}\n"

    freeze_hash_fields = (
        "matrix_rows_sha256",
        "spec_sha256",
        "adr_sha256",
        "checker_sha256",
        "checker_contract_sha256",
        "runner_sha256",
    )
    freeze_hashes = {
        field: f"{index:x}" * 64
        for index, field in enumerate(freeze_hash_fields, start=1)
    }
    exact_freeze_inputs = {"matrix_rows": len(MATRIX_IDS), **freeze_hashes}
    if problem := freeze_deterministic_inputs_problem(
        exact_freeze_inputs,
        freeze_hashes,
        len(MATRIX_IDS),
    ):
        fail(f"checker self-test rejected exact freeze inputs: {problem}")
    missing_freeze_count = dict(exact_freeze_inputs)
    missing_freeze_count.pop("matrix_rows")
    boolean_freeze_count = dict(exact_freeze_inputs)
    boolean_freeze_count["matrix_rows"] = True
    stale_freeze_hash = dict(exact_freeze_inputs)
    stale_freeze_hash["runner_sha256"] = "f" * 64
    reordered_freeze_inputs = {
        "matrix_rows": len(MATRIX_IDS),
        "spec_sha256": freeze_hashes["spec_sha256"],
        "matrix_rows_sha256": freeze_hashes["matrix_rows_sha256"],
        **{
            field: freeze_hashes[field]
            for field in freeze_hash_fields[2:]
        },
    }
    extra_freeze_input = dict(exact_freeze_inputs)
    extra_freeze_input["extra"] = "forbidden"
    for hostile_inputs in (
        missing_freeze_count,
        boolean_freeze_count,
        stale_freeze_hash,
        reordered_freeze_inputs,
        extra_freeze_input,
    ):
        if (
            freeze_deterministic_inputs_problem(
                hostile_inputs,
                freeze_hashes,
                len(MATRIX_IDS),
            )
            is None
        ):
            fail("checker self-test accepted hostile freeze inputs")

    exact_tier_2_spec = (
        "Tier 2 for S20-530 is:\n\n```text\n" + "\n".join(TIER_2_COMMANDS) + "\n```\n"
    )
    if tier_2_command_contract_problem(exact_tier_2_spec) is not None:
        fail("checker self-test rejected exact direct Tier 2 commands")
    old_wrapper_commands = exact_tier_2_spec.replace(
        "cargo test --workspace --locked",
        "make core",
        1,
    )
    if tier_2_command_contract_problem(old_wrapper_commands) is None:
        fail("checker self-test accepted mutable Make Tier 2 indirection")

    exact_fixture_digest_spec = (
        "The checker owns one immutable `CORRUPTION_FIXTURE_SPECS` registry "
        "in the exact\n235-leaf order. Its SHA-256 is\n"
        f"`{CORRUPTION_FIXTURE_SPECS_SHA256}`.\n"
    )
    if corruption_fixture_spec_digest_problem(exact_fixture_digest_spec) is not None:
        fail("checker self-test rejected the exact fixture-registry spec digest")
    stale_fixture_digest_spec = exact_fixture_digest_spec.replace(
        CORRUPTION_FIXTURE_SPECS_SHA256,
        "0" * 64,
    )
    if corruption_fixture_spec_digest_problem(stale_fixture_digest_spec) is None:
        fail("checker self-test accepted a stale fixture-registry spec digest")

    exact_limit_event_digest_spec = (
        "The checker owns one immutable `LIMIT_EVENT_SPECS` registry "
        "in the exact\n30-event order. It binds 37 unique qualified fields "
        "through 42 exact field-event\nmemberships. Its SHA-256 is\n"
        f"`{LIMIT_EVENT_SPECS_SHA256}`.\n"
    )
    if limit_event_spec_digest_problem(exact_limit_event_digest_spec) is not None:
        fail("checker self-test rejected the exact limit-event spec digest")
    stale_limit_event_digest_spec = exact_limit_event_digest_spec.replace(
        LIMIT_EVENT_SPECS_SHA256,
        "0" * 64,
    )
    if limit_event_spec_digest_problem(stale_limit_event_digest_spec) is None:
        fail("checker self-test accepted a stale limit-event spec digest")

    exact_provenance_digest_spec = (
        "The checker owns one immutable `RECOVERY_PROVENANCE_SPECS` registry "
        "in the\nexact 10-case order. Its SHA-256 is\n"
        f"`{RECOVERY_PROVENANCE_SPECS_SHA256}`.\n"
    )
    if (
        recovery_provenance_spec_digest_problem(exact_provenance_digest_spec)
        is not None
    ):
        fail("checker self-test rejected the exact provenance spec digest")
    stale_provenance_digest_spec = exact_provenance_digest_spec.replace(
        RECOVERY_PROVENANCE_SPECS_SHA256,
        "0" * 64,
    )
    if (
        recovery_provenance_spec_digest_problem(stale_provenance_digest_spec)
        is None
    ):
        fail("checker self-test accepted a stale provenance spec digest")

    exact_multifault_digest_spec = (
        "The checker owns one immutable `MULTIFAULT_OVERLAY_REGISTRY` "
        "in the exact\n15-case order. Its SHA-256 is\n"
        f"`{MULTIFAULT_OVERLAY_REGISTRY_SHA256}`.\n"
    )
    if multifault_overlay_spec_digest_problem(exact_multifault_digest_spec) is not None:
        fail("checker self-test rejected the exact multifault-overlay spec digest")
    stale_multifault_digest_spec = exact_multifault_digest_spec.replace(
        MULTIFAULT_OVERLAY_REGISTRY_SHA256,
        "0" * 64,
    )
    if multifault_overlay_spec_digest_problem(stale_multifault_digest_spec) is None:
        fail("checker self-test accepted a stale multifault-overlay spec digest")

    if strict_json_object(b'{"outer":{"value":1}}', "exact-json") != {
        "outer": {"value": 1}
    }:
        fail("checker self-test rejected strict JSON")
    for hostile_json in (
        b'{"contract":"first","contract":"last"}',
        b'{"outer":{"value":1,"value":2}}',
        b'{"duration_seconds":NaN}',
        b'{"duration_seconds":Infinity}',
        b'{"duration_seconds":-Infinity}',
        b'{"duration_seconds":1e999}',
    ):
        try:
            strict_json_object(hostile_json, "hostile-json")
        except ValueError:
            pass
        else:
            fail("checker self-test accepted ambiguous or non-finite JSON")

    with tempfile.TemporaryDirectory(prefix=".s20-530-json-", dir=ROOT) as name:
        fixture_root = Path(name)
        safe_parent = fixture_root / "safe"
        safe_parent.mkdir(mode=0o700)
        safe_file = safe_parent / "evidence.json"
        safe_file.write_bytes(b'{"result":"PASS"}')
        safe_file.chmod(0o600)
        if read_bounded_repository_file(safe_file, root=fixture_root) != (
            b'{"result":"PASS"}'
        ):
            fail("checker self-test rejected a safe bounded JSON file")
        try:
            read_bounded_repository_file(safe_file, root=fixture_root, size_limit=4)
        except ValueError:
            pass
        else:
            fail("checker self-test accepted an oversized JSON file")
        safe_file.chmod(0o700)
        try:
            read_bounded_repository_file(safe_file, root=fixture_root)
        except ValueError:
            pass
        else:
            fail("checker self-test accepted executable JSON")
        safe_file.chmod(0o602)
        try:
            read_bounded_repository_file(safe_file, root=fixture_root)
        except ValueError:
            pass
        else:
            fail("checker self-test accepted world-writable JSON")
        safe_file.chmod(0o600)
        final_symlink = safe_parent / "final-link.json"
        final_symlink.symlink_to(safe_file.name)
        try:
            read_bounded_repository_file(final_symlink, root=fixture_root)
        except (OSError, ValueError):
            pass
        else:
            fail("checker self-test accepted a final JSON symlink")
        parent_symlink = fixture_root / "parent-link"
        parent_symlink.symlink_to(safe_parent.name, target_is_directory=True)
        try:
            read_bounded_repository_file(
                parent_symlink / safe_file.name,
                root=fixture_root,
            )
        except (OSError, ValueError):
            pass
        else:
            fail("checker self-test accepted an intermediate JSON symlink")

    if grouped_error_metadata_problem() is not None:
        fail("checker self-test rejected exact grouped error metadata")

    def clone_grouped_cases() -> dict[
        str,
        dict[str, tuple[tuple[str, str, str, tuple[str, ...]], ...]],
    ]:
        return {
            row_id: {group_id: tuple(leaves) for group_id, leaves in groups.items()}
            for row_id, groups in GROUPED_ERROR_CASES.items()
        }

    def grouped_derivatives(
        cases: dict[
            str,
            dict[str, tuple[tuple[str, str, str, tuple[str, ...]], ...]],
        ],
    ) -> tuple[
        dict[tuple[str, str, str], tuple[str, str, tuple[str, ...]]],
        dict[str, frozenset[tuple[str, str, str]]],
        str,
    ]:
        specs = {
            (row_id, group_id, leaf_id): (code, variant, chain)
            for row_id, groups in cases.items()
            for group_id, leaves in groups.items()
            for leaf_id, code, variant, chain in leaves
        }
        operations = {
            "transaction_recovery": frozenset(
                ("COR-06", group_id, leaf_id)
                for group_id, leaves in cases["COR-06"].items()
                for leaf_id, _code, _variant, _chain in leaves
            ),
            "ref_recovery": frozenset(
                ("COR-07", group_id, leaf_id)
                for group_id, leaves in cases["COR-07"].items()
                for leaf_id, _code, _variant, _chain in leaves
            ),
        }
        return specs, operations, grouped_error_cases_sha256(cases)

    grouped_hostiles = []
    omitted = clone_grouped_cases()
    omitted["COR-06"]["head_checksum"] = omitted["COR-06"]["head_checksum"][1:]
    grouped_hostiles.append(omitted)
