    cycle_key_under_test = cycle_keys[0]
    cycle_entry = exact_multifault_entry(cycle_key_under_test)
    cycle_body = exact_multifault_body(cycle_key_under_test, cycle_entry)
    cycle_bindings = cycle_entry["m2_operation_bindings"]
    cycle_epoch_assertions = cycle_entry["m2_cycle_epoch_assertions"]
