    def gc_canary_fixture(
        row_id: str,
        subcase_id: str | None,
    ) -> dict[str, object]:
        kind = PREFLIGHT_CANARY_KINDS[(row_id, subcase_id, "gc_witness")]
        byte_assertion = (
            "::core::assert_eq!(gc_witness_before_snapshot, gc_witness_after_snapshot);"
        )
        kind_assertion = (
            "::core::assert_eq!(gc_witness_before_kind, gc_witness_after_kind);"
        )
        expected_kind_assertion = (
            f"::core::assert_eq!(gc_witness_before_kind, {json.dumps(kind)});"
        )
        fixture_assertion = PREFLIGHT_CANARY_FIXTURE_ASSERTIONS[
            (row_id, subcase_id, "gc_witness")
        ]
        tree_assertion = (
            "::core::assert_eq!(owner_tree_before_snapshot, owner_tree_after_snapshot);"
        )
        return {
            "assertions": [
                byte_assertion,
                kind_assertion,
                expected_kind_assertion,
                fixture_assertion,
                tree_assertion,
            ],
            "cleanup_canary_hashes": {
                "gc_witness_before_sha256": "a" * 64,
                "gc_witness_after_sha256": "a" * 64,
                "owner_tree_before_sha256": "b" * 64,
                "owner_tree_after_sha256": "b" * 64,
            },
            "cleanup_canary_kinds": {
                "gc_witness_before_kind": kind,
                "gc_witness_after_kind": kind,
            },
            "cleanup_canary_assertions": {
                "gc_witness_bytes": byte_assertion,
                "gc_witness_kind": kind_assertion,
                "gc_witness_expected_kind": expected_kind_assertion,
                "gc_witness_fixture": fixture_assertion,
                "owner_tree": tree_assertion,
            },
        }

