def main() -> None:
    require_evidence_metadata()
    require_frozen_test_authority()
    spec = SPEC.read_text(encoding="utf-8")
    adr = ADR.read_text(encoding="utf-8")
    require_contract(spec, adr)
    require_dependency_direction()

    summary = load_json(SUMMARY)
    package = summary.get("s20_530_crash_recovery")
    if not isinstance(package, dict):
        fail("machine summary lacks s20_530_crash_recovery")
    if package.get("contract") != str(SPEC.relative_to(ROOT)):
        fail("machine summary contract path differs")
    if package.get("adr") != str(ADR.relative_to(ROOT)):
        fail("machine summary ADR path differs")
    if not exact_json_scalar_equal(package.get("matrix_rows"), len(MATRIX_IDS)):
        fail("machine summary matrix count differs")
    if package.get("dependency_direction") != "sley-repo -> sley-txn -> sley-store":
        fail("machine summary dependency direction differs")
    complete = package.get("implementation_complete")
    if not isinstance(complete, bool):
        fail("implementation_complete must be a boolean")
    contract_set_sha256, _contract_reviews = require_freeze_evidence(package, complete)

    work_packages = WORK_PACKAGES.read_text(encoding="utf-8")
    require_text(work_packages, "| S20-530 |", "work-package table")
    require_text(work_packages, "100-row crash matrix", "work-package table")

    if complete is True:
        require_text(
            spec,
            "Status: S20-530 contract frozen; implementation state is tracked separately.",
            "crash-recovery spec",
        )
        require_implementation(package, contract_set_sha256)
    elif complete is False:
        require_text(
            spec,
            "Status: S20-530 contract frozen; implementation state is tracked separately.",
            "crash-recovery spec",
        )

    print(
        "S20-530 crash-recovery contract check: PASS "
        f"({len(MATRIX_IDS)} exact matrix rows; implementation_complete={complete})"
    )


if __name__ == "__main__":
    main()
